}

[[nodiscard]] std::uint64_t makeDeviceProgramFingerprint(
    const std::uint64_t worldFingerprint,
    const std::uint64_t metallibFingerprint,
    const std::uint64_t metallibByteCount,
    const RuntimeConfiguration& configuration
) noexcept {
    std::uint64_t hash = 14695981039346656037ull;
    hash = mixFingerprint(hash, worldFingerprint);
    hash = mixFingerprint(hash, NM_MATTER_ABI_VERSION);
    hash = detail::mixRuntimeExecutionPolicyFingerprint(
        hash, mixFingerprint);
    hash = mixFingerprint(hash, metallibFingerprint);
    hash = mixFingerprint(hash, metallibByteCount);
    hash = mixFingerprint(hash, configuration.captureEvents ? 1u : 0u);
    hash = mixFingerprint(hash, configuration.captureDiagnostics ? 1u : 0u);
    hash = mixFingerprint(hash, configuration.automaticIdentification ? 1u : 0u);
    hash = mixFingerprint(hash, configuration.adaptiveTransfer ? 1u : 0u);
    hash = mixFingerprint(hash, configuration.coupledCandidateCompensatedTranslation ? 1u : 0u);
    hash = mixFingerprint(hash, detail::hashBytes(
        configuration.humanJointEqualities.data(),
        configuration.humanJointEqualities.size_bytes()));
    hash = mixFingerprint(hash, detail::hashBytes(
        &configuration.humanEqualityDispatch, sizeof(configuration.humanEqualityDispatch)));
    hash = mixFingerprint(hash, configuration.humanEqualitySourceFingerprint);
    hash = mixFingerprint(hash, detail::hashBytes(configuration.humanJointLimits.data(),
        configuration.humanJointLimits.size_bytes()));
    hash = mixFingerprint(hash, detail::hashBytes(&configuration.humanLimitDispatch,
        sizeof(configuration.humanLimitDispatch)));
    hash = mixFingerprint(hash, configuration.humanLimitSourceFingerprint);
    hash = mixFingerprint(hash, detail::hashBytes(
        configuration.humanSupportContacts.data(),
        configuration.humanSupportContacts.size_bytes()));
    hash = mixFingerprint(hash, detail::hashBytes(
        configuration.humanSupportPointQueries.data(),
        configuration.humanSupportPointQueries.size_bytes()));
    hash = mixFingerprint(hash, detail::hashBytes(
        &configuration.humanSupportGroundPoint, sizeof(nm_float4)));
    hash = mixFingerprint(hash, detail::hashBytes(
        &configuration.humanSupportGroundNormal, sizeof(nm_float4)));
    // Preserve the device-program identity produced before prepared support
    // histories existed. An absent history is the legacy execution policy;
    // only an explicitly supplied payload extends that identity.
    hash = detail::mixPreparedSupportHistoryFingerprint(
        hash,
        configuration.humanSupportInitialHistories,
        mixFingerprint);
    return hash == 0u ? 1u : hash;
}

[[nodiscard]] std::uint64_t acceptedStateProofSourceFingerprint() noexcept {
    std::uint64_t hash = 14695981039346656037ull;
    hash = mixFingerprint(hash, 0x4e584d50524f4f46ull); // "NXMPROOF"
    hash = mixFingerprint(
        hash, detail::kAcceptedStateProofSchemaVersion);
    hash = mixFingerprint(
        hash, detail::kAcceptedStateProofManifestVersion);
    return hash == 0u ? 1u : hash;
}

[[nodiscard]] std::uint64_t makeAcceptedStateProofProgramFingerprint(
    const std::uint64_t executionFingerprint,
    const NMMatterDispatchGPU& dispatch,
    const std::uint32_t identificationDistributionCount,
    const std::uint32_t femNodeIncidenceStride,
    const std::uint32_t femNodeRangeStride,
    const std::uint64_t mujocoBytesPerEnvironmentCapacity,
    const std::uint32_t proofABIVersion,
    const std::uint64_t proofBytes
) noexcept {
    std::uint64_t hash = acceptedStateProofSourceFingerprint();
    hash = mixFingerprint(
        hash, proofABIVersion);
    hash = mixFingerprint(hash, proofBytes);
    hash = mixFingerprint(hash, executionFingerprint);
    hash = mixFingerprint(hash, dispatch.environmentCount);
    hash = mixFingerprint(hash, dispatch.objectCount);
    hash = mixFingerprint(hash, dispatch.parameterCount);
    hash = mixFingerprint(hash, dispatch.particleCount);
    hash = mixFingerprint(hash, dispatch.femNodeCount);
    hash = mixFingerprint(hash, dispatch.tetrahedronCount);
    hash = mixFingerprint(hash, dispatch.topologyNodeCapacity);
    hash = mixFingerprint(hash, dispatch.cohesiveFaceCount);
    hash = mixFingerprint(hash, dispatch.punctureChannelCount);
    hash = mixFingerprint(hash, dispatch.learnedWeightCount);
    hash = mixFingerprint(hash, dispatch.contactPairCount);
    hash = mixFingerprint(hash, dispatch.deformableContactCapacity);
    hash = mixFingerprint(hash, dispatch.rigidGeneralizedCapacity);
    hash = mixFingerprint(hash, dispatch.rigidProxyCount);
    hash = mixFingerprint(hash, dispatch.materialStateStride);
    hash = mixFingerprint(hash, identificationDistributionCount);
    hash = mixFingerprint(hash, femNodeIncidenceStride);
    hash = mixFingerprint(hash, femNodeRangeStride);
    hash = mixFingerprint(hash, mujocoBytesPerEnvironmentCapacity);
    return hash == 0u ? 1u : hash;
}

[[nodiscard]] NSUInteger checkedBytes(
    const std::size_t count,
    const std::size_t elementSize,
    bool& valid
) {
    if (count != 0u && elementSize >
        std::numeric_limits<std::size_t>::max() / count) {
        valid = false;
        return 0u;
    }
    const std::size_t bytes = count * elementSize;
    if (bytes > std::numeric_limits<NSUInteger>::max()) {
        valid = false;
        return 0u;
    }
    // Metal validates a typed device pointer against at least one complete
    // pointee even when the logical dispatch width is zero. A generic
    // 16-byte placeholder is therefore insufficient for empty bindings such
    // as NMParticleStateGPU (160 bytes), and validation correctly rejects the
    // command before the kernel's zero-work guard can run. Preserve the
    // logical zero count while allocating one fully typed sentinel.
    return static_cast<NSUInteger>(std::max({
        bytes,
        elementSize,
        std::size_t{16u},
    }));
}

struct RegionalRAPCaptureArray {
    std::string name;
    std::string dtype;
    std::vector<std::uint64_t> shape;
    std::uint64_t offset = 0u;
    std::uint64_t byteCount = 0u;
    std::uint64_t elementBytes = 0u;
    std::uint32_t sourceSlot = 0u;
    std::uint64_t sourceOffset = 0u;
};

struct RegionalRAPCaptureMetadata {
    std::uint32_t controlStep = 0u;
    std::uint32_t solverIteration = 0u;
    std::uint32_t physicsSubstep = 0u;
    std::uint32_t microtick = 0u;
    std::uint32_t microtickCount = 0u;
    std::uint32_t microGeneration = 0u;
    std::uint32_t environmentCount = 0u;
    std::uint32_t nodeCount = 0u;
    std::uint32_t tetrahedronCount = 0u;
    std::uint32_t modeCount = 0u;
    std::uint32_t materialStateStride = 0u;
    std::uint32_t tangentCacheUsed = 0u;
    std::uint32_t preconditionerSelector = 0u;
    std::uint32_t graphEnvironment = NM_INVALID_INDEX;
    std::uint32_t graphPatchCount = 0u;
    std::uint32_t graphPatchNodeCount = 0u;
    std::uint32_t graphDofCount = 0u;
    std::uint32_t graphMatrixFloatCount = 0u;
    std::uint32_t graphPivotCount = 0u;
    std::uint32_t graphLayoutChecksum = 0u;
    std::string graphSourceTopologySHA256;
    std::string graphSourceFreeMaskSHA256;
    std::string graphPotentialMaskSHA256;
    std::uint64_t linearizationGeneration = 0u;
    std::uint64_t worldFingerprint = 0u;
    std::uint64_t executionFingerprint = 0u;
    std::uint64_t deviceRegistryID = 0u;
    float timestepSeconds = 0.0f;
    std::string deviceName;
};

[[nodiscard]] std::string sha256Hex(const void* data, const std::size_t size) {
    unsigned char digest[CC_SHA256_DIGEST_LENGTH]{};
    if (size > std::numeric_limits<CC_LONG>::max()) return {};
    CC_SHA256(data, static_cast<CC_LONG>(size), digest);
    static constexpr char digits[] = "0123456789abcdef";
    std::string result;
    result.resize(CC_SHA256_DIGEST_LENGTH * 2u);
    for (std::size_t index = 0u; index < CC_SHA256_DIGEST_LENGTH; ++index) {
        result[2u * index] = digits[digest[index] >> 4u];
        result[2u * index + 1u] = digits[digest[index] & 0x0fu];
    }
    return result;
}

[[nodiscard]] std::string jsonQuoted(const std::string& value) {
    std::ostringstream output;
    output << '"';
    for (const unsigned char ch : value) {
        switch (ch) {
            case '"': output << "\\\""; break;
            case '\\': output << "\\\\"; break;
            case '\b': output << "\\b"; break;
            case '\f': output << "\\f"; break;
            case '\n': output << "\\n"; break;
            case '\r': output << "\\r"; break;
            case '\t': output << "\\t"; break;
            default:
                if (ch < 0x20u) {
                    output << "\\u00" << std::hex << std::setw(2)
                           << std::setfill('0') << static_cast<unsigned>(ch)
                           << std::dec << std::setfill(' ');
                } else {
                    output << static_cast<char>(ch);
                }
        }
    }
    output << '"';
    return output.str();
}

[[nodiscard]] bool writeAllBytes(
    const int fd, const void* data, std::size_t byteCount
) noexcept {
    const auto* cursor = static_cast<const unsigned char*>(data);
    while (byteCount != 0u) {
        const ssize_t written = ::write(fd, cursor, byteCount);
        if (written < 0) {
            if (errno == EINTR) continue;
            return false;
        }
        if (written == 0) return false;
        cursor += written;
        byteCount -= static_cast<std::size_t>(written);
    }
    return true;
}

[[nodiscard]] std::string hexU64(const std::uint64_t value) {
    std::ostringstream output;
    output << std::hex << std::setw(16) << std::setfill('0') << value;
    return output.str();
}

void writeRegionalRAPCapture(
    const void* payload,
    const std::uint64_t payloadBytes,
    const std::vector<RegionalRAPCaptureArray>& arrays,
    const RegionalRAPCaptureMetadata& metadata,
    const std::string& basePath
) {
    const auto* bytes = static_cast<const unsigned char*>(payload);
    std::string payloadHash = sha256Hex(bytes, static_cast<std::size_t>(payloadBytes));
    std::ostringstream manifest;
    manifest << std::setprecision(9)
        << "{\"schema\":\"numi.matter.regional_rap_capture.v1\","
        << "\"byte_order\":\"little_endian\","
        << "\"layout\":\"C-contiguous; environment-major; each array is tightly concatenated with no padding; float32x4 elements store four adjacent little-endian lanes\","
        << "\"capture_point\":"
        << jsonQuoted(metadata.preconditionerSelector == 5u
            ? "after_regional_rap_and_graph_factor_barrier_before_fgmres_correction"
            : "after_regional_rap_factor_barrier_before_fgmres_correction")
        << ','
        << "\"source_physics_fingerprint\":"
        << jsonQuoted(hexU64(metadata.worldFingerprint)) << ','
        << "\"device_program_fingerprint\":"
        << jsonQuoted(hexU64(metadata.executionFingerprint)) << ','
        << "\"root\":" << metadata.controlStep
        << ",\"iteration\":" << metadata.solverIteration
        << ",\"environment_count\":" << metadata.environmentCount
        << ",\"node_count\":" << metadata.nodeCount
        << ",\"tetrahedron_count\":" << metadata.tetrahedronCount
        << ",\"mode_count\":" << metadata.modeCount
        << ",\"preconditioner_selector\":"
        << metadata.preconditionerSelector
        << ",\"graph_schwarz\":{\"enabled\":"
        << (metadata.preconditionerSelector == 5u ? "true" : "false")
        << ",\"capture_environment\":"
        << (metadata.graphEnvironment == NM_INVALID_INDEX ? "null" :
            std::to_string(metadata.graphEnvironment))
        << ",\"patch_count\":" << metadata.graphPatchCount
        << ",\"patch_node_count\":" << metadata.graphPatchNodeCount
        << ",\"dof_count\":" << metadata.graphDofCount
        << ",\"matrix_float_count\":" << metadata.graphMatrixFloatCount
        << ",\"pivot_count\":" << metadata.graphPivotCount
        << ",\"layout_checksum_fnv1a32\":"
        << metadata.graphLayoutChecksum
        << ",\"source_topology_sha256\":"
        << jsonQuoted(metadata.graphSourceTopologySHA256)
        << ",\"source_free_mask_sha256\":"
        << jsonQuoted(metadata.graphSourceFreeMaskSHA256)
        << ",\"potential_node_mask_sha256\":"
        << jsonQuoted(metadata.graphPotentialMaskSHA256)
        << ",\"source_topology_digest_encoding\":\"little-endian u32 node_count, u32 tetrahedron_count, then row-major u32 tet connectivity; source free mask is raw u8, 1=free 0=fixed; graph potential-node mask is raw u8, 1=covered\"}"
        << ",\"material_state_stride\":" << metadata.materialStateStride
        << ",\"device\":{\"name\":" << jsonQuoted(metadata.deviceName)
        << ",\"registry_id\":" << metadata.deviceRegistryID << "},"
        << "\"substep\":" << metadata.physicsSubstep
        << ",\"microtick\":" << metadata.microtick
        << ",\"microtick_count\":" << metadata.microtickCount
        << ",\"linearization_generation\":"
        << metadata.linearizationGeneration
        << ",\"linearization_generation_encoding\":\"(micro_generation << 32) | newton_iteration\""
        << ",\"micro_generation\":" << metadata.microGeneration
        << ",\"dt_seconds\":" << metadata.timestepSeconds
        << ",\"operator_generation\":\"candidate state, accepted history, scheduler, deformation words, tangent cache, AP and RAP copied from the same ordered command-buffer generation; selector 5 graph matrices and LU factors follow from the same candidate before FGMRES correction\","
        << "\"candidate_linearization_digest_algorithm\":\"SHA-256 over raw little-endian environment slices concatenated in this exact order: candidate_nodes, material_history, scheduler_exponents, deformation_high, deformation_low, then algorithmic_tangent_cache and algorithmic_tangent_cache_valid when tangent_cache_used=true\","
        << "\"tangent_cache_used\":"
        << (metadata.tangentCacheUsed != 0u ? "true" : "false") << ','
        << "\"candidate_linearization_sha256\":[";
    const auto findArray = [&](const char* name) -> const RegionalRAPCaptureArray* {
        for (const auto& array : arrays)
            if (array.name == name) return &array;
        return nullptr;
    };
    const auto* candidateNodes = findArray("candidate_nodes");
    const auto* materialHistory = findArray("material_history");
    const auto* scheduler = findArray("scheduler_exponents");
    const auto* localFHigh = findArray("deformation_high");
    const auto* localFLow = findArray("deformation_low");
    const auto* tangentCache = findArray("algorithmic_tangent_cache");
    const auto* tangentCacheValid =
        findArray("algorithmic_tangent_cache_valid");
    const bool identityArraysPresent = candidateNodes != nullptr &&
        materialHistory != nullptr && scheduler != nullptr &&
        localFHigh != nullptr && localFLow != nullptr &&
        (metadata.tangentCacheUsed == 0u ||
            (tangentCache != nullptr && tangentCacheValid != nullptr));
    for (std::uint32_t environment = 0u;
         environment < metadata.environmentCount; ++environment) {
        if (environment != 0u) manifest << ',';
        if (!identityArraysPresent) {
            manifest << "{\"environment\":" << environment
                     << ",\"identity_status\":\"missing_arrays\"}";
            continue;
        }
        CC_SHA256_CTX context;
        CC_SHA256_Init(&context);
        const auto updateEnv = [&](const RegionalRAPCaptureArray* array,
                                   const std::uint64_t bytesPerEnvironment) {
            const std::uint64_t offset = array->offset +
                static_cast<std::uint64_t>(environment) * bytesPerEnvironment;
            CC_SHA256_Update(&context, bytes + offset,
                static_cast<CC_LONG>(bytesPerEnvironment));
        };
        const std::uint64_t nodeBytes = candidateNodes->byteCount /
            metadata.environmentCount;
        const std::uint64_t historyBytes = materialHistory->byteCount /
            metadata.environmentCount;
        const std::uint64_t schedulerBytes = scheduler->byteCount /
            metadata.environmentCount;
        const std::uint64_t highBytes = localFHigh->byteCount /
            metadata.environmentCount;
        const std::uint64_t lowBytes = localFLow->byteCount /
            metadata.environmentCount;
        updateEnv(candidateNodes, nodeBytes);
        updateEnv(materialHistory, historyBytes);
        updateEnv(scheduler, schedulerBytes);
        updateEnv(localFHigh, highBytes);
        updateEnv(localFLow, lowBytes);
        if (metadata.tangentCacheUsed != 0u) {
            updateEnv(tangentCache, tangentCache->byteCount /
                metadata.environmentCount);
            updateEnv(tangentCacheValid, tangentCacheValid->byteCount /
                metadata.environmentCount);
        }
        unsigned char digest[CC_SHA256_DIGEST_LENGTH]{};
        CC_SHA256_Final(digest, &context);
        std::string identityHash;
        identityHash.resize(CC_SHA256_DIGEST_LENGTH * 2u);
        static constexpr char digits[] = "0123456789abcdef";
        for (std::size_t index = 0u; index < CC_SHA256_DIGEST_LENGTH; ++index) {
            identityHash[2u * index] = digits[digest[index] >> 4u];
            identityHash[2u * index + 1u] = digits[digest[index] & 0x0fu];
        }
        const std::uint64_t nodeOffset = candidateNodes->offset +
            static_cast<std::uint64_t>(environment) * nodeBytes;
        manifest << "{\"environment\":" << environment
            << ",\"sha256\":" << jsonQuoted(identityHash)
            << ",\"candidate_nodes_sha256\":"
            << jsonQuoted(sha256Hex(bytes + nodeOffset,
                                    static_cast<std::size_t>(nodeBytes)))
            << '}';
    }
    manifest << "],\"payload\":{\"file\":"
        << jsonQuoted(basePath + ".regional.bin")
        << ",\"byte_count\":" << payloadBytes
        << ",\"sha256\":" << jsonQuoted(payloadHash)
        << "},\"arrays\":[";
    for (std::size_t index = 0u; index < arrays.size(); ++index) {
        const auto& array = arrays[index];
        if (index != 0u) manifest << ',';
        manifest << "{\"name\":" << jsonQuoted(array.name)
            << ",\"dtype\":" << jsonQuoted(array.dtype)
            << ",\"shape\":[";
        for (std::size_t axis = 0u; axis < array.shape.size(); ++axis) {
            if (axis != 0u) manifest << ',';
            manifest << array.shape[axis];
        }
        manifest << "],\"offset\":" << array.offset
            << ",\"byte_count\":" << array.byteCount
            << ",\"element_bytes\":" << array.elementBytes
            << ",\"sha256\":"
            << jsonQuoted(sha256Hex(bytes + array.offset,
                                    static_cast<std::size_t>(array.byteCount)))
            << '}';
    }
    manifest << "]}\n";
    const std::string manifestText = manifest.str();
    const std::string binaryPath = basePath + ".regional.bin";
    const std::string manifestPath = basePath + ".regional.json";
    int binaryFD = ::open(binaryPath.c_str(),
        O_WRONLY | O_CREAT | O_EXCL, S_IRUSR | S_IWUSR);
    if (binaryFD < 0) {
        std::fprintf(stderr,
            "fem_regional_rap_capture_error={\"schema\":1,\"root\":%u,\"reason\":\"binary_exclusive_create_failed\",\"errno\":%d}\n",
            metadata.controlStep, errno);
        return;
    }
    int manifestFD = ::open(manifestPath.c_str(),
        O_WRONLY | O_CREAT | O_EXCL, S_IRUSR | S_IWUSR);
    if (manifestFD < 0) {
        const int savedErrno = errno;
        ::close(binaryFD);
        ::unlink(binaryPath.c_str());
        std::fprintf(stderr,
            "fem_regional_rap_capture_error={\"schema\":1,\"root\":%u,\"reason\":\"manifest_exclusive_create_failed\",\"errno\":%d}\n",
            metadata.controlStep, savedErrno);
        return;
    }
    const bool binaryWritten = writeAllBytes(binaryFD, bytes,
        static_cast<std::size_t>(payloadBytes));
    const bool manifestWritten = binaryWritten && writeAllBytes(
        manifestFD, manifestText.data(), manifestText.size());
    const int binaryClose = ::close(binaryFD);
    const int manifestClose = ::close(manifestFD);
    if (!binaryWritten || !manifestWritten || binaryClose != 0 ||
        manifestClose != 0) {
        ::unlink(binaryPath.c_str());
        ::unlink(manifestPath.c_str());
        std::fprintf(stderr,
            "fem_regional_rap_capture_error={\"schema\":1,\"root\":%u,\"reason\":\"write_or_close_failed\",\"errno\":%d}\n",
            metadata.controlStep, errno);
        return;
    }
    std::fprintf(stderr,
        "fem_regional_rap_capture_complete={\"schema\":1,\"root\":%u,\"iteration\":%u,\"bytes\":%llu,\"arrays\":%lu,\"manifest\":%s}\n",
        metadata.controlStep, metadata.solverIteration,
        static_cast<unsigned long long>(payloadBytes),
        static_cast<unsigned long>(arrays.size()),
        jsonQuoted(manifestPath).c_str());
}

class UploadPlan {
public:
    UploadPlan(id<MTLDevice> device, id<MTLCommandQueue> queue)
        : device_(device), commandBuffer_([queue commandBuffer]),
          staging_([NSMutableArray array]) {
        blit_ = [commandBuffer_ blitCommandEncoder];
    }

    template <typename T>
    [[nodiscard]] id<MTLBuffer> repeated(
        const std::span<const T> values,
        const std::size_t repeat,
        bool& valid,
        std::size_t& residentBytes
    ) {
        const NSUInteger oneBytes = checkedBytes(values.size(), sizeof(T), valid);
        const NSUInteger totalBytes = checkedBytes(values.size() * repeat, sizeof(T), valid);
        if (!valid) {
            return nil;
        }
        id<MTLBuffer> output = [device_
            newBufferWithLength:totalBytes
                        options:MTLResourceStorageModePrivate];
        if (output == nil) {
            valid = false;
            return nil;
        }
        residentBytes += totalBytes;
        if (values.empty() || repeat == 0u) {
            return output;
        }
        // checkedBytes() may round a short logical payload up to Metal's
        // 16-byte typed-binding sentinel.  newBufferWithBytes:length: reads
        // exactly `length` host bytes, so passing the rounded size would read
        // beyond a source span such as float[3].  Allocate the padded staging
        // range explicitly, initialize its sentinel tail, and copy only the
        // logical source bytes.
        id<MTLBuffer> staging = [device_
            newBufferWithLength:oneBytes
                        options:MTLResourceStorageModeShared];
        if (staging == nil) {
            valid = false;
            return nil;
        }
        std::memset(staging.contents, 0, oneBytes);
        std::memcpy(staging.contents, values.data(), values.size_bytes());
        [staging_ addObject:staging];
        const NSUInteger logicalBytes = values.size_bytes();
        for (std::size_t index = 0u; index < repeat; ++index) {
            [blit_ copyFromBuffer:staging
                    sourceOffset:0u
                        toBuffer:output
               destinationOffset:static_cast<NSUInteger>(index) * logicalBytes
                            size:logicalBytes];
        }
        return output;
    }

    template <typename T>
    [[nodiscard]] id<MTLBuffer> one(
        const std::span<const T> values,
        bool& valid,
        std::size_t& residentBytes
    ) {
        return repeated(values, 1u, valid, residentBytes);
    }

    [[nodiscard]] bool finish(std::string& error) {
        [blit_ endEncoding];
        [commandBuffer_ commit];
        [commandBuffer_ waitUntilCompleted];
        if (commandBuffer_.status == MTLCommandBufferStatusError) {
            error = errorString(commandBuffer_.error);
            return false;
        }
        return true;
    }

private:
    id<MTLDevice> device_ = nil;
    id<MTLCommandBuffer> commandBuffer_ = nil;
    id<MTLBlitCommandEncoder> blit_ = nil;
    NSMutableArray<id<MTLBuffer>>* staging_ = nil;
};

template <typename T>
[[nodiscard]] id<MTLBuffer> privateScratch(
    id<MTLDevice> device,
    const std::size_t count,
    bool& valid,
    std::size_t& residentBytes
) {
    const NSUInteger bytes = checkedBytes(count, sizeof(T), valid);
    if (!valid) {
        return nil;
    }
    id<MTLBuffer> buffer = [device
        newBufferWithLength:bytes
                    options:MTLResourceStorageModePrivate];
    if (buffer == nil) {
        valid = false;
        return nil;
    }
    residentBytes += bytes;
    return buffer;
}

template <typename T>
[[nodiscard]] id<MTLBuffer> sharedScratch(
    id<MTLDevice> device,
    const std::size_t count,
    bool& valid,
    std::size_t& residentBytes
) {
    const NSUInteger bytes = checkedBytes(count, sizeof(T), valid);
    if (!valid) {
        return nil;
    }
    id<MTLBuffer> buffer = [device
        newBufferWithLength:bytes
                    options:MTLResourceStorageModeShared];
    if (buffer == nil) {
        valid = false;
        return nil;
    }
    std::memset(buffer.contents, 0, bytes);
    residentBytes += bytes;
    return buffer;
}

struct RegionalGalerkinBasis {
    std::vector<nm_float4> values; // [mode][compiled FEM node]
    std::uint32_t modeCount = 0u;
    std::string error;
};

struct RegionalGraphSchwarzHostLayout {
    std::vector<std::array<std::uint32_t, 4>> patches;
    std::vector<std::array<std::uint32_t, 4>> rows;
    detail::RegionalGraphSchwarzLayout layout;
    std::vector<std::uint8_t> sourceFreeMask;
    std::vector<std::uint8_t> potentialMask;
    std::string sourceTopologySHA256;
    std::string sourceFreeMaskSHA256;
    std::string potentialMaskSHA256;
};

[[nodiscard]] RegionalGraphSchwarzHostLayout buildRegionalGraphSchwarz(
    const CompiledWorld& world
) {
    RegionalGraphSchwarzHostLayout result;
    const std::uint32_t nodes = world.dispatch.femNodeCount;
    if (nodes == 0u || world.fem.nodes.size() != nodes ||
        world.fem.tetrahedra.size() != world.dispatch.tetrahedronCount) {
        result.layout.error = "graph Schwarz requires exact compiled FEM node/tet arrays";
        return result;
    }
    std::vector<std::array<std::uint32_t, 4>> tetrahedra;
    tetrahedra.reserve(world.fem.tetrahedra.size());
    for (const NMTetrahedronGPU& tetrahedron : world.fem.tetrahedra) {
        tetrahedra.push_back({tetrahedron.nodes.x, tetrahedron.nodes.y,
                              tetrahedron.nodes.z, tetrahedron.nodes.w});
    }
    result.sourceFreeMask.resize(nodes);
    result.potentialMask.assign(nodes, 1u);
    for (std::uint32_t node = 0u; node < nodes; ++node) {
        const float fixed = world.fem.nodes[node].restAndFixed.w;
        if (!std::isfinite(fixed) || (fixed != 0.0f && fixed != 1.0f)) {
            result.layout.error = "graph Schwarz requires a binary immutable FEM fixed mask";
            return result;
        }
        result.sourceFreeMask[node] = fixed == 0.0f ? 1u : 0u;
    }
    // Hash the exact host topology and mask consumed by the builder
    // and uploaded below; no reconstructed or synthetic graph enters
    // this identity. Serialize words explicitly in little-endian order.
    std::vector<unsigned char> topologyBytes;
    topologyBytes.reserve(8u + tetrahedra.size() * 16u);
    const auto appendWord = [&](const std::uint32_t word) {
        for (unsigned int shift = 0u; shift < 32u; shift += 8u)
            topologyBytes.push_back(static_cast<unsigned char>(word >> shift));
    };
    appendWord(nodes);
    appendWord(static_cast<std::uint32_t>(tetrahedra.size()));
    for (const auto& tetrahedron : tetrahedra)
        for (const std::uint32_t node : tetrahedron) appendWord(node);
    result.sourceTopologySHA256 = sha256Hex(
        topologyBytes.data(), topologyBytes.size());
    result.sourceFreeMaskSHA256 = sha256Hex(
        result.sourceFreeMask.data(), result.sourceFreeMask.size());
    result.potentialMaskSHA256 = sha256Hex(
        result.potentialMask.data(), result.potentialMask.size());
    result.layout = detail::buildBudgetedRegionalGraphSchwarzLayout(
        nodes, tetrahedra, result.sourceFreeMask,
        world.dispatch.environmentCount);
    if (!result.layout.error.empty()) return result;
    result.patches.reserve(result.layout.patches.size());
    for (const auto& patch : result.layout.patches) {
        result.patches.push_back({patch.nodeOffset, patch.nodeCount,
                                  patch.matrixFloatOffset, patch.pivotOffset});
    }
    result.rows = result.layout.rows;
    return result;
}

[[nodiscard]] bool usesRegionalGalerkinPreconditioner(
    const std::uint32_t selector
) noexcept {
    return selector == 2u || selector == 3u || selector == 4u ||
        selector == 5u;
}

[[nodiscard]] std::uint32_t decodeFEMPreconditionerRegion(
    const std::uint32_t tetrahedronFlags
) noexcept {
    return (tetrahedronFlags &
            NM_TETRAHEDRON_PRECONDITIONER_REGION_MASK) >>
        NM_TETRAHEDRON_PRECONDITIONER_REGION_SHIFT;
}

[[nodiscard]] RegionalGalerkinBasis buildRegionalGalerkinBasis(
    const CompiledWorld& world
) {
    constexpr std::uint32_t maximumRegions = 5u;
    constexpr std::uint32_t modesPerRegion = 6u;
    constexpr std::uint32_t maximumModes = 32u;
    RegionalGalerkinBasis result;
    const std::size_t nodeCount = world.dispatch.femNodeCount;
    if (world.objects.size() != 1u || nodeCount == 0u ||
        world.fem.nodes.size() != nodeCount || world.fem.tetrahedra.empty()) {
        result.error = "regional Galerkin basis requires one nonempty compiled FEM object";
        return result;
    }
    std::array<bool, maximumRegions> declaredRegion{};
    std::uint32_t declaredRegionCount = 0u;
    for (const NMTetrahedronGPU& tetrahedron : world.fem.tetrahedra) {
        const std::uint32_t region = decodeFEMPreconditionerRegion(
            tetrahedron.identity.w);
        if (region >= maximumRegions) {
            result.error = "compiled tetrahedron has an out-of-range regional Galerkin label";
            return result;
        }
        declaredRegion[region] = true;
        declaredRegionCount = std::max(declaredRegionCount, region + 1u);
    }
    if (declaredRegionCount == 0u ||
        declaredRegionCount * modesPerRegion > maximumModes) {
        result.error = "regional Galerkin region count exceeds its 32-mode bound";
        return result;
    }
    for (std::uint32_t region = 0u; region < declaredRegionCount; ++region) {
        if (!declaredRegion[region]) {
            result.error = "regional Galerkin labels must be compact from zero";
            return result;
        }
    }
    constexpr std::uint64_t maximumRegionalScratchBytes =
        256ull * 1024ull * 1024ull;
    const bool enrichBending = world.mixedSolver.executionBudgets.z >= 3u;
    const std::uint64_t modes = enrichBending ? maximumModes :
        static_cast<std::uint64_t>(declaredRegionCount) * modesPerRegion;
    const std::uint64_t environments = world.dispatch.environmentCount;
    const std::uint64_t nodes = nodeCount;
    if (environments == 0u || environments > 4u) {
        result.error = "regional Galerkin environment count must be between one and four";
        return result;
    }
    const std::uint64_t scalarCount =
        nodes * modes + 2u * environments * nodes * modes +
        environments * modes * modes +
        environments * modes * 2u + environments * modes + environments;
    const std::uint64_t blockFineFloat4Count =
        (world.mixedSolver.executionBudgets.z == 3u ||
         world.mixedSolver.executionBudgets.z == 4u)
            ? 3u * environments * nodes
            : 0u;
    constexpr std::uint64_t maximumSafeScalars =
        maximumRegionalScratchBytes / sizeof(nm_float4);
    if (scalarCount > maximumSafeScalars ||
        blockFineFloat4Count > maximumSafeScalars -
            std::min(scalarCount, maximumSafeScalars)) {
        result.error = "regional Galerkin P/AP/coarse plus fine-correction scratch exceeds the 256 MiB admission bound";
        return result;
    }
    std::array<std::vector<double>, maximumRegions> nodalVolume;
    for (auto& values : nodalVolume) values.assign(nodeCount, 0.0);
    std::array<double, maximumRegions> totalVolume{};
    std::array<std::array<double, 3>, maximumRegions> firstMoment{};
    std::array<double, maximumRegions> secondMoment{};
    std::array<bool, maximumRegions> present{};
    std::uint32_t regionCount = 0u;
    const auto position = [&](const std::uint32_t node) {
        const nm_float4 value = world.fem.nodes[node].positionAndMass;
        return std::array<double, 3>{value.x, value.y, value.z};
    };
    for (const NMTetrahedronGPU& tetrahedron : world.fem.tetrahedra) {
        if ((tetrahedron.identity.w & NM_OBJECT_ACTIVE) == 0u) {
            result.error = "regional Galerkin basis cannot include inactive topology slots";
            return result;
        }
        const std::uint32_t region = decodeFEMPreconditionerRegion(
            tetrahedron.identity.w);
        if (region >= maximumRegions) {
            result.error = "compiled tetrahedron has an out-of-range regional Galerkin label";
            return result;
        }
        const double volume = tetrahedron.inverseRestRow0.w;
        if (!(volume > 0.0) || !std::isfinite(volume)) {
            result.error = "compiled tetrahedron has invalid volume for regional Galerkin basis";
            return result;
        }
        present[region] = true;
        regionCount = std::max(regionCount, region + 1u);
        std::array<double, 3> center{};
        const std::array<std::uint32_t, 4> nodes{
            tetrahedron.nodes.x, tetrahedron.nodes.y,
            tetrahedron.nodes.z, tetrahedron.nodes.w};
        for (const std::uint32_t node : nodes) {
            if (node >= nodeCount) {
                result.error = "compiled regional Galerkin tetrahedron references an invalid node";
                return result;
            }
            const auto x = position(node);
            for (std::size_t axis = 0u; axis < 3u; ++axis)
                center[axis] += 0.25 * x[axis];
            nodalVolume[region][node] += 0.25 * volume;
        }
        totalVolume[region] += volume;
        for (std::size_t axis = 0u; axis < 3u; ++axis)
            firstMoment[region][axis] += volume * center[axis];
    }
    if (regionCount == 0u || regionCount * modesPerRegion > maximumModes) {
        result.error = "regional Galerkin region count exceeds its 32-mode bound";
        return result;
    }
    for (std::uint32_t region = 0u; region < regionCount; ++region) {
        if (!present[region] || !(totalVolume[region] > 0.0)) {
            result.error = "regional Galerkin labels must be compact from zero";
            return result;
        }
        for (double& component : firstMoment[region])
            component /= totalVolume[region];
    }
    for (const NMTetrahedronGPU& tetrahedron : world.fem.tetrahedra) {
        const std::uint32_t region = decodeFEMPreconditionerRegion(
            tetrahedron.identity.w);
        const double volume = tetrahedron.inverseRestRow0.w;
        const std::array<std::uint32_t, 4> nodes{
            tetrahedron.nodes.x, tetrahedron.nodes.y,
            tetrahedron.nodes.z, tetrahedron.nodes.w};
        for (const std::uint32_t node : nodes) {
            const auto x = position(node);
            double radiusSquared = 0.0;
            for (std::size_t axis = 0u; axis < 3u; ++axis) {
                const double delta = x[axis] - firstMoment[region][axis];
                radiusSquared += delta * delta;
            }
            secondMoment[region] += 0.25 * volume * radiusSquared;
        }
    }
    std::vector<double> nodalTotal(nodeCount, 0.0);
    for (std::uint32_t region = 0u; region < regionCount; ++region)
        for (std::size_t node = 0u; node < nodeCount; ++node)
            nodalTotal[node] += nodalVolume[region][node];

    std::vector<std::vector<double>> orthonormal;
    orthonormal.reserve(maximumModes);
    const auto admitCandidate = [&](std::vector<double> candidate) {
        if (orthonormal.size() >= maximumModes) return;
        double rawNormSquared = 0.0;
        for (const double value : candidate) rawNormSquared += value * value;
        if (!(rawNormSquared > 0.0)) return;
        const double rawNorm = std::sqrt(rawNormSquared);
        for (unsigned pass = 0u; pass < 2u; ++pass) {
            for (const auto& basis : orthonormal) {
                double projection = 0.0;
                for (std::size_t index = 0u; index < candidate.size(); ++index)
                    projection += basis[index] * candidate[index];
                for (std::size_t index = 0u; index < candidate.size(); ++index)
                    candidate[index] -= projection * basis[index];
            }
        }
        double normSquared = 0.0;
        for (const double value : candidate) normSquared += value * value;
        const double norm = std::sqrt(normSquared);
        if (!(norm > 1.0e-12 * rawNorm) || !std::isfinite(norm)) return;
        for (double& value : candidate) value /= norm;
        orthonormal.push_back(std::move(candidate));
    };
    for (std::uint32_t region = 0u; region < regionCount; ++region) {
        const double radius = std::sqrt(secondMoment[region] / totalVolume[region]);
        for (std::uint32_t mode = 0u; mode < modesPerRegion; ++mode) {
            std::vector<double> candidate(nodeCount * 3u, 0.0);
            for (std::size_t node = 0u; node < nodeCount; ++node) {
                const double total = nodalTotal[node];
                if (!(total > 0.0) || world.fem.nodes[node].restAndFixed.w != 0.0f)
                    continue;
                const double weight = nodalVolume[region][node] / total;
                if (!(weight > 0.0)) continue;
                const auto x = position(static_cast<std::uint32_t>(node));
                const double rx = x[0] - firstMoment[region][0];
                const double ry = x[1] - firstMoment[region][1];
                const double rz = x[2] - firstMoment[region][2];
                std::array<double, 3> value{};
                if (mode < 3u) {
                    value[mode] = weight;
                } else if (radius > 1.0e-15) {
                    const double scale = weight / radius;
                    if (mode == 3u) value = {0.0, -scale * rz, scale * ry};
                    if (mode == 4u) value = {scale * rz, 0.0, -scale * rx};
                    if (mode == 5u) value = {-scale * ry, scale * rx, 0.0};
                }
                for (std::size_t axis = 0u; axis < 3u; ++axis)
                    candidate[node * 3u + axis] = value[axis];
            }
            admitCandidate(std::move(candidate));
        }
    }
    if (enrichBending && orthonormal.size() < maximumModes) {
        std::array<double, 3> minimum{INFINITY, INFINITY, INFINITY};
        std::array<double, 3> maximum{-INFINITY, -INFINITY, -INFINITY};
        for (std::size_t node = 0u; node < nodeCount; ++node) {
            const auto x = position(static_cast<std::uint32_t>(node));
            for (unsigned axis = 0u; axis < 3u; ++axis) {
                minimum[axis] = std::min(minimum[axis], x[axis]);
                maximum[axis] = std::max(maximum[axis], x[axis]);
            }
        }
        const auto coordinates = regionalBendingCoordinates(minimum, maximum);
        if (coordinates.available) {
            for (unsigned mode = 0u; mode < 8u &&
                    orthonormal.size() < maximumModes; ++mode) {
                std::vector<double> candidate(nodeCount * 3u, 0.0);
                for (std::size_t node = 0u; node < nodeCount; ++node) {
                    if (!(nodalTotal[node] > 0.0) ||
                        world.fem.nodes[node].restAndFixed.w != 0.0f) continue;
                    const auto value = regionalBendingTrialField(coordinates,
                        position(static_cast<std::uint32_t>(node)), mode);
                    for (unsigned axis = 0u; axis < 3u; ++axis)
                        candidate[3u * node + axis] = value[axis];
                }
                admitCandidate(std::move(candidate));
            }
        }
    }
    if (orthonormal.empty() || orthonormal.size() > maximumModes) {
        result.error = "regional Galerkin basis has no independent free modes";
        return result;
    }
    result.modeCount = static_cast<std::uint32_t>(orthonormal.size());
    result.values.resize(orthonormal.size() * nodeCount);
    for (std::size_t mode = 0u; mode < orthonormal.size(); ++mode) {
        for (std::size_t node = 0u; node < nodeCount; ++node) {
            result.values[mode * nodeCount + node] = {
                static_cast<float>(orthonormal[mode][node * 3u]),
                static_cast<float>(orthonormal[mode][node * 3u + 1u]),
                static_cast<float>(orthonormal[mode][node * 3u + 2u]),
                0.0f};
        }
    }
    return result;
}


