    id<MTLBuffer> femOperatorFDParameters = nil;
    id<MTLBuffer> femOperatorFDOperatorStatuses = nil;
    id<MTLBuffer> femOperatorFDHistorySnapshot = nil;
    id<MTLBuffer> femOperatorFDTetrahedronSnapshot = nil;
    id<MTLBuffer> femOperatorFDStatusSnapshot = nil;
    id<MTLBuffer> femOperatorFDNodeSnapshot = nil;
    id<MTLBuffer> femOperatorFDRichCapture = nil;
    id<MTLBuffer> femOperatorFDInputsUnchanged = nil;
    id<MTLBuffer> fgmresBasis = nil;
    id<MTLBuffer> fgmresPreconditionedBasis = nil;
    id<MTLBuffer> fgmresHessenberg = nil;
    id<MTLBuffer> fgmresRotations = nil;
    id<MTLBuffer> fgmresLeastSquares = nil;
    id<MTLBuffer> fgmresRestartCoefficients = nil;
    id<MTLBuffer> fgmresStates = nil;
    // Optional per-tetrahedron unsymmetric 9x9 material-frame dP/dF cache.
    // It is rebuilt at each Newton linearization and may feed FGMRES,
    // conditioning-only tangent preconditioners, and regional AP. Direct
    // residual and Armijo paths never read it.
    id<MTLBuffer> femAlgorithmicTangentCache = nil;
    id<MTLBuffer> femAlgorithmicTangentCacheValid = nil;
    bool forceCompletedTangentCacheRebuild = false;
    // Source-bound, opt-in regional RAP preconditioner. femRegionalBasis is
    // the immutable authored P; femRegionalEffectiveBasis is P projected
    // through each environment's current candidate Dirichlet mask. AP and
    // the small coarse factorization are rebuilt from the exact production A
    // at each Newton linearization. These are solver-only scratch arenas.
    id<MTLBuffer> femRegionalBasis = nil;
    id<MTLBuffer> femRegionalEffectiveBasis = nil;
    id<MTLBuffer> femRegionalLinearizationNodes = nil;
    id<MTLBuffer> femRegionalLinearizationMaterialState = nil;
    id<MTLBuffer> femRegionalLinearizationSchedulerExponent = nil;
    id<MTLBuffer> femRegionalLinearizationLocalFHigh = nil;
    id<MTLBuffer> femRegionalLinearizationLocalFLow = nil;
    id<MTLBuffer> femRegionalAP = nil;
    id<MTLBuffer> femRegionalCoarseMatrix = nil;
    id<MTLBuffer> femRegionalCoarsePivots = nil;
    id<MTLBuffer> femRegionalCoarseRHS = nil;
    id<MTLBuffer> femRegionalCoarseCoefficients = nil;
    id<MTLBuffer> femRegionalCoarseValid = nil;
    // Selector 3 only: inverse 3x3 nodal velocity blocks, three row-major
    // float4 rows per environment/node. This conditions FGMRES only.
    id<MTLBuffer> femRegionalNodeBlockInverse = nil;
    // Selector 5: deterministic immutable graph patches. Metadata is uploaded
    // once; the dense per-Newton matrices, pivots, validity, and patch solves
    // are private scratch and never enter accepted physical state.
    id<MTLBuffer> femRegionalGraphPatches = nil;
    id<MTLBuffer> femRegionalGraphPatchNodes = nil;
    id<MTLBuffer> femRegionalGraphRows = nil;
    id<MTLBuffer> femRegionalGraphNodePatchOffsets = nil;
    id<MTLBuffer> femRegionalGraphNodePatchValues = nil;
    id<MTLBuffer> femRegionalGraphNodeCoverage = nil;
    id<MTLBuffer> femRegionalGraphFactors = nil;
    // Selector 5 refinement-only copy of the assembled patch principal A.
    // `femRegionalGraphFactors` is overwritten in place by pivoted LU, while
    // one residual-correction solve needs the original A for r = b - A*x.
    id<MTLBuffer> femRegionalGraphOriginalMatrices = nil;
    id<MTLBuffer> femRegionalGraphPivots = nil;
    id<MTLBuffer> femRegionalGraphFactorValid = nil;
    id<MTLBuffer> femRegionalGraphPatchCorrections = nil;
    std::uint32_t femRegionalModeCount = 0u;
    std::uint32_t femRegionalGraphPatchCount = 0u;
    std::uint32_t femRegionalGraphParallelSearch = 0u;
    std::uint32_t femRegionalGraphPatchNodeCount = 0u;
    std::uint32_t femRegionalGraphDofCount = 0u;
    std::uint32_t femRegionalGraphMatrixFloatCount = 0u;
    std::uint32_t femRegionalGraphPivotCount = 0u;
    std::uint32_t femRegionalGraphLayoutChecksum = 0u;
    std::string femRegionalGraphSourceTopologySHA256;
    std::string femRegionalGraphSourceFreeMaskSHA256;
    std::string femRegionalGraphPotentialMaskSHA256;
    id<MTLBuffer> primalContactArguments = nil;

    id<MTLBuffer> identificationDistributions = nil;
    id<MTLBuffer> identificationPreparedCheckpoint = nil;
    id<MTLBuffer> identificationCandidates = nil;
    id<MTLBuffer> identificationLosses = nil;
    id<MTLBuffer> dummy = nil;

    struct AcceptedStateArena {
        id<MTLBuffer> buffer = nil;
        std::uint32_t source = 0u;
        std::uint32_t target = 0u;
        std::uint32_t flags = 0u;
        std::uint64_t elementCount = 0u;
        std::uint32_t elementBytes = 0u;
        std::uint64_t bytesPerEnvironment = 0u;
        std::uint64_t sharedBytes = 0u;
    };

    [[nodiscard]] std::array<
        AcceptedStateArena,
        NM_MATTER_PHYSICAL_STATE_DIGEST_SOURCE_COUNT>
    acceptedStateArenas(
        id<MTLBuffer> rootTranslation,
        id<MTLBuffer> q,
        id<MTLBuffer> v,
        id<MTLBuffer> mujocoStates,
        std::uint32_t qStride,
        std::uint32_t vStride,
        std::uint32_t mujocoStateStride
    ) const noexcept;

    [[nodiscard]] id<MTLComputePipelineState> pipeline(
        const std::string_view name
    ) const {
        const auto iterator = pipelines.find(std::string(name));
        return iterator == pipelines.end() ? nil : iterator->second;
    }
};

std::array<
    Runtime::State::AcceptedStateArena,
    NM_MATTER_PHYSICAL_STATE_DIGEST_SOURCE_COUNT>
Runtime::State::acceptedStateArenas(
    id<MTLBuffer> rootTranslation,
    id<MTLBuffer> q,
    id<MTLBuffer> v,
    id<MTLBuffer> mujocoStates,
    const std::uint32_t qStride,
    const std::uint32_t vStride,
    const std::uint32_t mujocoStateStride
) const noexcept {
    const std::uint64_t particleMaterialScalars =
        static_cast<std::uint64_t>(dispatch.particleCount) *
        dispatch.materialStateStride;
    const std::uint64_t femMaterialScalars =
        static_cast<std::uint64_t>(dispatch.tetrahedronCount) *
        dispatch.materialStateStride;
    const auto canonical = [](id<MTLBuffer> buffer,
                              const std::size_t ordinal,
                              const std::uint64_t count,
                              const std::uint32_t elementBytes) noexcept {
        const NMPhysicalStateDigestManifestIdentityGPU& identity =
            kNMPhysicalStateDigestManifestV1[ordinal];
        const bool shared =
            (identity.flags & NM_MATTER_PHYSICAL_STATE_SOURCE_SHARED) != 0u;
        const std::uint64_t bytes = count *
            static_cast<std::uint64_t>(elementBytes);
        return AcceptedStateArena{
            .buffer = buffer,
            .source = identity.source,
            .target = identity.target,
            .flags = identity.flags,
            .elementCount = count,
            .elementBytes = elementBytes,
            .bytesPerEnvironment = shared ? 0u : bytes,
            .sharedBytes = shared ? bytes : 0u,
        };
    };
    return {{
        canonical(rootTranslation, 0u, 1u,
            sizeof(MRCompensatedRootTranslationGPU)),
        canonical(q, 1u, qStride, sizeof(float)),
        canonical(v, 2u, vStride, sizeof(float)),
        canonical(mujocoStates, 3u, mujocoStateStride,
            sizeof(MRMujocoMuscleStateGPU)),
        canonical(particleAccepted, 4u,
            dispatch.particleCount, sizeof(NMParticleStateGPU)),
        canonical(particleMaterialStateAccepted, 5u,
            particleMaterialScalars, sizeof(float)),
        canonical(femAccepted, 6u,
            dispatch.femNodeCount, sizeof(NMFEMNodeStateGPU)),
        canonical(femMaterialStateAccepted, 7u,
            femMaterialScalars, sizeof(float)),
        canonical(femFieldsAccepted, 8u,
            dispatch.femNodeCount, sizeof(NMFEMFieldStateGPU)),
        canonical(vascularAccepted, 9u,
            vascularValue.layout.ranges.z, sizeof(nm_float4)),
        canonical(vascularClockAccepted, 10u,
            vascularValue.layout.ranges.z == 0u ? 0u : 1u,
            sizeof(NMVascularClockGPU)),
        canonical(femTetrahedraAccepted, 11u,
            dispatch.tetrahedronCount, sizeof(NMTetrahedronGPU)),
        canonical(femTopologyNodesAccepted, 12u,
            dispatch.topologyNodeCapacity, sizeof(NMFEMTopologyNodeGPU)),
        canonical(cohesiveFacesAccepted, 13u,
            dispatch.cohesiveFaceCount, sizeof(NMCohesiveFaceGPU)),
        canonical(punctureChannelsAccepted, 14u,
            dispatch.punctureChannelCount, sizeof(NMPunctureChannelGPU)),
        canonical(topologyStatesAccepted, 15u,
            dispatch.objectCount, sizeof(NMFEMTopologyStateGPU)),
        canonical(learnedWeightsAccepted, 16u,
            dispatch.learnedWeightCount, sizeof(float)),
        canonical(learnedRevisionAccepted, 17u, 1u,
            sizeof(std::uint32_t)),
        canonical(contactHistoriesAccepted, 18u,
            dispatch.contactPairCount, sizeof(nm_float4)),
        canonical(humanSupportHistoriesAccepted, 19u,
            humanSupportDispatch.contactCount, sizeof(nm_float4)),
        canonical(humanSupportConsequencesAccepted, 20u,
            humanSupportDispatch.contactCount,
            sizeof(NMHumanSupportConsequenceGPU)),
        canonical(deformableContactHistoriesAccepted, 21u,
            dispatch.deformableContactCapacity,
            sizeof(NMDeformableContactHistoryGPU)),
        canonical(coupledGeneralizedCandidate, 22u,
            dispatch.rigidGeneralizedCapacity, sizeof(float)),
        canonical(frameReactions, 23u,
            dispatch.rigidProxyCount, sizeof(NMRigidReactionGPU)),
        canonical(rigidStates, 24u,
            dispatch.rigidProxyCount, sizeof(NMRigidStateGPU)),
        canonical(adaptive, 25u,
            dispatch.objectCount, sizeof(NMAdaptiveStateGPU)),
        canonical(schedulers, 26u,
            dispatch.objectCount, sizeof(NMSchedulerStateGPU)),
        canonical(identificationDistributions, 27u,
            identificationDistributionCount,
            sizeof(NMIdentificationDistributionGPU)),
        canonical(environmentParameters, 28u,
            dispatch.parameterCount, sizeof(float)),
        canonical(femNodeIncidence, 29u,
            femNodeIncidenceStride, sizeof(std::uint32_t)),
        canonical(femNodeRanges, 30u,
            femNodeRangeStride, sizeof(NMIncidenceRangeGPU)),
    }};
}

