    explicit AcceptedStateApplyPassView(
        const AcceptedStateApplyPassV2& input
    ) noexcept : exact(true) {
#define NM_COPY_APPLY_PASS_V2_FIELD(field) field = input.field
        NM_COPY_APPLY_PASS_V2_FIELD(abiVersion);
        NM_COPY_APPLY_PASS_V2_FIELD(structSize);
        NM_COPY_APPLY_PASS_V2_FIELD(mode);
        NM_COPY_APPLY_PASS_V2_FIELD(tokenFamily);
        NM_COPY_APPLY_PASS_V2_FIELD(environmentCount);
        NM_COPY_APPLY_PASS_V2_FIELD(environmentIdentifierBase);
        NM_COPY_APPLY_PASS_V2_FIELD(controlStep);
        NM_COPY_APPLY_PASS_V2_FIELD(physicsSubstep);
        NM_COPY_APPLY_PASS_V2_FIELD(physicsSubstepCount);
        NM_COPY_APPLY_PASS_V2_FIELD(transactionSlot);
        NM_COPY_APPLY_PASS_V2_FIELD(clockDomain);
        NM_COPY_APPLY_PASS_V2_FIELD(clockQuantumNanoseconds);
        NM_COPY_APPLY_PASS_V2_FIELD(commandBuffer);
        NM_COPY_APPLY_PASS_V2_FIELD(proposals);
        NM_COPY_APPLY_PASS_V2_FIELD(brainAcks);
        NM_COPY_APPLY_PASS_V2_FIELD(applyActions);
        NM_COPY_APPLY_PASS_V2_FIELD(matterApplyOutcomes);
        NM_COPY_APPLY_PASS_V2_FIELD(proposedPhysicsStateTokens);
        NM_COPY_APPLY_PASS_V2_FIELD(proposalsGPUAddress);
        NM_COPY_APPLY_PASS_V2_FIELD(brainAcksGPUAddress);
        NM_COPY_APPLY_PASS_V2_FIELD(applyActionsGPUAddress);
        NM_COPY_APPLY_PASS_V2_FIELD(matterApplyOutcomesGPUAddress);
        NM_COPY_APPLY_PASS_V2_FIELD(proposedPhysicsStateTokensGPUAddress);
        NM_COPY_APPLY_PASS_V2_FIELD(proposalElementCount);
        NM_COPY_APPLY_PASS_V2_FIELD(brainAckElementCount);
        NM_COPY_APPLY_PASS_V2_FIELD(applyActionElementCount);
        NM_COPY_APPLY_PASS_V2_FIELD(matterApplyOutcomeElementCount);
        NM_COPY_APPLY_PASS_V2_FIELD(proposedPhysicsStateTokenBytes);
        NM_COPY_APPLY_PASS_V2_FIELD(proposalStride);
        NM_COPY_APPLY_PASS_V2_FIELD(brainAckStride);
        NM_COPY_APPLY_PASS_V2_FIELD(applyActionStride);
        NM_COPY_APPLY_PASS_V2_FIELD(matterApplyOutcomeStride);
        NM_COPY_APPLY_PASS_V2_FIELD(proposedPhysicsStateTokenStrideBytes);
        tailReserved0 = input.reserved0;
        NM_COPY_APPLY_PASS_V2_FIELD(ownerProgramFingerprint);
        NM_COPY_APPLY_PASS_V2_FIELD(transactionFingerprint);
        NM_COPY_APPLY_PASS_V2_FIELD(linearizationEpoch);
        NM_COPY_APPLY_PASS_V2_FIELD(slotGeneration);
#undef NM_COPY_APPLY_PASS_V2_FIELD
    }
};

Runtime::Runtime() = default;
Runtime::~Runtime() = default;
Runtime::Runtime(Runtime&&) noexcept = default;
Runtime& Runtime::operator=(Runtime&&) noexcept = default;

RuntimeDiagnostics Runtime::initialize(
    const CompiledWorld& world,
    const RuntimeConfiguration& configuration
) {
    @autoreleasepool {
        RuntimeDiagnostics diagnostics;
        std::string layoutError;
        if (!validateCompiledWorldLayout(world, &layoutError)) {
            diagnostics.message =
                "compiled Matter world has an invalid fixed-capacity layout: " +
                layoutError;
            return diagnostics;
        }
        if (configuration.environmentCount != 0u &&
            configuration.environmentCount != world.dispatch.environmentCount) {
            diagnostics.message = "runtime environment count must match the cooked matter package";
            return diagnostics;
        }
        if (staticFEMSurfaceMapEnabled(world.dispatch)) {
            std::uint64_t nodeCapacity = 0u;
            std::uint64_t tetrahedronCapacity = 0u;
            std::uint64_t mutationCapacity = 0u;
            for (const NMFEMCapacityGPU& capacity : world.fem.capacities) {
                nodeCapacity += capacity.topology.x;
                tetrahedronCapacity += capacity.topology.y;
                mutationCapacity += capacity.work.x;
            }
            const bool mutableObject = std::any_of(
                world.objects.begin(), world.objects.end(),
                [](const NMContinuumObjectGPU& object) {
                    return object.representation != NM_REPRESENTATION_FEM ||
                        (object.flags & NM_OBJECT_MUTABLE_TOPOLOGY) != 0u;
                });
            if ((world.dispatch.flags & NM_MATTER_ADAPTIVE) != 0u ||
                world.dispatch.mpmGridCount != 0u ||
                world.dispatch.mpmBlockCount != 0u ||
                world.dispatch.particleCount != 0u ||
                world.dispatch.gridNodeCount != 0u ||
                world.dispatch.mutationCommandCount != 0u ||
                mutationCapacity != 0u || mutableObject ||
                world.dispatch.tetrahedronCount == 0u ||
                world.dispatch.surfaceFaceCount == 0u ||
                nodeCapacity != world.dispatch.femNodeCount ||
                tetrahedronCapacity != world.dispatch.tetrahedronCount ||
                world.dispatch.surfaceFaceCount !=
                    world.fem.surfaceFaces.size()) {
                diagnostics.message =
                    "static FEM surface map requires exact immutable FEM topology without adaptive, MPM, or mutation capacity";
                return diagnostics;
            }
        }
        if (world.dispatch.femHumanAttachmentCount >
                NM_MATTER_MAX_HUMAN_ATTACHMENT_POINTS ||
            !detail::femHumanAttachmentPointJacobianStrideFits(
                world.dispatch.femHumanAttachmentCount,
                world.dispatch.rigidGeneralizedCapacity) ||
            world.dispatch.femHumanAttachmentPointJacobianStride !=
                detail::femHumanAttachmentPointJacobianStride(
                    world.dispatch.femHumanAttachmentCount,
                    world.dispatch.rigidGeneralizedCapacity) ||
            (world.dispatch.femHumanAttachmentCount != 0u &&
             (world.dispatch.rigidGeneralizedCapacity == 0u ||
              world.dispatch.rigidQCapacity == 0u))) {
            diagnostics.message =
                "FEM Human attachments exceed the exact coupled-candidate point/Jacobian capacity";
            return diagnostics;
        }
        auto candidate = std::make_unique<State>();
        candidate->dispatch = world.dispatch;
        const char* parallelGraphSearch = std::getenv("NM_FEM_GRAPH_PARALLEL_LU_SEARCH");
        if (parallelGraphSearch != nullptr) {
            if (std::strcmp(parallelGraphSearch, "1") != 0 ||
                world.mixedSolver.executionBudgets.z != 5u) {
                diagnostics.message = "parallel graph LU search requires explicit value1 and graph selector5";
                return diagnostics;
            }
            candidate->femRegionalGraphParallelSearch = 1u;
        }
        const char* sortedNodeIncidence = std::getenv(
            "NM_CONTACT_NODE_INCIDENCE_SORT");
        if (sortedNodeIncidence != nullptr &&
            std::strcmp(sortedNodeIncidence, "1") != 0) {
            diagnostics.message =
                "NM_CONTACT_NODE_INCIDENCE_SORT must be exactly 1 when set";
            return diagnostics;
        }
        candidate->deformableContactNodeIncidenceSortEnabled =
            sortedNodeIncidence != nullptr;
        std::uint64_t sortedCornerLogicalCount = 0u;
        std::uint64_t sortedCornerPaddedCapacity = 0u;
        std::uint64_t sortedCornerTotalCount = 0u;
        if (candidate->deformableContactNodeIncidenceSortEnabled) {
            const std::uint64_t contactCapacity =
                world.dispatch.deformableContactCapacity;
            const std::uint64_t environments =
                world.dispatch.environmentCount;
            const std::uint64_t nodeCount =
                static_cast<std::uint64_t>(world.dispatch.gridNodeCount) +
                world.dispatch.femNodeCount;
            if (contactCapacity == 0u || environments == 0u ||
                nodeCount == 0u ||
                nodeCount > std::numeric_limits<std::uint32_t>::max() /
                    environments ||
                contactCapacity >
                    (std::numeric_limits<std::uint32_t>::max() - 5ull) / 8ull) {
                diagnostics.message =
                    "sorted deformable incidence requires nonzero contact, node, environment counts and uint32-safe payload identities";
                return diagnostics;
            }
            sortedCornerLogicalCount = 6ull * contactCapacity;
            if (sortedCornerLogicalCount >
                    std::numeric_limits<std::uint32_t>::max() ||
                sortedCornerLogicalCount >
                    (std::uint64_t{1} << 31u)) {
                diagnostics.message =
                    "sorted deformable corner record count exceeds the checked bitonic sort domain";
                return diagnostics;
            }
            sortedCornerPaddedCapacity = std::bit_ceil(
                sortedCornerLogicalCount);
            if (sortedCornerPaddedCapacity == 0u ||
                sortedCornerPaddedCapacity >
                    std::numeric_limits<std::uint32_t>::max() ||
                sortedCornerPaddedCapacity >
                    std::numeric_limits<std::uint32_t>::max() / environments) {
                diagnostics.message =
                    "sorted deformable corner workspace exceeds the uint32 Metal dispatch domain";
                return diagnostics;
            }
            sortedCornerTotalCount =
                sortedCornerPaddedCapacity * environments;
            if (sortedCornerTotalCount >
                    std::numeric_limits<std::size_t>::max() /
                        sizeof(std::uint64_t) ||
                sortedCornerTotalCount >
                    std::numeric_limits<std::size_t>::max() /
                        sizeof(std::uint32_t)) {
                diagnostics.message =
                    "sorted deformable corner workspace exceeds host allocation sizing";
                return diagnostics;
            }
            candidate->deformableContactNodeCornerSortPaddedCapacity =
                static_cast<std::uint32_t>(sortedCornerPaddedCapacity);
        }
        const char* forceCompletedTangentCacheRebuild = std::getenv(
            "NM_FEM_FORCE_COMPLETED_TANGENT_CACHE_REBUILD");
        if (forceCompletedTangentCacheRebuild != nullptr &&
            std::strcmp(forceCompletedTangentCacheRebuild, "1") != 0) {
            diagnostics.message =
                "NM_FEM_FORCE_COMPLETED_TANGENT_CACHE_REBUILD must be exactly 1";
            return diagnostics;
        }
        if (forceCompletedTangentCacheRebuild != nullptr &&
            world.mixedSolver.executionBudgets.w != 1u) {
            diagnostics.message =
                "forced completed tangent-cache rebuild requires the algorithmic tangent cache";
            return diagnostics;
        }
        candidate->forceCompletedTangentCacheRebuild =
            forceCompletedTangentCacheRebuild != nullptr;
        if (candidate->forceCompletedTangentCacheRebuild) {
            std::fprintf(stderr,
                "matter_tangent_cache_control={\"schema\":1,\"completed_tail_rebuild\":true}\n");
        }
        const SparseArmijoContactOptions sparseArmijoOptions =
            sparseArmijoContactOptionsFromEnvironment();
        if (sparseArmijoOptions.error != nullptr) {
            diagnostics.message = sparseArmijoOptions.error;
            return diagnostics;
        }
        if (sparseArmijoOptions.requested) {
            const char* rootSelector = std::getenv(
                "NM_FEM_FULL_CONTACT_RESIDUAL_ARMIJO_ROOT");
            if (rootSelector == nullptr) {
                diagnostics.message =
                    "sparse private contact capacity requires the full-contact Armijo selector";
                return diagnostics;
            }
            if (std::strcmp(rootSelector, "all") != 0) {
                if (rootSelector[0] == '\0') {
                    diagnostics.message =
                        "full-contact Armijo selector is empty while sparse private contact is requested";
                    return diagnostics;
                }
                std::uint64_t selectedRoot = 0u;
                for (const char* cursor = rootSelector; *cursor != '\0'; ++cursor) {
                    if (*cursor < '0' || *cursor > '9') {
                        diagnostics.message =
                            "sparse private contact requires a decimal full-contact Armijo selector or all";
                        return diagnostics;
                    }
                    const std::uint32_t digit =
                        static_cast<std::uint32_t>(*cursor - '0');
                    if (selectedRoot >
                        (std::numeric_limits<std::uint32_t>::max() - digit) / 10u) {
                        diagnostics.message =
                            "full-contact Armijo selector exceeds uint32 indexing";
                        return diagnostics;
                    }
                    selectedRoot = selectedRoot * 10u + digit;
                }
            }
            const auto sparseAdmission = detail::admitSparsePrivateContact(
                world.dispatch.environmentCount,
                world.dispatch.contactPairCount,
                sparseArmijoOptions.capacity,
                sparseArmijoOptions.parity,
                world.dispatch.rigidGeneralizedCapacity != 0u ||
                    world.dispatch.rigidQCapacity != 0u,
                sparsePrivateBoundedFreeBoxLayout(world));
            if (!sparseAdmission.admitted()) {
                diagnostics.message =
                    detail::sparsePrivateContactAdmissionErrorText(
                        sparseAdmission.error);
                return diagnostics;
            }
            candidate->femArmijoSparseContactRequested = true;
            candidate->femArmijoSparseContactParity =
                sparseArmijoOptions.parity;
            candidate->femArmijoSparseContactCapacity =
                sparseArmijoOptions.capacity;
        }
        const char* surfaceScratchAlias = std::getenv(
            "NM_FEM_FULL_CONTACT_REUSE_SELF_SURFACE_SCRATCH");
        if (surfaceScratchAlias != nullptr &&
            std::strcmp(surfaceScratchAlias, "1") != 0) {
            diagnostics.message =
                "NM_FEM_FULL_CONTACT_REUSE_SELF_SURFACE_SCRATCH must be exactly 1";
            return diagnostics;
        }
        if (surfaceScratchAlias != nullptr &&
            std::getenv("NM_FEM_FULL_CONTACT_RESIDUAL_ARMIJO_ROOT") == nullptr) {
            diagnostics.message =
                "self-surface scratch reuse requires the full-contact Armijo selector";
            return diagnostics;
        }
        candidate->femArmijoAliasesProductionSurfaceScratch =
            surfaceScratchAlias != nullptr;
        const char* cohesiveScratchAlias = std::getenv(
            "NM_FEM_FULL_CONTACT_REUSE_COHESIVE_SCRATCH");
        if (cohesiveScratchAlias != nullptr &&
            std::strcmp(cohesiveScratchAlias, "1") != 0) {
            diagnostics.message =
                "NM_FEM_FULL_CONTACT_REUSE_COHESIVE_SCRATCH must be exactly 1";
            return diagnostics;
        }
        if (cohesiveScratchAlias != nullptr &&
            (std::getenv("NM_FEM_FULL_CONTACT_RESIDUAL_ARMIJO_ROOT") == nullptr ||
             std::getenv("NM_FEM_RESIDUAL_ARMIJO_ROOT") != nullptr ||
             std::getenv("NM_FEM_CAPSULE_RESIDUAL_ARMIJO_ROOT") != nullptr ||
             std::getenv("NM_FEM_CAPSULE_BOX_RESIDUAL_ARMIJO_ROOT") != nullptr ||
             std::getenv("NM_FEM_COHESIVE_RESIDUAL_ARMIJO_ROOT") != nullptr)) {
            diagnostics.message =
                "cohesive scratch reuse requires the exclusive full-contact Armijo selector";
            return diagnostics;
        }
        candidate->femArmijoAliasesCohesiveScratch =
            cohesiveScratchAlias != nullptr;
        candidate->materialNames.reserve(world.constitutive.size());
        candidate->materialParameterOffsets.reserve(world.constitutive.size());
        candidate->materialParameterNames.reserve(world.constitutive.size());
        for (std::size_t index = 0u; index < world.constitutive.size(); ++index) {
            const auto& material = world.constitutive[index];
            candidate->materialNames.push_back(material.material.name);
            candidate->materialParameterOffsets.push_back(
                world.materials[index].parameterOffset);
            std::vector<std::string> names;
            names.reserve(material.material.parameters.size());
            for (const auto& parameter : material.material.parameters)
                names.push_back(parameter.name);
            candidate->materialParameterNames.push_back(std::move(names));
        }
        candidate->coupledCandidateCompensatedTranslation =
            configuration.coupledCandidateCompensatedTranslation;
        candidate->vascularValue = world.vascular;
        candidate->objectLayout = world.objects;
        candidate->femArmijoMixedCohesiveSupported =
            world.dispatch.cohesiveFaceCount != 0u &&
            detail::fullContactArmijoSupportsCohesiveFaces(
                world.fem.cohesiveFaces);
        candidate->femAuthoredMassLayout.reserve(world.fem.nodes.size());
        candidate->femAuthoredRestLayout.reserve(world.fem.nodes.size());
        candidate->femMutableMassRestLayout.assign(world.fem.nodes.size(), 0u);
        for (const auto& object : world.objects) {
            if (object.representation != NM_REPRESENTATION_FEM ||
                (object.flags & NM_OBJECT_MUTABLE_TOPOLOGY) == 0u) continue;
            const std::size_t end = static_cast<std::size_t>(object.stateOffset) +
                object.stateCount;
            for (std::size_t node = object.stateOffset;
                 node < end && node < candidate->femMutableMassRestLayout.size(); ++node)
                candidate->femMutableMassRestLayout[node] = 1u;
        }
        for (const auto& node : world.fem.nodes) {
            candidate->femAuthoredMassLayout.push_back({
                node.positionAndMass.w, node.velocityAndInverseMass.w});
            candidate->femAuthoredRestLayout.push_back(node.restAndFixed);
        }
        if (staticFEMSurfaceMapEnabled(world.dispatch) ||
            std::any_of(world.objects.begin(), world.objects.end(),
                [](const NMContinuumObjectGPU& object) {
                    return (object.flags & (NM_OBJECT_FEM_MATERIAL_FRAME | NM_OBJECT_FEM_REGIONAL_MATERIAL | NM_OBJECT_FEM_REFERENCE_CONFIGURATION | NM_OBJECT_FEM_REFERENCE_DISPLACEMENT_GRADIENT)) != 0u;
                })) {
            candidate->femImmutableElementLayout = world.fem.tetrahedra;
            candidate->femImmutableNodeLayout = world.fem.topologyNodes;
            candidate->femImmutableCohesiveLayout = world.fem.cohesiveFaces;
            candidate->femImmutablePunctureLayout = world.fem.punctureChannels;
        }
        if (std::any_of(world.objects.begin(), world.objects.end(),
                [](const NMContinuumObjectGPU& object) {
                    return (object.flags & (NM_OBJECT_FEM_REGIONAL_MATERIAL | NM_OBJECT_FEM_REFERENCE_CONFIGURATION | NM_OBJECT_FEM_REFERENCE_DISPLACEMENT_GRADIENT)) != 0u;
                })) {
            std::set<std::uint32_t> regionalMaterials;
            for (const auto& object : world.objects) {
                if ((object.flags & (NM_OBJECT_FEM_REGIONAL_MATERIAL | NM_OBJECT_FEM_REFERENCE_CONFIGURATION | NM_OBJECT_FEM_REFERENCE_DISPLACEMENT_GRADIENT)) == 0u) continue;
                regionalMaterials.insert(object.materialIndex);
                candidate->femRegionalBaseExponentLayout.emplace_back(
                    object.schedulerIndex, world.schedulers[object.schedulerIndex].baseExponent);
                for (std::uint32_t local = 0u; local < object.elementCount; ++local)
                    regionalMaterials.insert(world.fem.tetrahedra[object.elementOffset + local].identity.x);
            }
            for (const auto materialIndex : regionalMaterials) {
                const auto& material = world.materials[materialIndex];
                for (std::uint32_t local = 0u; local < material.parameterCount; ++local) {
                    const auto parameter = material.parameterOffset + local;
                    candidate->femRegionalFixedParameterLayout.emplace_back(parameter, world.parameters[parameter].valueAndBounds.x);
                }
            }
            for (const auto& distribution : world.identification)
                candidate->femRegionalIdentificationIdentityLayout.push_back(distribution.identity);
        }
        for (const auto& object : world.objects) {
            if ((object.flags & (NM_OBJECT_FEM_REFERENCE_CONFIGURATION | NM_OBJECT_FEM_REFERENCE_DISPLACEMENT_GRADIENT)) == 0u) continue;
            candidate->femReferenceCenterLayout.emplace_back(object.schedulerIndex, world.adaptive[object.schedulerIndex].referenceCenter);
            for (std::uint32_t local = 0u; local < object.elementCount; ++local) {
                const auto index = object.elementOffset + local;
                const auto& tet = world.fem.tetrahedra[index];
                if ((tet.identity.w & NM_OBJECT_ACTIVE) != 0u)
                    candidate->femReferenceDeterminantLimits.emplace_back(index, world.materials[tet.identity.x].validity);
            }
        }
        candidate->hasMutableFEMTopology = std::any_of(
            world.objects.begin(), world.objects.end(),
            [](const NMContinuumObjectGPU& object) {
                return object.representation == NM_REPRESENTATION_FEM &&
                    (object.flags & NM_OBJECT_MUTABLE_TOPOLOGY) != 0u;
            });
        candidate->capacityLayout = world.fem.capacities;
        const std::uint64_t incidenceStride64 = std::max<std::uint64_t>(
            1u,
            static_cast<std::uint64_t>(world.dispatch.tetrahedronCount) * 4u
        );
        const std::uint64_t environmentCount64 =
            world.dispatch.environmentCount;
        const bool incidenceCapacityExceedsU32 =
            environmentCount64 == 0u ||
            incidenceStride64 >
                std::numeric_limits<std::uint32_t>::max() /
                    environmentCount64;
        const std::uint64_t environmentIncidenceCount64 =
            incidenceCapacityExceedsU32
                ? std::numeric_limits<std::uint64_t>::max()
                : incidenceStride64 * environmentCount64;
        if (incidenceCapacityExceedsU32 ||
            environmentIncidenceCount64 >
                std::numeric_limits<std::size_t>::max() /
                    sizeof(std::uint32_t) ||
            world.fem.nodeIncidence.size() > incidenceStride64 ||
            world.fem.nodeRanges.size() >
                std::numeric_limits<std::uint32_t>::max()) {
            diagnostics.message =
                "Matter topology incidence exceeds accepted-state proof ABI capacity";
            return diagnostics;
        }
        // Topology rebuild indexes one four-entry corner slot per tetrahedron,
        // including dormant reserved tetrahedra. Keep this full per-environment
        // arena from initialization so later accepted mutations never write past
        // the buffer that snapshot restore and rollback checkpoints own.
        candidate->femNodeIncidenceStride = static_cast<std::uint32_t>(
            incidenceStride64);
        candidate->femNodeRangeStride = static_cast<std::uint32_t>(
            world.fem.nodeRanges.size());
        candidate->mixedSolverValue = world.mixedSolver;
        candidate->mutationFingerprint = detail::hashBytes(
            world.fem.mutationCommands.data(),
            world.fem.mutationCommands.size() * sizeof(NMMutationCommandGPU)
        );
        candidate->learnedFingerprint = detail::hashBytes(
            world.learnedWeights.data(),
            world.learnedWeights.size() * sizeof(float)
        );
        candidate->sourcePhysicsFingerprint = world.physicsFingerprint;
        candidate->worldFingerprint = world.fingerprint;
        candidate->captureEvents = configuration.captureEvents;
        candidate->captureDiagnostics = configuration.captureDiagnostics;
        candidate->automaticIdentification =
            configuration.automaticIdentification;
        candidate->adaptiveTransfer = configuration.adaptiveTransfer;
        candidate->identificationDistributionCount =
            static_cast<std::uint32_t>(world.identification.size());
        candidate->hasAdaptive =
            (world.dispatch.flags & NM_MATTER_ADAPTIVE) != 0u;
        candidate->device = MTLCreateSystemDefaultDevice();
        if (candidate->device == nil) {
            diagnostics.message = "no Metal device is available";
            return diagnostics;
        }
        candidate->queue = [candidate->device newCommandQueue];
        if (candidate->queue == nil) {
            diagnostics.message = "failed to create Numi Matter command queue";
            return diagnostics;
        }
        const auto& equalities = configuration.humanJointEqualities;
        const auto eq = configuration.humanEqualityDispatch;
        const bool emptyEquality = equalities.empty();
        if (eq.count != equalities.size() ||
            (!emptyEquality &&
             (eq.policy != NM_HUMAN_EQUALITY_POLICY_MUJOCO_312_CLASSIC ||
              (eq.flags & ~NM_HUMAN_EQUALITY_REFSAFE) != 0u ||
              eq.reserved0 != 0u || eq.reserved1 != 0u || eq.reserved2 != 0u ||
              eq.dofCount < 6u || eq.dofCount > 160u ||
              eq.qCount != eq.dofCount + 1u ||
              eq.dofCount > world.dispatch.rigidGeneralizedCapacity ||
              eq.count > eq.dofCount || world.dispatch.maximumRateExponent != 0u ||
              configuration.humanEqualitySourceFingerprint == 0u ||
              eq.time.x != 0.0f || eq.time.y != 0.0f || eq.time.z != 0.0f || eq.time.w != 0.0f)) ||
            (emptyEquality && (eq.qCount != 0u || eq.dofCount != 0u ||
              eq.flags != 0u || eq.policy != 0u || eq.reserved0 != 0u ||
              eq.reserved1 != 0u || eq.reserved2 != 0u ||
              eq.time.x != 0.0f || eq.time.y != 0.0f || eq.time.z != 0.0f || eq.time.w != 0.0f ||
              configuration.humanEqualitySourceFingerprint != 0u))) {
            diagnostics.message = "invalid NHEQ2 source compliance program header";
            return diagnostics;
        }
        std::vector<bool> dependent(eq.dofCount, false);
        for (const auto& row : equalities) {
            const bool fixed = row.indices.z == NM_INVALID_INDEX;
            const auto* scalars = reinterpret_cast<const float*>(&row.referencesAndCoefficients0);
            bool finite = true;
            for (std::size_t i=0u; i<24u; ++i) finite = finite && std::isfinite(scalars[i]);
            if (!finite || row.indices.y < 6u || row.indices.y >= eq.dofCount ||
                row.indices.x != row.indices.y + 1u ||
                (fixed ? row.indices.w != NM_INVALID_INDEX :
                 (row.indices.w < 6u || row.indices.w >= eq.dofCount ||
                  row.indices.z != row.indices.w + 1u || row.indices.y == row.indices.w)) ||
                dependent[row.indices.y] || row.coefficients1.w != 0.0f ||
                row.solref.z != 0.0f || row.solref.w != 0.0f ||
                !((row.solref.x > 0.0f && row.solref.y > 0.0f) ||
                  (row.solref.x <= 0.0f && row.solref.y <= 0.0f)) ||
                row.solimp1.y != 0.0f || row.solimp1.z != 0.0f || row.solimp1.w != 0.0f ||
                !(row.sourceInverseWeights.x > 0.0f) ||
                (fixed ? row.sourceInverseWeights.y != 0.0f : !(row.sourceInverseWeights.y > 0.0f)) ||
                row.sourceInverseWeights.z != 0.0f || row.sourceInverseWeights.w != 0.0f) {
                diagnostics.message = "invalid NHEQ2 scalar row or source inverse weight";
                return diagnostics;
            }
            dependent[row.indices.y] = true;
        }
        for (const auto& row : equalities) {
            if (row.indices.w != NM_INVALID_INDEX && dependent[row.indices.w]) {
                diagnostics.message = "NHEQ2 dependent chains require a separately qualified source profile";
                return diagnostics;
            }
        }
        candidate->humanEqualityDispatch = eq;
        if (!emptyEquality) {
            candidate->requiresCoupledCandidate = true;
            candidate->sourcePhysicsFingerprint = mixFingerprint(
                candidate->sourcePhysicsFingerprint,
                configuration.humanEqualitySourceFingerprint);
            candidate->sourcePhysicsFingerprint = mixFingerprint(
                candidate->sourcePhysicsFingerprint,
                detail::hashBytes(equalities.data(), equalities.size_bytes()));
        }
        const auto& limits = configuration.humanJointLimits;
        const auto lim = configuration.humanLimitDispatch;
        const bool emptyLimits = limits.empty();
        if (lim.count != limits.size() ||
            (!emptyLimits && (emptyEquality || lim.policy != eq.policy || lim.flags != eq.flags ||
             lim.qCount != eq.qCount || lim.dofCount != eq.dofCount || lim.count > lim.dofCount - 6u ||
             lim.reserved0 != 0u || lim.reserved1 != 0u || lim.reserved2 != 0u ||
             lim.time.x != 0.0f || lim.time.y != 0.0f || lim.time.z != 0.0f || lim.time.w != 0.0f ||
             configuration.humanLimitSourceFingerprint == 0u)) ||
            (emptyLimits && (lim.qCount != 0u || lim.dofCount != 0u || lim.policy != 0u ||
             lim.flags != 0u || lim.reserved0 != 0u || lim.reserved1 != 0u || lim.reserved2 != 0u ||
             lim.time.x != 0.0f || lim.time.y != 0.0f || lim.time.z != 0.0f || lim.time.w != 0.0f ||
             configuration.humanLimitSourceFingerprint != 0u))) {
