                    valid, candidate->residentBytes);
                candidate->femOperatorFDTetrahedronSnapshot = privateScratch<std::uint32_t>(
                    candidate->device,
                    multiplied(static_cast<std::size_t>(world.dispatch.tetrahedronCount) *
                        sizeof(NMTetrahedronGPU) / sizeof(std::uint32_t)),
                    valid, candidate->residentBytes);
                candidate->femOperatorFDStatusSnapshot = privateScratch<std::uint32_t>(
                    candidate->device,
                    multiplied(sizeof(NMMatterStatusGPU) / sizeof(std::uint32_t)),
                    valid, candidate->residentBytes);
                if (candidate->femOperatorFDRichCaptureEnabled) {
                    candidate->femOperatorFDNodeSnapshot =
                        privateScratch<NMFEMNodeStateGPU>(candidate->device,
                            multiplied(world.dispatch.femNodeCount),
                            valid, candidate->residentBytes);
                    candidate->femOperatorFDRichCapture =
                        privateScratch<nm_float4>(candidate->device,
                            operatorFDRichCaptureSlots,
                            valid, candidate->residentBytes);
                }
                candidate->femOperatorFDInputsUnchanged = privateScratch<std::uint32_t>(
                    candidate->device, multiplied(1u),
                    valid, candidate->residentBytes);
            }
        }
        const std::size_t fgmresUnknownTotal = mixedUnknownTotal;
        const std::size_t fgmresSystemTotal = multiplied(1u);
        const std::size_t configuredRestart = std::clamp<std::size_t>(
            world.mixedSolver.nonlinearIterations.y,
            1u,
            NM_MIXED_FGMRES_RESTART);
        candidate->fgmresBasis = privateScratch<nm_float4>(
            candidate->device,
            fgmresUnknownTotal * (configuredRestart + 1u),
            valid, candidate->residentBytes);
        candidate->fgmresPreconditionedBasis = privateScratch<nm_float4>(
            candidate->device,
            fgmresUnknownTotal * configuredRestart,
            valid, candidate->residentBytes);
        candidate->fgmresHessenberg = privateScratch<float>(
            candidate->device,
            fgmresSystemTotal * (NM_MIXED_FGMRES_RESTART + 1u) *
                NM_MIXED_FGMRES_RESTART,
            valid, candidate->residentBytes);
        candidate->fgmresRotations = privateScratch<float>(
            candidate->device,
            fgmresSystemTotal * NM_MIXED_FGMRES_RESTART * 2u,
            valid, candidate->residentBytes);
        candidate->fgmresLeastSquares = privateScratch<float>(
            candidate->device,
            fgmresSystemTotal * (NM_MIXED_FGMRES_RESTART + 1u),
            valid, candidate->residentBytes);
        candidate->fgmresRestartCoefficients = privateScratch<float>(
            candidate->device,
            fgmresSystemTotal * (NM_MIXED_FGMRES_RESTART + 1u),
            valid, candidate->residentBytes);
        candidate->fgmresStates = privateScratch<NMFGMRESStateGPU>(
            candidate->device, fgmresSystemTotal,
            valid, candidate->residentBytes);
        if (world.mixedSolver.executionBudgets.w == 1u) {
            const std::uint64_t totalTetrahedra =
                static_cast<std::uint64_t>(world.dispatch.environmentCount) *
                world.dispatch.tetrahedronCount;
            constexpr std::uint64_t cacheScalarsPerTetrahedron = 81u;
            if (totalTetrahedra == 0u ||
                totalTetrahedra >
                    std::numeric_limits<std::uint32_t>::max() /
                        cacheScalarsPerTetrahedron ||
                totalTetrahedra >
                    std::numeric_limits<std::size_t>::max() /
                        (cacheScalarsPerTetrahedron * sizeof(float))) {
                diagnostics.message =
                    "algorithmic tangent cache exceeds checked Metal indexing";
                return diagnostics;
            }
            const std::uint64_t tangentBytes = totalTetrahedra *
                cacheScalarsPerTetrahedron * sizeof(float);
            const std::uint64_t validBytes = totalTetrahedra *
                sizeof(std::uint32_t);
            if (tangentBytes > candidate->device.maxBufferLength ||
                validBytes > candidate->device.maxBufferLength) {
                diagnostics.message =
                    "algorithmic tangent cache exceeds one Metal buffer limit";
                return diagnostics;
            }
            candidate->femAlgorithmicTangentCache =
                privateScratch<float>(candidate->device,
                    static_cast<std::size_t>(totalTetrahedra *
                        cacheScalarsPerTetrahedron),
                    valid, candidate->residentBytes);
            candidate->femAlgorithmicTangentCacheValid =
                privateScratch<std::uint32_t>(candidate->device,
                    static_cast<std::size_t>(totalTetrahedra),
                    valid, candidate->residentBytes);
        }
        if (candidate->femRegionalModeCount != 0u) {
            const std::size_t modes = candidate->femRegionalModeCount;
            const std::size_t nodes = world.dispatch.femNodeCount;
            const std::size_t modeNodeCount = modes * nodes;
            candidate->femRegionalEffectiveBasis = privateScratch<nm_float4>(
                candidate->device, multiplied(modeNodeCount),
                valid, candidate->residentBytes);
            candidate->femRegionalAP = privateScratch<nm_float4>(
                candidate->device, multiplied(modeNodeCount),
                valid, candidate->residentBytes);
            if (candidate->captureDiagnostics) {
                candidate->femRegionalLinearizationNodes =
                    privateScratch<NMFEMNodeStateGPU>(
                        candidate->device,
                        multiplied(world.dispatch.femNodeCount), valid,
                        candidate->residentBytes);
                candidate->femRegionalLinearizationMaterialState =
                    privateScratch<float>(candidate->device,
                        multiplied(world.dispatch.tetrahedronCount) *
                            world.dispatch.materialStateStride,
                        valid, candidate->residentBytes);
                candidate->femRegionalLinearizationSchedulerExponent =
                    privateScratch<std::uint32_t>(candidate->device,
                        multiplied(world.dispatch.tetrahedronCount), valid,
                        candidate->residentBytes);
                candidate->femRegionalLinearizationLocalFHigh =
                    privateScratch<nm_float4>(candidate->device,
                        multiplied(world.dispatch.tetrahedronCount) * 3u, valid,
                        candidate->residentBytes);
                candidate->femRegionalLinearizationLocalFLow =
                    privateScratch<nm_float4>(candidate->device,
                        multiplied(world.dispatch.tetrahedronCount) * 3u, valid,
                        candidate->residentBytes);
            }
            candidate->femRegionalCoarseMatrix = privateScratch<float>(
                candidate->device, multiplied(modes * modes),
                valid, candidate->residentBytes);
            candidate->femRegionalCoarsePivots =
                privateScratch<std::uint32_t>(candidate->device,
                    multiplied(modes), valid, candidate->residentBytes);
            candidate->femRegionalCoarseRHS = privateScratch<float>(
                candidate->device, multiplied(modes),
                valid, candidate->residentBytes);
            candidate->femRegionalCoarseCoefficients =
                privateScratch<float>(candidate->device,
                    multiplied(modes), valid, candidate->residentBytes);
            candidate->femRegionalCoarseValid = privateScratch<std::uint32_t>(
                candidate->device, environments, valid,
                candidate->residentBytes);
            if (world.mixedSolver.executionBudgets.z == 3u ||
                world.mixedSolver.executionBudgets.z == 4u) {
                candidate->femRegionalNodeBlockInverse =
                    privateScratch<nm_float4>(candidate->device,
                        multiplied(std::size_t{3u} *
                                   world.dispatch.femNodeCount),
                        valid, candidate->residentBytes);
            }
        }
        if (candidate->femRegionalGraphPatchCount != 0u) {
            candidate->femRegionalGraphOriginalMatrices = privateScratch<float>(
                candidate->device,
                multiplied(candidate->femRegionalGraphMatrixFloatCount),
                valid, candidate->residentBytes);
            candidate->femRegionalGraphFactors = privateScratch<float>(
                candidate->device,
                multiplied(candidate->femRegionalGraphMatrixFloatCount),
                valid, candidate->residentBytes);
            candidate->femRegionalGraphPivots =
                privateScratch<std::uint32_t>(candidate->device,
                    multiplied(candidate->femRegionalGraphPivotCount),
                    valid, candidate->residentBytes);
            candidate->femRegionalGraphFactorValid =
                privateScratch<std::uint32_t>(candidate->device,
                    multiplied(candidate->femRegionalGraphPatchCount),
                    valid, candidate->residentBytes);
            candidate->femRegionalGraphPatchCorrections =
                privateScratch<nm_float4>(candidate->device,
                    multiplied(candidate->femRegionalGraphPatchNodeCount),
                    valid, candidate->residentBytes);
        }
        candidate->solverCertificates = privateScratch<NMSolverCertificateGPU>(
            candidate->device, multiplied(world.dispatch.objectCount),
            valid, candidate->residentBytes);
        candidate->identificationCandidates =
            privateScratch<NMIdentificationCandidateGPU>(
                candidate->device,
                static_cast<std::size_t>(world.dispatch.identificationCandidateCount) *
                    world.identification.size(),
                valid,
                candidate->residentBytes
            );
        candidate->identificationLosses = sharedScratch<float>(
            candidate->device,
            world.dispatch.identificationCandidateCount,
            valid,
            candidate->residentBytes
        );
        candidate->statuses = sharedScratch<NMMatterStatusGPU>(
            candidate->device,
            environments,
            valid,
            candidate->residentBytes
        );
        candidate->acceptedControlCursor = sharedScratch<nm_uint4>(
            candidate->device, 1u, valid, candidate->residentBytes);
        const auto proofBytes = [&](const std::uint64_t count,
                                    const std::uint64_t elementBytes) {
            if (count != 0u && elementBytes >
                    std::numeric_limits<std::uint64_t>::max() / count) {
                valid = false;
                return std::uint64_t{0u};
            }
            return count * elementBytes;
        };
        const std::array proofArenaBytes{
            proofBytes(1u, sizeof(MRCompensatedRootTranslationGPU)),
            proofBytes(candidate->dispatch.rigidQCapacity, sizeof(float)),
            proofBytes(
                candidate->dispatch.rigidGeneralizedCapacity, sizeof(float)),
            candidate->acceptedStateProofMujocoBytesPerEnvironmentCapacity,
            proofBytes(
                candidate->dispatch.rigidGeneralizedCapacity, sizeof(float)),
            proofBytes(candidate->dispatch.particleCount,
                       sizeof(NMParticleStateGPU)),
            proofBytes(
                proofBytes(candidate->dispatch.particleCount,
                           candidate->dispatch.materialStateStride),
                sizeof(float)),
            proofBytes(candidate->dispatch.femNodeCount,
                       sizeof(NMFEMNodeStateGPU)),
            proofBytes(
                proofBytes(candidate->dispatch.tetrahedronCount,
                           candidate->dispatch.materialStateStride),
                sizeof(float)),
            proofBytes(candidate->dispatch.femNodeCount,
                       sizeof(NMFEMFieldStateGPU)),
            proofBytes(candidate->vascularValue.layout.ranges.z,
                       sizeof(nm_float4)),
            proofBytes(candidate->vascularValue.layout.ranges.z == 0u ? 0u : 1u,
                       sizeof(NMVascularClockGPU)),
            proofBytes(candidate->dispatch.tetrahedronCount,
                       sizeof(NMTetrahedronGPU)),
            proofBytes(candidate->dispatch.topologyNodeCapacity,
                       sizeof(NMFEMTopologyNodeGPU)),
            proofBytes(candidate->dispatch.cohesiveFaceCount,
                       sizeof(NMCohesiveFaceGPU)),
            proofBytes(candidate->dispatch.punctureChannelCount,
                       sizeof(NMPunctureChannelGPU)),
            proofBytes(candidate->dispatch.objectCount,
                       sizeof(NMFEMTopologyStateGPU)),
            proofBytes(candidate->dispatch.learnedWeightCount, sizeof(float)),
            proofBytes(candidate->dispatch.contactPairCount, sizeof(nm_float4)),
            proofBytes(candidate->humanSupportDispatch.contactCount,
                       sizeof(nm_float4)),
            proofBytes(candidate->humanSupportDispatch.contactCount,
                       sizeof(NMHumanSupportConsequenceGPU)),
            proofBytes(candidate->dispatch.deformableContactCapacity,
                       sizeof(NMDeformableContactHistoryGPU)),
            proofBytes(candidate->dispatch.rigidGeneralizedCapacity,
                       sizeof(float)),
            proofBytes(candidate->dispatch.rigidProxyCount,
                       sizeof(NMRigidReactionGPU)),
            proofBytes(candidate->dispatch.rigidProxyCount,
                       sizeof(NMRigidStateGPU)),
            proofBytes(candidate->dispatch.objectCount,
                       sizeof(NMAdaptiveStateGPU)),
            proofBytes(candidate->dispatch.objectCount,
                       sizeof(NMSchedulerStateGPU)),
            proofBytes(candidate->identificationDistributionCount,
                       sizeof(NMIdentificationDistributionGPU)),
            proofBytes(candidate->dispatch.parameterCount, sizeof(float)),
            proofBytes(candidate->femNodeIncidenceStride,
                       sizeof(std::uint32_t)),
            proofBytes(candidate->femNodeRangeStride,
                       sizeof(NMIncidenceRangeGPU)),
        };
        const std::uint64_t maximumProofArenaBytes =
            *std::max_element(proofArenaBytes.begin(), proofArenaBytes.end());
        const std::uint64_t proofScratchStride64 = std::max<std::uint64_t>(
            1u,
            maximumProofArenaBytes /
                    detail::kAcceptedStateProofChunkBytes +
                (maximumProofArenaBytes %
                     detail::kAcceptedStateProofChunkBytes != 0u));
        if (proofScratchStride64 >
                std::numeric_limits<std::uint32_t>::max()) {
            valid = false;
        } else {
            candidate->acceptedStateProofScratchStride =
                static_cast<std::uint32_t>(proofScratchStride64);
        }
        const std::uint64_t proofScratchCount64 = valid
            ? static_cast<std::uint64_t>(environments) *
                candidate->acceptedStateProofScratchStride
            : 0u;
        const std::uint64_t proofHashCount64 =
            static_cast<std::uint64_t>(environments) * 2u;
        if (proofScratchCount64 >
                std::numeric_limits<std::uint32_t>::max() ||
            proofScratchCount64 >
                std::numeric_limits<std::size_t>::max() ||
            proofHashCount64 >
                std::numeric_limits<std::uint32_t>::max() ||
            proofHashCount64 >
                std::numeric_limits<std::size_t>::max()) {
            valid = false;
        }
        const std::size_t proofScratchCount = valid
            ? static_cast<std::size_t>(proofScratchCount64)
            : 0u;
        const std::size_t proofResidentBefore = candidate->residentBytes;
        candidate->acceptedStateProofHashes = privateScratch<std::uint64_t>(
            candidate->device,
            valid ? static_cast<std::size_t>(proofHashCount64) : 0u,
            valid,
            candidate->residentBytes
        );
        candidate->acceptedStateProofScratchA = privateScratch<std::uint64_t>(
            candidate->device,
            proofScratchCount,
            valid,
            candidate->residentBytes
        );
        candidate->acceptedStateProofScratchB = privateScratch<std::uint64_t>(
            candidate->device,
            proofScratchCount,
            valid,
            candidate->residentBytes
        );
        if (physicalStateDigestEnabled) {
            candidate->physicalStateDigestScratchA =
                privateScratch<NMSHA256DigestGPU>(
                    candidate->device,
                    proofScratchCount,
                    valid,
                    candidate->residentBytes
                );
            candidate->physicalStateDigestScratchB =
                privateScratch<NMSHA256DigestGPU>(
                    candidate->device,
                    proofScratchCount,
                    valid,
                    candidate->residentBytes
                );
            candidate->physicalStateDigestContexts =
                privateScratch<NMSHA256ContextGPU>(
                    candidate->device,
                    proofScratchCount,
                    valid,
                    candidate->residentBytes
                );
            candidate->physicalStateDigestLeafMetadata =
                privateScratch<NMPhysicalStateDigestLeafMetadataGPU>(
                    candidate->device,
                    proofScratchCount,
                    valid,
                    candidate->residentBytes
                );
            const std::uint64_t physicalSourceRootCount64 =
                static_cast<std::uint64_t>(environments) *
                NM_MATTER_PHYSICAL_STATE_DIGEST_SOURCE_COUNT;
            if (physicalSourceRootCount64 >
                    std::numeric_limits<std::uint32_t>::max() ||
                physicalSourceRootCount64 >
                    std::numeric_limits<std::size_t>::max()) {
                valid = false;
            }
            candidate->physicalStateDigestSourceRoots =
                privateScratch<NMSHA256DigestGPU>(
                    candidate->device,
                    valid ? static_cast<std::size_t>(
                        physicalSourceRootCount64) : 0u,
                    valid,
                    candidate->residentBytes
                );
        }
        candidate->preparedStateBindings =
            privateScratch<NMPreparedStateBindingGPU>(
                candidate->device, environments,
                valid, candidate->residentBytes);
        candidate->preparedStateActions = privateScratch<std::uint32_t>(
            candidate->device, environments,
            valid, candidate->residentBytes);
        candidate->preparedStateRestoreStatuses =
            privateScratch<NMMatterStatusGPU>(
                candidate->device, environments,
                valid, candidate->residentBytes);
        candidate->preparedStateApplyOutcome =
            sharedScratch<std::uint32_t>(
                candidate->device, 1u,
                valid, candidate->residentBytes);
        candidate->preparedStatePublicationFacts =
            sharedScratch<NMPreparedStatePublicationFactsGPU>(
                candidate->device, 1u,
                valid, candidate->residentBytes);
        candidate->acceptedStateProofResidentByteCount =
            candidate->residentBytes - proofResidentBefore;
        candidate->events = sharedScratch<NMEventTokenGPU>(
            candidate->device,
            multiplied(world.dispatch.eventStride),
            valid,
            candidate->residentBytes
        );
        candidate->dummy = sharedScratch<std::uint8_t>(
            candidate->device, 256u, valid, candidate->residentBytes);
        if (!valid) {
            diagnostics.message = "failed to allocate persistent matter runtime state";
            return diagnostics;
        }

        candidate->primalContactArguments = [candidate->device
            newBufferWithLength:primalContactEncoder.encodedLength
                         options:MTLResourceStorageModeShared];
        if (candidate->primalContactArguments == nil) {
            diagnostics.message =
                "failed to allocate monolithic primal-contact argument table";
            return diagnostics;
        }
        [primalContactEncoder
            setArgumentBuffer:candidate->primalContactArguments offset:0u];
        [primalContactEncoder setBuffer:candidate->contactPairs
                                 offset:0u atIndex:0u];
        [primalContactEncoder setBuffer:candidate->contactSamples
                                 offset:0u atIndex:1u];
        [primalContactEncoder setBuffer:candidate->contactNodeIncidence
                                 offset:0u atIndex:2u];
        [primalContactEncoder setBuffer:candidate->contactNodeRanges
                                 offset:0u atIndex:3u];
        [primalContactEncoder setBuffer:candidate->contactActivePairs
                                 offset:0u atIndex:4u];
        [primalContactEncoder setBuffer:candidate->contactActiveSlotsByPair
                                 offset:0u atIndex:5u];
        [primalContactEncoder setBuffer:candidate->contactActiveCounts
                                 offset:0u atIndex:6u];
        [primalContactEncoder setBuffer:candidate->deformableContacts
                                 offset:0u atIndex:7u];
        [primalContactEncoder
            setBuffer:candidate->deformableContactNodeIncidence
               offset:0u atIndex:8u];
        [primalContactEncoder
            setBuffer:candidate->deformableContactNodeRanges
               offset:0u atIndex:9u];
        [primalContactEncoder setBuffer:candidate->mpmNodeToActive
                                 offset:0u atIndex:10u];
        [primalContactEncoder setBuffer:candidate->mpmActiveNodeCounts
                                 offset:0u atIndex:11u];
        [primalContactEncoder setBuffer:candidate->rigidProxies
                                 offset:0u atIndex:12u];
        [primalContactEncoder setBuffer:candidate->rigidStates
                                 offset:0u atIndex:13u];
        [primalContactEncoder
            setBuffer:candidate->deformableContactActiveCounts
               offset:0u atIndex:14u];
        candidate->residentBytes += primalContactEncoder.encodedLength;

        // Full-contact Armijo may include one finite free body. Its trial
        // contact queries need the private trial rigid-state and sample
        // arenas, while sharing immutable pair/incidence topology with the
        // production contact table.
        if (candidate->femArmijoRigidStates != nil &&
            candidate->femArmijoBoxContactSamples != nil &&
            candidate->femArmijoContactActivePairs != nil &&
            candidate->femArmijoContactActiveSlotsByPair != nil &&
            candidate->femArmijoContactActiveCounts != nil) {
            candidate->femArmijoPrimalContactArguments =
                [candidate->device
                    newBufferWithLength:primalContactEncoder.encodedLength
                                 options:MTLResourceStorageModeShared];
            if (candidate->femArmijoPrimalContactArguments == nil) {
                diagnostics.message =
                    "failed to allocate private free-rigid Armijo contact arguments";
                return diagnostics;
            }
            [primalContactEncoder setArgumentBuffer:
                candidate->femArmijoPrimalContactArguments offset:0u];
            [primalContactEncoder setBuffer:candidate->contactPairs
                                     offset:0u atIndex:0u];
            [primalContactEncoder setBuffer:
                candidate->femArmijoBoxContactSamples
                                     offset:0u atIndex:1u];
            [primalContactEncoder setBuffer:candidate->contactNodeIncidence
                                     offset:0u atIndex:2u];
            [primalContactEncoder setBuffer:candidate->contactNodeRanges
                                     offset:0u atIndex:3u];
            [primalContactEncoder setBuffer:
                candidate->femArmijoContactActivePairs
                                     offset:0u atIndex:4u];
            [primalContactEncoder setBuffer:
                candidate->femArmijoContactActiveSlotsByPair
                                     offset:0u atIndex:5u];
            [primalContactEncoder setBuffer:
                candidate->femArmijoContactActiveCounts
                                     offset:0u atIndex:6u];
            [primalContactEncoder setBuffer:candidate->deformableContacts
                                     offset:0u atIndex:7u];
            [primalContactEncoder setBuffer:
                candidate->deformableContactNodeIncidence
                                     offset:0u atIndex:8u];
            [primalContactEncoder setBuffer:
                candidate->deformableContactNodeRanges
                                     offset:0u atIndex:9u];
            [primalContactEncoder setBuffer:candidate->mpmNodeToActive
                                     offset:0u atIndex:10u];
            [primalContactEncoder setBuffer:candidate->mpmActiveNodeCounts
                                     offset:0u atIndex:11u];
            [primalContactEncoder setBuffer:candidate->rigidProxies
                                     offset:0u atIndex:12u];
            [primalContactEncoder setBuffer:candidate->femArmijoRigidStates
                                     offset:0u atIndex:13u];
            [primalContactEncoder setBuffer:
                candidate->deformableContactActiveCounts
                                     offset:0u atIndex:14u];
            candidate->residentBytes += primalContactEncoder.encodedLength;
        }

        for (const NMRigidProxyGPU& proxy : world.contact.rigidProxies) {
            if ((proxy.flags & NM_RIGID_SUTURE_STRAND) != 0u) {
                candidate->requiresRodNodes = true;
                candidate->requiredRodNodeCount = std::max({
                    candidate->requiredRodNodeCount,
                    proxy.bodyIndex + 1u,
                    proxy.sceneBodyIndex + 1u,
                });
                continue;
            }
            if (proxy.bodyIndex != NM_INVALID_INDEX) {
                candidate->requiresCurrentBodies = true;
                candidate->requiredCurrentBodyCount = std::max(
                    candidate->requiredCurrentBodyCount,
                    proxy.bodyIndex + 1u
                );
            }
            if ((proxy.flags &
                 (NM_RIGID_ARTICULATED | NM_RIGID_DYNAMIC)) != 0u) {
                candidate->requiresBodyWrenches = true;
                candidate->requiredBodyWrenchCount = std::max(
                    candidate->requiredBodyWrenchCount,
                    proxy.bodyIndex + 1u
                );
            }
            if ((proxy.flags & NM_RIGID_ARTICULATED) != 0u) {
                candidate->requiresCoupledCandidate = true;
            }
            if ((proxy.flags & NM_RIGID_DYNAMIC) != 0u) {
                candidate->requiresSceneBodies = true;
                candidate->requiredSceneBodyCount = std::max(
                    candidate->requiredSceneBodyCount,
                    proxy.sceneBodyIndex + 1u
                );
                if (proxy.sceneBodyIndex == NM_INVALID_INDEX) {
                    diagnostics.message =
                        "dynamic rigid proxies require a scene-body index";
                    return diagnostics;
                }
            }
        }

        if (!world.fem.humanAttachments.empty()) {
            candidate->requiresCoupledCandidate = true;
            for (const NMFEMHumanAttachmentGPU& attachment :
                 world.fem.humanAttachments) {
                candidate->requiredCandidateBodyCount = std::max(
                    candidate->requiredCandidateBodyCount,
                    attachment.identity.y + 1u
                );
            }
        }
        if (candidate->humanSupportDispatch.contactCount != 0u) {
            candidate->requiresCoupledCandidate = true;
            for (const NMHumanSupportContactGPU& support :
                 configuration.humanSupportContacts) {
                if (support.identity.x == NM_INVALID_INDEX ||
                    support.identity.z >=
                        candidate->humanSupportDispatch.contactCount ||
                    support.identity.w > 2u) {
                    diagnostics.message =
                        "Human support row has an invalid body or point identity";
                    return diagnostics;
                }
                candidate->requiredCandidateBodyCount = std::max(
                    candidate->requiredCandidateBodyCount,
                    support.identity.x + 1u);
                candidate->requiredCurrentBodyCount = std::max(
                    candidate->requiredCurrentBodyCount,
                    support.identity.x + 1u);
            }
        }

        candidate->reactionBodyCount =
            candidate->requiredBodyWrenchCount;
        std::vector<std::vector<std::uint32_t>> bodyProxyOwners(
            candidate->reactionBodyCount
        );
        for (std::uint32_t proxyIndex = 0u;
             proxyIndex < world.contact.rigidProxies.size();
             ++proxyIndex) {
            const NMRigidProxyGPU& proxy =
                world.contact.rigidProxies[proxyIndex];
            if (proxy.bodyIndex != NM_INVALID_INDEX &&
                (proxy.flags &
                 (NM_RIGID_ARTICULATED | NM_RIGID_DYNAMIC)) != 0u) {
                bodyProxyOwners[proxy.bodyIndex].push_back(proxyIndex);
            }
        }

        std::set<std::uint32_t> adaptiveProxyBindings;
        std::set<std::uint32_t> adaptiveBodyBindings;
        std::set<std::uint32_t> adaptiveSceneBindings;
        for (const NMContinuumObjectGPU& object : world.objects) {
            if ((object.flags & NM_OBJECT_ADAPTIVE) == 0u) {
                continue;
            }
            if (object.rigidBinding >= world.contact.rigidProxies.size()) {
                diagnostics.message =
                    "adaptive Matter object has no valid rigid proxy";
                return diagnostics;
            }
            const NMRigidProxyGPU& proxy =
                world.contact.rigidProxies[object.rigidBinding];
            if ((proxy.flags & NM_RIGID_DYNAMIC) == 0u ||
                (proxy.flags & NM_RIGID_ARTICULATED) != 0u ||
                proxy.bodyIndex == NM_INVALID_INDEX ||
                proxy.sceneBodyIndex == NM_INVALID_INDEX ||
                !adaptiveProxyBindings.insert(object.rigidBinding).second ||
                !adaptiveBodyBindings.insert(proxy.bodyIndex).second ||
                !adaptiveSceneBindings.insert(proxy.sceneBodyIndex).second) {
                diagnostics.message =
                    "adaptive Matter objects require unique free-dynamic proxy and scene-body bindings";
                return diagnostics;
            }
        }

        std::vector<std::uint32_t> bodyProxyIncidence;
        std::vector<NMIncidenceRangeGPU> bodyProxyRanges(
            candidate->reactionBodyCount
        );
        for (std::uint32_t bodyIndex = 0u;
             bodyIndex < candidate->reactionBodyCount;
             ++bodyIndex) {
            NMIncidenceRangeGPU range{};
            range.first = static_cast<nm_u32>(bodyProxyIncidence.size());
            range.count = static_cast<nm_u32>(bodyProxyOwners[bodyIndex].size());
            range.objectIndex = bodyIndex;
            bodyProxyIncidence.insert(
                bodyProxyIncidence.end(),
                bodyProxyOwners[bodyIndex].begin(),
                bodyProxyOwners[bodyIndex].end()
            );
            bodyProxyRanges[bodyIndex] = range;
        }
        UploadPlan bridgeUploads(candidate->device, candidate->queue);
        candidate->bodyProxyIncidence = bridgeUploads.one(
            std::span<const std::uint32_t>(bodyProxyIncidence),
            valid,
            candidate->residentBytes
        );
        candidate->bodyProxyRanges = bridgeUploads.one(
            std::span<const NMIncidenceRangeGPU>(bodyProxyRanges),
            valid,
            candidate->residentBytes
        );
        std::string bridgeUploadError;
        if (!valid || !bridgeUploads.finish(bridgeUploadError)) {
            diagnostics.message = valid
                ? "failed to upload body-owned Matter coupling incidence: " +
                    bridgeUploadError
                : "failed to allocate body-owned Matter coupling incidence";
            return diagnostics;
        }

        diagnostics.encoded = true;
        diagnostics.residentBytes = candidate->residentBytes;
        diagnostics.device = nsString(candidate->device.name);
        if (candidate->enableVascularDense45) {
            diagnostics.message =
                "Numi Matter runtime initialized with eligible dense45 vascular solve";
        } else if (configuration.enableVascularDense45) {
            diagnostics.message =
                "Numi Matter runtime initialized; dense45 ineligible (" +
                std::string(dense45Reason == nullptr ? "unknown" : dense45Reason) +
                "), using FGMRES";
        } else {
            diagnostics.message = "Numi Matter runtime initialized";
        }
        state_ = std::move(candidate);
        return diagnostics;
    }
}

RuntimeDiagnostics Runtime::encode(const EncodeRequest& request) {
    return encodeImpl(request, false);
}

RuntimeDiagnostics Runtime::encodeAcceptedControlCursorPublication(
    void* const commandBufferRaw,
    const std::uint32_t controlStep,
    const std::uint32_t physicsSubstep,
    const AcceptedControlCursorGate& gate
) {
    RuntimeDiagnostics diagnostics;
    if (!state_ || commandBufferRaw == nullptr) {
        diagnostics.message =
            "accepted-control-cursor publication requires an initialized Runtime and borrowed command buffer";
        return diagnostics;
    }
    State& state = *state_;
    id<MTLCommandBuffer> commandBuffer =
        (__bridge id<MTLCommandBuffer>)commandBufferRaw;
    id<MTLBuffer> externalStatuses = gate.statusCodes == nullptr
        ? state.statuses
        : (__bridge id<MTLBuffer>)gate.statusCodes;
    if (commandBuffer.commandQueue == nil ||
        commandBuffer.commandQueue.device.registryID !=
            state.device.registryID ||
        externalStatuses == nil ||
        externalStatuses.device.registryID != state.device.registryID ||
        (gate.statusCodes == nullptr && gate.recordCount != 0u) ||
        (gate.statusCodes != nullptr &&
         (gate.recordCount == 0u || gate.recordStrideBytes < sizeof(std::uint32_t) ||
          (gate.recordStrideBytes % sizeof(std::uint32_t)) != 0u ||
          static_cast<std::uint64_t>(gate.recordCount - 1u) *
                  gate.recordStrideBytes + sizeof(std::uint32_t) >
              externalStatuses.length))) {
        diagnostics.message =
            "accepted-control-cursor external gate has invalid device provenance or bounds";
        return diagnostics;
    }
    const auto ownership = state.commandOwnership;
    std::unique_lock lock(ownership->mutex);
    if (ownership->activeCommandBuffer != commandBufferRaw ||
        ownership->preDynamicsOpen ||
        !ownership->acceptedControlCursorDeferred ||
        ownership->controlStep != controlStep ||
        ownership->physicsSubstep != physicsSubstep) {
        diagnostics.message =
            "accepted-control-cursor publication does not match the deferred active transaction";
        return diagnostics;
    }
    const auto pipeline = state.pipelines.find(
        "nm_publish_accepted_control_cursor");
    if (pipeline == state.pipelines.end() || pipeline->second == nil) {
        diagnostics.message =
            "accepted-control-cursor Metal pipeline is unavailable";
        return diagnostics;
    }
    const std::uint32_t strideWords = gate.statusCodes == nullptr
        ? 0u
        : gate.recordStrideBytes / sizeof(std::uint32_t);
    const NMControlCursorPublicationParams publication{
        .controlStep = controlStep,
        .physicsSubstep = physicsSubstep,
        .environmentCount = state.dispatch.environmentCount,
        .externalStatusCount = gate.recordCount,
        .externalStatusStrideWords = strideWords,
        .acceptedStatusCode = gate.acceptedStatusCode,
        .flags = gate.statusCodes == nullptr ? 0u : 1u,
        .reserved = 0u,
    };
    id<MTLComputeCommandEncoder> encoder =
        [commandBuffer computeCommandEncoder];
    if (encoder == nil) {
        diagnostics.message =
            "failed to create accepted-control-cursor compute encoder";
        return diagnostics;
    }
    [encoder setLabel:@"Numi Matter accepted control cursor publication"];
    [encoder setComputePipelineState:pipeline->second];
    [encoder setBuffer:state.dispatchBuffer offset:0u atIndex:0u];
    [encoder setBytes:&publication length:sizeof(publication) atIndex:1u];
    [encoder setBuffer:state.statuses offset:0u atIndex:2u];
    [encoder setBuffer:externalStatuses offset:0u atIndex:3u];
    [encoder setBuffer:state.acceptedControlCursor offset:0u atIndex:4u];
    [encoder dispatchThreads:MTLSizeMake(1u, 1u, 1u)
        threadsPerThreadgroup:MTLSizeMake(1u, 1u, 1u)];
    [encoder endEncoding];
    ownership->acceptedControlCursorDeferred = false;
    diagnostics.encoded = true;
    diagnostics.residentBytes = state.residentBytes;
    diagnostics.device = nsString(state.device.name);
    diagnostics.message =
        "accepted Matter control cursor publication encoded behind all owner gates";
    return diagnostics;
}

RuntimeDiagnostics Runtime::prepareAcceptedState(
    const EncodeRequest& postCommitRequest
) {
    if (postCommitRequest.phase != EncodePhase::postCommit) {
        RuntimeDiagnostics diagnostics;
        diagnostics.message =
            "prepared-state reconciliation requires a postCommit request";
        return diagnostics;
    }
    if (!postCommitRequest.enablePreparedState ||
        postCommitRequest.physicsSubsteps != 1u ||
        postCommitRequest.physicsSubstep != 0u) {
        RuntimeDiagnostics diagnostics;
        diagnostics.message =
            "prepared-state v1 requires an explicitly opted-in single-substep transaction";
        return diagnostics;
    }
    return encodeImpl(postCommitRequest, true);
}

RuntimeDiagnostics Runtime::encodeImpl(
    const EncodeRequest& request,
    const bool retainPreparedState
) {
    @autoreleasepool {
        RuntimeDiagnostics diagnostics;
        if (!state_) {
            diagnostics.message = "Numi Matter runtime is not initialized";
            return diagnostics;
        }
        if (request.commandBuffer == nullptr) {
            diagnostics.message = "encode requires a borrowed Metal command buffer";
            return diagnostics;
        }
        State& state = *state_;
        // Parse once: endpoint certification and trial scope must select
        // exactly the same transactions, including the every-step mode.
        const char* boxArmijoSelector = std::getenv(
            "NM_FEM_CAPSULE_BOX_RESIDUAL_ARMIJO_ROOT");
        const bool boxArmijoEveryStep = boxArmijoSelector != nullptr &&
            std::strcmp(boxArmijoSelector, "all") == 0;
        char* boxArmijoSelectorEnd = nullptr;
        const unsigned long boxArmijoSelectedRoot = boxArmijoEveryStep
            ? request.controlStep : boxArmijoSelector != nullptr
                ? std::strtoul(boxArmijoSelector, &boxArmijoSelectorEnd, 10) : 0ul;
        const bool boxArmijoSelectorValid = boxArmijoSelector != nullptr &&
            (boxArmijoEveryStep || (boxArmijoSelectorEnd != boxArmijoSelector &&
                *boxArmijoSelectorEnd == '\0')) &&
            boxArmijoSelectedRoot <= std::numeric_limits<std::uint32_t>::max();
        // Full-contact Armijo owns the same endpoint projection/rollback
        // transaction as the narrower capsule/BOX residual mode. Parse its
        // selector here too: these gates run before the later line-search
        // selector block, so looking only at the capsule/BOX variable leaves
        // BOX rigid-state rollback disabled for full-contact runs.
        const char* fullContactArmijoSelector = std::getenv(
            "NM_FEM_FULL_CONTACT_RESIDUAL_ARMIJO_ROOT");
        const bool fullContactArmijoEveryStep =
            fullContactArmijoSelector != nullptr &&
            std::strcmp(fullContactArmijoSelector, "all") == 0;
        char* fullContactArmijoSelectorEnd = nullptr;
        const unsigned long fullContactArmijoSelectedRoot =
            fullContactArmijoEveryStep ? request.controlStep
                : fullContactArmijoSelector != nullptr
                    ? std::strtoul(fullContactArmijoSelector,
                        &fullContactArmijoSelectorEnd, 10)
                    : 0ul;
        const bool fullContactArmijoSelectorValid =
            fullContactArmijoSelector != nullptr &&
            (fullContactArmijoEveryStep ||
             (fullContactArmijoSelectorEnd != fullContactArmijoSelector &&
              *fullContactArmijoSelectorEnd == '\0')) &&
            fullContactArmijoSelectedRoot <=
                std::numeric_limits<std::uint32_t>::max();
        const bool stationaryBoxEndpointGateRequested =
            (boxArmijoSelectorValid &&
             boxArmijoSelectedRoot == request.controlStep) ||
            (fullContactArmijoSelectorValid &&
             fullContactArmijoSelectedRoot == request.controlStep);
        const bool hasAcceptedStepExtension =
            request.encodeAcceptedStepExtension != nullptr;
        if (hasAcceptedStepExtension !=
            (request.acceptedStepExtensionContext != nullptr)) {
            diagnostics.message =
                "accepted-step extension requires both callback and context";
            return diagnostics;
        }
        if (hasAcceptedStepExtension &&
            state.vascularValue.layout.ranges.z == 0u) {
            diagnostics.message =
                "accepted-step extension requires an initialized vascular network";
            return diagnostics;
        }
        if (hasAcceptedStepExtension && retainPreparedState) {
            diagnostics.message =
                "accepted-step extension does not support prepared-state publication transactions";
            return diagnostics;
        }
        if (request.phase != EncodePhase::preDynamics &&
            request.phase != EncodePhase::postCommit) {
            diagnostics.message = "unknown Matter encode phase";
            return diagnostics;
        }
        if (request.physicsSubsteps == 0u ||
            request.physicsSubstep >= request.physicsSubsteps) {
            diagnostics.message = "matter physics-substep coordinates are invalid";
            return diagnostics;
        }
        if (request.enablePreparedState &&
            (request.physicsSubsteps != 1u ||
             request.physicsSubstep != 0u)) {
            diagnostics.message =
                "prepared-state v1 supports exactly one physics substep";
            return diagnostics;
        }
        if (request.enablePreparedState &&
            (request.runIdentification ||
             request.resetMaskStepStride != 0u)) {
            diagnostics.message =
                "prepared-state v1 rejects identification and episode reset until their control-plane authority is covered by ACK-gated apply/restore";
            return diagnostics;
        }
        if (request.enablePreparedState &&
            (state.hasAdaptive || request.runAdaptiveTransfer)) {
            diagnostics.message =
                "prepared-state v1 rejects adaptive worlds/transfers until borrowed current-body and scene-body rollback authority is covered by ACK-gated apply/restore";
            return diagnostics;
        }
        if (request.enablePreparedState &&
            request.deferAcceptedControlCursorPublication) {
            diagnostics.message =
                "prepared-state publication owns its cursor and cannot defer the standalone accepted-cursor kernel";
            return diagnostics;
        }
        if (state.requiresCurrentBodies &&
            request.rigid.currentBodies == nullptr) {
            diagnostics.message =
                "body-backed matter proxies require the current body arena";
            return diagnostics;
        }
        void* supportInitialBodyArena = request.humanSupportInitialBodies != nullptr
            ? request.humanSupportInitialBodies : request.rigid.currentBodies;
        void* supportInitialBodyLowArena = request.humanSupportInitialBodyPositionLow;
        const std::uint32_t coupledPositionPrecision =
            state.coupledCandidateCompensatedTranslation ? 1u : 0u;
        if (!state.coupledCandidateCompensatedTranslation &&
            (request.humanSupportInitialBodyPositionLow != nullptr ||
             request.humanSupportInitialBodyPositionLowGPUAddress != 0u ||
             request.humanSupportInitialBodyPositionLowElementCount != 0u)) {
            diagnostics.message = "legacy high-only candidate owner cannot silently consume compensated support state";
            return diagnostics;
        }
        if (state.humanSupportDispatch.contactCount != 0u &&
            supportInitialBodyArena == nullptr) {
            diagnostics.message = "Human support requires an initial body pose arena";
            return diagnostics;
        }
        if (state.humanSupportDispatch.contactCount != 0u) {
            id<MTLBuffer> bodies = (__bridge id<MTLBuffer>)supportInitialBodyArena;
            const std::uint64_t elements =
                static_cast<std::uint64_t>(state.dispatch.environmentCount) *
                request.rigid.currentBodyStride;
            if (bodies.device == nil ||
                bodies.device.registryID != state.device.registryID ||
                bodies.gpuAddress == 0u ||
                elements > static_cast<std::uint64_t>(bodies.length) /
                    sizeof(MRBodyStateGPU)) {
                diagnostics.message =
                    "Human support initial body arena has wrong device provenance or byte capacity";
                return diagnostics;
            }
        }
        if (state.coupledCandidateCompensatedTranslation &&
            state.humanSupportDispatch.contactCount != 0u) {
            id<MTLBuffer> lows = (__bridge id<MTLBuffer>)supportInitialBodyLowArena;
            id<MTLBuffer> highs = (__bridge id<MTLBuffer>)supportInitialBodyArena;
            const std::uint64_t elements = std::uint64_t(state.dispatch.environmentCount) *
                request.rigid.currentBodyStride;
            if (lows == nil || lows.device.registryID != state.device.registryID ||
                lows.gpuAddress == 0u || lows.gpuAddress != request.humanSupportInitialBodyPositionLowGPUAddress ||
                request.humanSupportInitialBodyPositionLowElementCount != elements ||
                elements > std::uint64_t(lows.length) / sizeof(nm_float4) ||
                lows == highs ||
                (lows.gpuAddress < highs.gpuAddress + highs.length &&
                 highs.gpuAddress < lows.gpuAddress + lows.length)) {
                diagnostics.message = "compensated Human support requires a distinct exact initial low arena";
                return diagnostics;
            }
        }
        if (state.requiresCurrentBodies) {
            id<MTLBuffer> bodies = (__bridge id<MTLBuffer>)request.rigid.currentBodies;
            const std::uint64_t elements =
                static_cast<std::uint64_t>(state.dispatch.environmentCount) *
                request.rigid.currentBodyStride;
            if (bodies.device == nil ||
                bodies.device.registryID != state.device.registryID ||
                bodies.gpuAddress == 0u ||
                elements > static_cast<std::uint64_t>(bodies.length) /
                    sizeof(MRBodyStateGPU)) {
                diagnostics.message =
                    "current body arena has wrong device provenance or byte capacity";
                return diagnostics;
            }
        }
        if (request.phase == EncodePhase::preDynamics &&
            state.requiresBodyWrenches &&
            request.rigid.bodyWrenches == nullptr) {
            diagnostics.message =
                "two-way matter coupling requires the global body-wrench arena";
            return diagnostics;
        }
        if (request.phase == EncodePhase::preDynamics &&
            state.requiresCoupledCandidate &&
            (request.encodeCoupledCandidate == nullptr ||
             request.coupledCandidateContext == nullptr ||
             request.rigid.q == nullptr || request.rigid.v == nullptr ||
             request.rigid.qStride == 0u || request.rigid.vStride == 0u ||
             request.rigid.qStride > state.dispatch.rigidQCapacity ||
             request.rigid.vStride >
                 state.dispatch.rigidGeneralizedCapacity ||
             (state.requiredCandidateBodyCount != 0u &&
              (request.rigid.currentBodyCount <
                   state.requiredCandidateBodyCount ||
               request.rigid.currentBodyStride <
                   state.requiredCandidateBodyCount)))) {
            diagnostics.message =
                "articulated Matter IPC requires a compatible primal coupled-candidate service plus exact q/v and candidate-body capacity";
            return diagnostics;
        }
        if (state.requiresSceneBodies &&
            request.rigid.sceneBodies == nullptr) {
            diagnostics.message =
                "dynamic matter coupling requires the scene-body arena";
            return diagnostics;
        }
        if (state.requiresRodNodes &&
            (request.rigid.rodNodes == nullptr ||
             request.rigid.rodInverseMasses == nullptr)) {
            diagnostics.message =
                "suture-strand matter proxies require live DER node and inverse-mass arenas";
            return diagnostics;
        }
        if (request.phase == EncodePhase::postCommit &&
            request.environmentStatuses == nullptr) {
            diagnostics.message =
                "post-commit matter reconciliation requires MetalWorld status";
            return diagnostics;
        }
        if (request.environmentStatuses == nullptr) {
            diagnostics.message =
                "coupled Matter execution requires MetalWorld environment status";
            return diagnostics;
        }
        const std::uint64_t requiredFEMExternalForceCount =
            static_cast<std::uint64_t>(state.dispatch.environmentCount) *
            state.dispatch.femNodeCount;
        if ((request.femExternalForces == nullptr) !=
                (request.femExternalForceCount == 0u) ||
            (request.femExternalForces != nullptr &&
             request.femExternalForceCount != requiredFEMExternalForceCount)) {
            diagnostics.message =
                "borrowed FEM external-force field must exactly cover every environment and cooked node";
            return diagnostics;
        }
        if ((request.femKinematicTargets == nullptr) !=
                (request.femKinematicTargetCount == 0u) ||
            (request.femKinematicTargets != nullptr &&
             request.femKinematicTargetCount != requiredFEMExternalForceCount)) {
            diagnostics.message =
                "borrowed FEM kinematic-target field must exactly cover every environment and cooked node";
            return diagnostics;
        }
        const bool hasCohesiveActivationCommands =
            request.cohesiveActivationCommandCount != 0u;
        if ((request.cohesiveActivationCommands == nullptr) !=
                !hasCohesiveActivationCommands ||
            (!hasCohesiveActivationCommands &&
             request.cohesiveActivationCommandStride != 0u) ||
            (hasCohesiveActivationCommands &&
             request.cohesiveActivationCommandStride !=
                sizeof(NMCohesiveActivationCommandGPU))) {
            diagnostics.message =
                "cohesive activation stream requires a nonnull exact-stride buffer, or all three fields zero";
            return diagnostics;
        }
        if (request.phase == EncodePhase::postCommit &&
            hasCohesiveActivationCommands) {
            diagnostics.message =
                "cohesive activation commands are consumed only by preDynamics";
            return diagnostics;
        }
        if (hasCohesiveActivationCommands) {
            if (request.phase != EncodePhase::preDynamics ||
                request.physicsSubstep != 0u) {
                diagnostics.message =
                    "cohesive activation commands must be submitted at the first preDynamics physics substep";
                return diagnostics;
            }
            const std::uint64_t explicitFaceCount = static_cast<std::uint64_t>(
                std::ranges::count_if(state.femImmutableCohesiveLayout,
                    [](const NMCohesiveFaceGPU& face) {
                        return (face.adjacency.w &
                            (NM_TOPOLOGY_PAIRED_COHESIVE |
                             NM_TOPOLOGY_COHESIVE_MIXED_MODE |
                             NM_TOPOLOGY_COHESIVE_DORMANT |
                             NM_TOPOLOGY_COHESIVE_MORTAR)) ==
                            (NM_TOPOLOGY_PAIRED_COHESIVE |
                             NM_TOPOLOGY_COHESIVE_MIXED_MODE |
                             NM_TOPOLOGY_COHESIVE_DORMANT |
                             NM_TOPOLOGY_COHESIVE_MORTAR) &&
                            face.lawIdentity.w ==
                                NM_COHESIVE_ACTIVATION_EXPLICIT_COMMAND;
                    }));
            const std::uint64_t maximumCommands = explicitFaceCount *
                state.dispatch.environmentCount;
            if (explicitFaceCount == 0u ||
                request.cohesiveActivationCommandCount > maximumCommands) {
                diagnostics.message =
                    "cohesive activation command count exceeds the compiled explicit-mortar face capacity";
                return diagnostics;
            }
        }
        if (request.rigid.currentBodyCount >
                request.rigid.currentBodyStride ||
            request.rigid.bodyWrenchCount >
                request.rigid.bodyWrenchStride ||
            request.rigid.sceneBodyCount >
                request.rigid.sceneStride ||
            request.rigid.rodNodeCount > request.rigid.rodNodeStride) {
            diagnostics.message =
                "borrowed rigid-world buffer strides are invalid";
            return diagnostics;
        }
        if (request.rigid.currentBodyCount <
                state.requiredCurrentBodyCount ||
            request.rigid.bodyWrenchCount <
                state.requiredBodyWrenchCount ||
            request.rigid.sceneBodyCount <
                state.requiredSceneBodyCount ||
            request.rigid.rodNodeCount < state.requiredRodNodeCount) {
            diagnostics.message =
                "borrowed rigid-world buffers do not cover every compiled Matter proxy";
            return diagnostics;
        }
        const bool hasExternalWorldWrenches =
            request.rigid.externalWrenches != nullptr;
        if (!hasExternalWorldWrenches &&
            (request.rigid.externalWrenchCount != 0u ||
             request.rigid.externalWrenchStride != 0u)) {
            diagnostics.message =
                "external world-wrench input requires a nonnull buffer or all fields zero";
            return diagnostics;
        }
        if (hasExternalWorldWrenches) {
            const bool hasFreeDynamicBodyProxy = std::ranges::any_of(
                state.rigidProxyLayout,
                [&](const NMRigidProxyGPU& proxy) {
                    return (proxy.flags & NM_RIGID_DYNAMIC) != 0u &&
                        (proxy.flags & NM_RIGID_ARTICULATED) == 0u &&
                        proxy.generalizedFreeBodyIndex != NM_INVALID_INDEX &&
                        6u * std::uint64_t(
                            proxy.generalizedFreeBodyIndex + 1u) <=
                            state.dispatch.rigidGeneralizedCapacity;
                });
            if (!state.requiresCurrentBodies ||
                !hasFreeDynamicBodyProxy ||
                state.dispatch.rigidGeneralizedCapacity == 0u ||
                request.rigid.currentBodyCount == 0u ||
                request.rigid.externalWrenchCount !=
                    request.rigid.currentBodyCount ||
                request.rigid.externalWrenchStride <
                    request.rigid.externalWrenchCount) {
                diagnostics.message =
                    "external world-wrench rows must cover the exact current-body index range for a free-rigid world";
                return diagnostics;
            }
            const std::uint64_t rows =
                static_cast<std::uint64_t>(state.dispatch.environmentCount) *
                request.rigid.externalWrenchStride;
            if (rows > std::numeric_limits<std::uint64_t>::max() /
                    sizeof(MRABABodyWrenchGPU)) {
                diagnostics.message =
                    "external world-wrench byte capacity overflows";
                return diagnostics;
            }
            id<MTLBuffer> external = (__bridge id<MTLBuffer>)
                request.rigid.externalWrenches;
            const std::uint64_t bytes = rows *
                sizeof(MRABABodyWrenchGPU);
            if (external.device == nil ||
                external.device.registryID != state.device.registryID ||
                external.gpuAddress == 0u ||
                external.gpuAddress >
                    std::numeric_limits<std::uint64_t>::max() - bytes ||
                bytes > static_cast<std::uint64_t>(external.length)) {
                diagnostics.message =
                    "external world-wrench arena has wrong device provenance or byte capacity";
                return diagnostics;
            }
            if (request.rigid.bodyWrenches != nullptr) {
                id<MTLBuffer> output = (__bridge id<MTLBuffer>)
                    request.rigid.bodyWrenches;
                bool addressRangesOverlap = false;
                if (output.device != nil && output.gpuAddress != 0u &&
                    output.length != 0u) {
                    const std::uint64_t outputBytes =
                        static_cast<std::uint64_t>(output.length);
                    if (output.gpuAddress >
                        std::numeric_limits<std::uint64_t>::max() -
                            outputBytes) {
                        diagnostics.message =
                            "body-wrench output GPU address range overflows";
                        return diagnostics;
                    }
                    addressRangesOverlap = external.gpuAddress <=
                            output.gpuAddress
                        ? output.gpuAddress - external.gpuAddress < bytes
                        : external.gpuAddress - output.gpuAddress <
                            outputBytes;
                }
                if (external == output || addressRangesOverlap) {
                    diagnostics.message =
                        "external world-wrench input must not alias Matter's body-wrench output arena";
                    return diagnostics;
                }
            }
        }
        if (request.runIdentification &&
            (request.phase != EncodePhase::preDynamics ||
             request.physicsSubstep != 0u)) {
            diagnostics.message =
                "inverse material identification may run only in the first pre-dynamics substep";
            return diagnostics;
        }
        if (request.runIdentification && state.requiresCoupledCandidate) {
            diagnostics.message =
                "accepted-state attached Matter transactions reject in-place identification until device rollback authority is available";
            return diagnostics;
        }
        if (request.runAdaptiveTransfer &&
            (request.phase != EncodePhase::postCommit ||
             request.physicsSubstep + 1u != request.physicsSubsteps)) {
            diagnostics.message =
                "adaptive representation transfer may run only after the final rigid substep commits";
            return diagnostics;
        }
        if (request.resetMaskStepStride != 0u &&
            (request.resetMasks == nullptr ||
             request.resetMaskStepStride < state.dispatch.environmentCount)) {
            diagnostics.message =
                "matter reset-mask stream is missing or undersized";
            return diagnostics;
        }
        if (request.learnedWeightUpdate != nullptr &&
            request.phase == EncodePhase::preDynamics &&
            (request.physicsSubstep != 0u ||
             request.learnedWeightCount != state.dispatch.learnedWeightCount ||
             request.learnedWeightRevision == 0u ||
             (request.expectedLearnedFingerprint != 0u &&
              request.expectedLearnedFingerprint != state.learnedFingerprint))) {
            diagnostics.message =
                "learned weights require a complete, newer first-substep candidate";
            return diagnostics;
        }
        if (request.learnedWeightUpdate == nullptr &&
            request.learnedWeightCount != 0u) {
            diagnostics.message = "learned weight count has no borrowed buffer";
            return diagnostics;
        }
        if (staticFEMSurfaceMapEnabled(state.dispatch) &&
            (request.mutationCommandCount != 0u ||
             state.dispatch.mutationCommandCount != 0u ||
             state.hasMutableFEMTopology)) {
            diagnostics.message =
                "static FEM surface-map runtime rejects topology mutation commands";
            return diagnostics;
        }
        if (state.vascularValue.layout.ranges.z != 0u &&
            (request.mutationCommandCount != 0u ||
             state.dispatch.mutationCommandCount != 0u)) {
            diagnostics.message =
                "vascular topology does not support mutation or growth remapping";
            return diagnostics;
        }
        if (request.mutationCommandCount != 0u &&
            request.phase == EncodePhase::preDynamics &&
            (request.mutationCommands == nullptr ||
             request.physicsSubstep != 0u ||
             request.mutationCommandStride < sizeof(NMMutationCommandGPU))) {
            diagnostics.message =
                "mutation commands require a fixed-stride first-substep device stream";
            return diagnostics;
        }
        if (request.mutationCommandCount != 0u &&
            request.expectedMutationFingerprint != 0u &&
            request.expectedMutationFingerprint != state.mutationFingerprint) {
            diagnostics.message = "borrowed mutation fingerprint is stale";
            return diagnostics;
        }
        const float cookedTimestep =
            state.dispatch.gravityAndTimestep.w;
        const float activeTimestep = cookedTimestep *
            static_cast<float>(
                state.coupledTimestepMultiplier.load(
                    std::memory_order_acquire
                )
            ) /
            static_cast<float>(
                state.coupledTimestepDivisor.load(
                    std::memory_order_acquire
                )
            );
        const float frameTimestep = request.timestepSeconds > 0.0f
            ? request.timestepSeconds
            : activeTimestep;
        if (!std::isfinite(frameTimestep) || !(frameTimestep > 0.0f)) {
            diagnostics.message =
                "matter frame timestep must be finite and positive";
            return diagnostics;
        }
        if (frameTimestep != activeTimestep) {
            diagnostics.message =
                "Matter runtime timestep differs from the active coupled cadence";
            return diagnostics;
        }

        std::uint64_t vascularTimestepTicks = 0u;
        if (state.vascularValue.layout.ranges.z != 0u) {
            const float vascularDt = frameTimestep /
                static_cast<float>(1u << state.dispatch.maximumRateExponent);
            const int quantumExponent = std::bit_cast<std::int32_t>(
                state.vascularValue.layout.clock.x);
            const double ticks = std::ldexp(static_cast<double>(vascularDt), -quantumExponent);
            if (!std::isfinite(ticks) || !(ticks >= 1.0) || !(ticks < 0x1p64) ||
                std::trunc(ticks) != ticks) {
                diagnostics.message =
                    "vascular timestep is not exactly representable in the authored binary clock";
                return diagnostics;
            }
            vascularTimestepTicks = static_cast<std::uint64_t>(ticks);
        }

        id<MTLCommandBuffer> commandBuffer =
            (__bridge id<MTLCommandBuffer>)request.commandBuffer;
        id<MTLBuffer> femExternalForces = request.femExternalForces == nullptr
            ? state.dummy
            : (__bridge id<MTLBuffer>)request.femExternalForces;
        const std::uint32_t hasFEMExternalForces =
            request.femExternalForces == nullptr ? 0u : 1u;
        if (request.femExternalForces != nullptr &&
            femExternalForces.length <
                static_cast<NSUInteger>(request.femExternalForceCount) *
                    4u * sizeof(float)) {
            diagnostics.message = "borrowed FEM external-force Metal buffer is undersized";
            return diagnostics;
        }
        const bool hasVascularCavities = state.vascularValue.layout.cavities.x != 0u;
        const bool hasVascularBloodMass = std::any_of(
            state.vascularValue.tissues.begin(), state.vascularValue.tissues.end(),
            [](const auto& tissue) { return tissue.identity.w != 0u; });
        const bool hasVascularPressureReaction = std::any_of(
            state.vascularValue.tissues.begin(), state.vascularValue.tissues.end(),
            [](const auto& tissue) { return tissue.region.z != 0u && tissue.region.w != 0u; });
        const bool hasVascularMechanicalForces =
            hasVascularCavities || hasVascularBloodMass || hasVascularPressureReaction;
        id<MTLBuffer> femMechanicalForces = hasVascularMechanicalForces
            ? state.vascularCavityMergedExternal : femExternalForces;
        const std::uint32_t hasFEMMechanicalForces =
            hasVascularMechanicalForces || hasFEMExternalForces ? 1u : 0u;
        id<MTLBuffer> femKinematicTargets =
            request.femKinematicTargets == nullptr
                ? state.dummy
                : (__bridge id<MTLBuffer>)request.femKinematicTargets;
        const std::uint32_t hasFEMKinematicTargets =
            request.femKinematicTargets == nullptr ? 0u : 1u;
        if (request.femKinematicTargets != nullptr &&
            femKinematicTargets.length <
                static_cast<NSUInteger>(request.femKinematicTargetCount) *
                    4u * sizeof(float)) {
            diagnostics.message =
                "borrowed FEM kinematic-target Metal buffer is undersized";
            return diagnostics;
        }
        id<MTLBuffer> cohesiveActivationCommands =
            request.cohesiveActivationCommands == nullptr
                ? state.dummy
                : (__bridge id<MTLBuffer>)request.cohesiveActivationCommands;
        if (hasCohesiveActivationCommands) {
            const std::uint64_t commandBytes =
                static_cast<std::uint64_t>(
                    request.cohesiveActivationCommandCount) *
                sizeof(NMCohesiveActivationCommandGPU);
            const auto overlapsBuffer = [&](id<MTLBuffer> other) {
                if (other == nil || other.gpuAddress == 0u ||
                    cohesiveActivationCommands.gpuAddress == 0u ||
                    other.gpuAddress > UINT64_MAX - other.length ||
                    cohesiveActivationCommands.gpuAddress >
                        UINT64_MAX - commandBytes) return false;
                return cohesiveActivationCommands.gpuAddress <
                        other.gpuAddress + other.length &&
                    other.gpuAddress < cohesiveActivationCommands.gpuAddress +
                        commandBytes;
            };
            const std::array<id<MTLBuffer>, 8u> forbiddenAliases{
                state.cohesiveFacesAccepted,
                state.cohesiveFacesCandidate,
                state.cohesiveFacesCheckpoint,
                state.cohesiveFacesDefaults,
                state.femAccepted,
                state.femCandidate,
                state.statuses,
                state.solverCertificates,
            };
            const bool overlapsState = std::ranges::any_of(
                forbiddenAliases, overlapsBuffer);
            if (cohesiveActivationCommands == nil ||
                cohesiveActivationCommands.device == nil ||
                cohesiveActivationCommands.device.registryID !=
                    state.device.registryID ||
                cohesiveActivationCommands.gpuAddress == 0u ||
                (cohesiveActivationCommands.gpuAddress & 15u) != 0u ||
                commandBytes > cohesiveActivationCommands.length ||
                overlapsState) {
                diagnostics.message =
                    "cohesive activation stream has wrong device provenance, alignment, byte capacity, or aliases Matter state";
                return diagnostics;
            }
        }
        if (commandBuffer.commandQueue == nil ||
            commandBuffer.commandQueue.device.registryID !=
                state.device.registryID) {
            diagnostics.message =
                "borrowed command buffer does not belong to the initialized Matter device";
            return diagnostics;
        }
        if (state.requiresCoupledCandidate) {
            id<MTLBuffer> q = (__bridge id<MTLBuffer>)request.rigid.q;
            id<MTLBuffer> v = (__bridge id<MTLBuffer>)request.rigid.v;
            const std::uint64_t requiredQBytes =
                static_cast<std::uint64_t>(state.dispatch.environmentCount) *
                request.rigid.qStride * sizeof(float);
            const std::uint64_t requiredVBytes =
                static_cast<std::uint64_t>(state.dispatch.environmentCount) *
                request.rigid.vStride * sizeof(float);
            if (q == nil || v == nil ||
                q.device.registryID != state.device.registryID ||
                v.device.registryID != state.device.registryID ||
                q.length < requiredQBytes || v.length < requiredVBytes) {
                diagnostics.message =
                    "borrowed coupled q/v buffers have wrong device provenance or byte capacity";
                return diagnostics;
            }
        }

        const auto ownership = state.commandOwnership;
        std::unique_lock ownershipLock(ownership->mutex);
        if (ownership->physicalStateDigestOpen ||
            ownership->preparedStateOpen || ownership->applyEncoded ||
            ownership->restoreRequired) {
            diagnostics.message =
                ownership->physicalStateDigestOpen
                    ? "a quiescent physical-state digest is still in flight"
                    : "a prepared Matter transaction still requires apply, publication, or restore";
            return diagnostics;
        }
        if (ownership->activeCommandBuffer != nullptr &&
            ownership->activeCommandBuffer != request.commandBuffer) {
            diagnostics.message =
                "Numi Matter runtime already has another command buffer in flight";
            return diagnostics;
        }
        if (request.phase == EncodePhase::preDynamics &&
            ownership->preDynamicsOpen) {
            diagnostics.message =
                "a Matter pre-dynamics pass is still awaiting post-commit reconciliation";
            return diagnostics;
        }
        if (request.phase == EncodePhase::postCommit &&
            (!ownership->preDynamicsOpen ||
             ownership->controlStep != request.controlStep ||
             ownership->physicsSubstep != request.physicsSubstep ||
             ownership->acceptedControlCursorDeferred !=
                 request.deferAcceptedControlCursorPublication)) {
            diagnostics.message =
                "Matter post-commit pass does not match its pre-dynamics transaction or cursor-publication policy";
            return diagnostics;
        }
        if (retainPreparedState && !ownership->preparedStateRequested) {
            diagnostics.message =
                "prepared-state postCommit was not opted in at preDynamics";
            return diagnostics;
        }
        if (request.phase == EncodePhase::postCommit &&
            ownership->acceptedStateProofEncoded &&
            request.runAdaptiveTransfer) {
            diagnostics.message =
                "accepted-state proof cannot precede adaptive post-commit mutation";
            return diagnostics;
        }
        if (request.runIdentification &&
            ownership->identificationAdvanced) {
            diagnostics.message =
                "inverse material identification may advance only once per command buffer";
            return diagnostics;
        }
        if (state.humanEqualityDispatch.count != 0u) {
            id<MTLBuffer> sourceV = (__bridge id<MTLBuffer>)request.humanEqualitySourceVelocity;
            id<MTLBuffer> sourceFactor = (__bridge id<MTLBuffer>)request.humanEqualitySourceEffectiveTangentFactor;
            const std::uint64_t factorBytes = static_cast<std::uint64_t>(state.dispatch.environmentCount) *
                state.humanEqualityDispatch.dofCount * state.humanEqualityDispatch.dofCount * sizeof(float);
            const std::uint64_t bytes = static_cast<std::uint64_t>(state.dispatch.environmentCount) *
                state.humanEqualityDispatch.dofCount * sizeof(float);
            const std::uint64_t qBytes = static_cast<std::uint64_t>(state.dispatch.environmentCount) *
                state.humanEqualityDispatch.qCount * sizeof(float);
            const auto overlapsSource = [](void* lhsRaw, const std::uint64_t lhsBytes,
                                           void* rhsRaw, const std::uint64_t rhsBytes) {
                id<MTLBuffer> lhs = (__bridge id<MTLBuffer>)lhsRaw;
                id<MTLBuffer> rhs = (__bridge id<MTLBuffer>)rhsRaw;
                if (lhs == nil || rhs == nil || lhs.gpuAddress == 0u || rhs.gpuAddress == 0u ||
                    lhsBytes > UINT64_MAX-lhs.gpuAddress || rhsBytes > UINT64_MAX-rhs.gpuAddress)
                    return true;
                return lhs.gpuAddress < rhs.gpuAddress+rhsBytes &&
                       rhs.gpuAddress < lhs.gpuAddress+lhsBytes;
            };
            if (request.rigid.qStride != state.humanEqualityDispatch.qCount ||
                request.rigid.vStride != state.humanEqualityDispatch.dofCount ||
                sourceFactor == nil || sourceFactor.device.registryID != state.device.registryID ||
                sourceFactor.gpuAddress == 0u || sourceFactor.length < factorBytes ||
                sourceV == nil || sourceV.device.registryID != state.device.registryID ||
                sourceV.gpuAddress == 0u || sourceV.length < bytes ||
                overlapsSource(request.humanEqualitySourceVelocity, bytes,
                    request.humanEqualitySourceEffectiveTangentFactor, factorBytes) ||
                overlapsSource(request.humanEqualitySourceVelocity, bytes, request.rigid.v, bytes) ||
                overlapsSource(request.humanEqualitySourceVelocity, bytes, request.rigid.q, qBytes) ||
                overlapsSource(request.humanEqualitySourceEffectiveTangentFactor, factorBytes,
                    request.rigid.v, bytes) ||
                overlapsSource(request.humanEqualitySourceEffectiveTangentFactor, factorBytes,
                    request.rigid.q, qBytes) ||
                overlapsSource(request.rigid.q, qBytes, request.rigid.v, bytes) ||
                request.physicsSubsteps != 1u || request.runAdaptiveTransfer ||
                state.hasAdaptive) {
                diagnostics.message = "NHEQ2 requires one exact Human source root and distinct accepted velocity";
                return diagnostics;
            }
        }
        const bool firstEncodeForCommandBuffer =
            ownership->activeCommandBuffer == nullptr;

        if (request.phase == EncodePhase::preDynamics &&
            (state.requiresCoupledCandidate || state.coupledCandidateCompensatedTranslation)) {
            const std::uint32_t requiredQStride = request.rigid.qStride;
            const std::uint32_t requiredVStride = request.rigid.vStride;
            const std::uint32_t requiredBodyStride =
                request.rigid.currentBodyStride;
            if ((state.coupledQStride != 0u &&
                 state.coupledQStride != requiredQStride) ||
                (state.coupledVStride != 0u &&
                 state.coupledVStride != requiredVStride) ||
                (state.coupledBodyStride != 0u &&
                 state.coupledBodyStride != requiredBodyStride)) {
                diagnostics.message =
                    "MetalWorld coupled candidate strides changed after runtime allocation";
                return diagnostics;
            }
            if (state.coupledCandidateQ == nil) {
                bool allocationValid = true;
                const NSUInteger qBytes = checkedBytes(
                    static_cast<std::size_t>(state.dispatch.environmentCount) *
                        requiredQStride,
                    sizeof(float),
                    allocationValid);
                const NSUInteger bodyBytes = checkedBytes(
                    static_cast<std::size_t>(state.dispatch.environmentCount) *
                        requiredBodyStride,
                    sizeof(MRBodyStateGPU),
                    allocationValid);
                const NSUInteger lowBytes = checkedBytes(
                    state.coupledCandidateCompensatedTranslation
                        ? static_cast<std::size_t>(state.dispatch.environmentCount) * requiredBodyStride : 1u,
                    sizeof(nm_float4), allocationValid);
                const NSUInteger rootBytes = checkedBytes(
                    state.coupledCandidateCompensatedTranslation ? state.dispatch.environmentCount : 1u,
                    sizeof(MRCompensatedRootTranslationGPU), allocationValid);
                if (!allocationValid) {
                    diagnostics.message =
                        "coupled candidate allocation exceeds host address space";
                    return diagnostics;
                }
                state.coupledCandidateQ = [state.device
                    newBufferWithLength:qBytes
                                options:MTLResourceStorageModePrivate];
                state.coupledCandidateBodies = [state.device
                    newBufferWithLength:bodyBytes
                                options:MTLResourceStorageModePrivate];
                state.coupledCandidateRootTranslation = [state.device newBufferWithLength:rootBytes options:MTLResourceStorageModePrivate];
                state.coupledCandidateBodyPositionLow = [state.device newBufferWithLength:lowBytes options:MTLResourceStorageModePrivate];
                state.humanSupportInitialBodiesCheckpoint = [state.device newBufferWithLength:bodyBytes options:MTLResourceStorageModePrivate];
                state.humanSupportInitialBodyPositionLowCheckpoint = [state.device newBufferWithLength:lowBytes options:MTLResourceStorageModePrivate];
                if (state.coupledCandidateQ == nil ||
                    state.coupledCandidateBodies == nil ||
                    state.coupledCandidateRootTranslation == nil ||
                    state.coupledCandidateBodyPositionLow == nil ||
                    state.humanSupportInitialBodiesCheckpoint == nil ||
                    state.humanSupportInitialBodyPositionLowCheckpoint == nil) {
                    state.coupledCandidateQ = nil;
                    state.coupledCandidateBodies = nil;
                    state.coupledCandidateRootTranslation = nil;
                    state.coupledCandidateBodyPositionLow = nil;
                    state.humanSupportInitialBodiesCheckpoint = nil;
                    state.humanSupportInitialBodyPositionLowCheckpoint = nil;
                    diagnostics.message =
                        "failed to allocate private coupled candidate kinematics";
                    return diagnostics;
                }
                state.coupledQStride = requiredQStride;
                state.coupledVStride = requiredVStride;
                state.coupledBodyStride = requiredBodyStride;
                state.residentBytes += qBytes + 2u * bodyBytes + rootBytes + 2u * lowBytes;
            }
        }

        const bool firstPrePass =
            request.phase == EncodePhase::preDynamics &&
            request.physicsSubstep == 0u;
        if (state.coupledCandidateCompensatedTranslation &&
            state.humanSupportDispatch.contactCount != 0u) {
            if (firstPrePass) {
                id<MTLBlitCommandEncoder> initialGeometryBlit = [commandBuffer blitCommandEncoder];
                if (initialGeometryBlit == nil) {
                    diagnostics.message = "failed to checkpoint paired initial Human support geometry";
                    return diagnostics;
                }
                const NSUInteger elements = NSUInteger(state.dispatch.environmentCount) * state.coupledBodyStride;
                [initialGeometryBlit copyFromBuffer:(__bridge id<MTLBuffer>)supportInitialBodyArena
                    sourceOffset:0u toBuffer:state.humanSupportInitialBodiesCheckpoint
                    destinationOffset:0u size:elements * sizeof(MRBodyStateGPU)];
                [initialGeometryBlit copyFromBuffer:(__bridge id<MTLBuffer>)supportInitialBodyLowArena
                    sourceOffset:0u toBuffer:state.humanSupportInitialBodyPositionLowCheckpoint
                    destinationOffset:0u size:elements * sizeof(nm_float4)];
                [initialGeometryBlit endEncoding];
            }
            supportInitialBodyArena = (__bridge void*)state.humanSupportInitialBodiesCheckpoint;
            supportInitialBodyLowArena = (__bridge void*)state.humanSupportInitialBodyPositionLowCheckpoint;
        } else {
            supportInitialBodyLowArena = (__bridge void*)state.humanSupportHistoriesAccepted;
        }
        if (firstPrePass && request.enablePreparedState) {
            id<MTLBlitCommandEncoder> checkpointBlit =
                [commandBuffer blitCommandEncoder];
            if (checkpointBlit == nil) {
                diagnostics.message =
                    "failed to create prepared-state checkpoint blit";
                return diagnostics;
            }
            const std::array checkpointPairs{
                std::pair{id<MTLBuffer>(state.adaptive),
                          id<MTLBuffer>(state.adaptivePreparedCheckpoint)},
                std::pair{id<MTLBuffer>(state.schedulerPrevious),
                          id<MTLBuffer>(
                              state.schedulerPreviousPreparedCheckpoint)},
                std::pair{id<MTLBuffer>(state.frameReactions),
                          id<MTLBuffer>(
                              state.frameReactionsPreparedCheckpoint)},
                std::pair{id<MTLBuffer>(state.coupledGeneralizedCandidate),
                          id<MTLBuffer>(
                              state.coupledGeneralizedPreparedCheckpoint)},
                std::pair{id<MTLBuffer>(state.rigidStates),
                          id<MTLBuffer>(
                              state.rigidStatesPreparedCheckpoint)},
                std::pair{id<MTLBuffer>(state.identificationDistributions),
                          id<MTLBuffer>(
                              state.identificationPreparedCheckpoint)},
                std::pair{id<MTLBuffer>(state.environmentParameters),
                          id<MTLBuffer>(
                              state.environmentParametersPreparedCheckpoint)},
            };
            bool checkpointValid = true;
            for (const auto& [source, destination] : checkpointPairs) {
                if (source == nil || destination == nil ||
                    destination.length < source.length) {
                    checkpointValid = false;
                    break;
                }
                if (source.length != 0u) {
                    [checkpointBlit copyFromBuffer:source sourceOffset:0u
                                         toBuffer:destination
                                destinationOffset:0u size:source.length];
                }
            }
            if (checkpointValid) {
                [checkpointBlit fillBuffer:state.preparedStateBindings
                                     range:NSMakeRange(
                                         0u,
                                         state.preparedStateBindings.length)
                                     value:0u];
                [checkpointBlit fillBuffer:state.preparedStateActions
                                     range:NSMakeRange(
                                         0u,
                                         state.preparedStateActions.length)
                                     value:0u];
            }
            [checkpointBlit endEncoding];
            if (!checkpointValid) {
                diagnostics.message =
                    "prepared-state checkpoint arena is unavailable";
                return diagnostics;
            }
        }

        id<MTLComputeCommandEncoder> encoder =
            detail::timedEncoder(commandBuffer, state.device,
                request.phase == EncodePhase::preDynamics ? "matter_pre" : "matter_post",
                request.controlStep);
        if (encoder == nil) {
            diagnostics.message =
                "failed to create borrowed matter compute encoder";
            return diagnostics;
        }
        [encoder setLabel:request.phase == EncodePhase::preDynamics
            ? @"Numi Matter pre-dynamics"
            : @"Numi Matter post-commit"];

        const auto buffer = [&](void* value) -> id<MTLBuffer> {
            return value == nullptr
                ? state.dummy
                : (__bridge id<MTLBuffer>)value;
        };
        id<MTLBuffer> currentBodies = buffer(request.rigid.currentBodies);
        id<MTLBuffer> bodyWrenches = buffer(request.rigid.bodyWrenches);
        id<MTLBuffer> externalWrenches =
            buffer(request.rigid.externalWrenches);
        id<MTLBuffer> sceneBodies = buffer(request.rigid.sceneBodies);
        id<MTLBuffer> rodNodes = buffer(request.rigid.rodNodes);
        id<MTLBuffer> rodInverseMasses =
            buffer(request.rigid.rodInverseMasses);
        id<MTLBuffer> resetMasks = buffer(request.resetMasks);
        id<MTLBuffer> worldStatuses = buffer(request.environmentStatuses);
        const std::uint64_t requiredWorldStatusBytes =
            static_cast<std::uint64_t>(state.dispatch.environmentCount) *
            sizeof(MRMetalWorldStatusGPU);
        if (worldStatuses == nil || worldStatuses.device == nil ||
            worldStatuses.device.registryID != state.device.registryID ||
            worldStatuses.gpuAddress == 0u ||
            requiredWorldStatusBytes >
                static_cast<std::uint64_t>(worldStatuses.length)) {
            diagnostics.message =
                "borrowed MetalWorld status has wrong device provenance or byte capacity";
            return diagnostics;
        }

        NMMatterDispatchGPU frameDispatch = state.dispatch;
        frameDispatch.gravityAndTimestep.w = frameTimestep;
        NMBridgeDispatchGPU bridge{};
        bridge.environmentCount = state.dispatch.environmentCount;
        bridge.rigidProxyCount = state.dispatch.rigidProxyCount;
        bridge.currentBodyCount = request.rigid.currentBodyCount;
        bridge.currentBodyStride = request.rigid.currentBodyStride;
        bridge.bodyWrenchCount = request.rigid.bodyWrenchCount;
        bridge.sceneBodyCount = request.rigid.sceneBodyCount;
        bridge.bodyWrenchStride = request.rigid.bodyWrenchStride;
        bridge.sceneStride = request.rigid.sceneStride;
        bridge.reactionStride = state.dispatch.rigidProxyCount;
        bridge.reactionBodyCount = state.reactionBodyCount;
        bridge.rodNodeCount = request.rigid.rodNodeCount;
        bridge.rodNodeStride = request.rigid.rodNodeStride;
        bridge.time = {
            1.0f / frameTimestep,
            frameTimestep,
            0.0f,
            0.0f,
        };
        const std::uint32_t coupledArticulatedNv =
            state.requiresCoupledCandidate ? request.rigid.vStride : 0u;
        state.humanEqualityDispatch.time.x = frameTimestep;
        state.humanLimitDispatch.time.x = frameTimestep;
        state.humanSupportDispatch.articulatedNv = coupledArticulatedNv;
        state.humanSupportDispatch.articulationRootBody =
            request.articulationRootBody;
        state.humanSupportDispatch.bodyCount =
            request.rigid.currentBodyCount;
        state.humanSupportDispatch.bodyStride =
            request.rigid.currentBodyStride;
        state.humanSupportDispatch.groundPointAndTimestep.w = frameTimestep;

        // Argument-buffer resource declarations belong to an encoder, not
        // to the surrounding transaction. Borrowed articulated queries close
        // and replace that encoder during every Krylov column.
        id<MTLComputeCommandEncoder> primalResourcesEncoder = nil;
        const auto bindPrimalContactArguments = [&](const NSUInteger index) {
            if (primalResourcesEncoder != encoder) {
                [encoder useResource:state.contactPairs usage:MTLResourceUsageRead];
                [encoder useResource:state.contactSamples usage:MTLResourceUsageRead];
                [encoder useResource:state.contactNodeIncidence usage:MTLResourceUsageRead];
                [encoder useResource:state.contactNodeRanges usage:MTLResourceUsageRead];
                [encoder useResource:state.contactActivePairs usage:MTLResourceUsageRead];
                [encoder useResource:state.contactActiveSlotsByPair usage:MTLResourceUsageRead];
                [encoder useResource:state.contactActiveCounts usage:MTLResourceUsageRead];
                [encoder useResource:state.deformableContacts
                             usage:MTLResourceUsageRead | MTLResourceUsageWrite];
                [encoder useResource:state.deformableContactActiveIndices
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.deformableContactActiveCounts
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.deformableContactNodeIncidence
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.deformableContactNodeRanges
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.deformableContactGlobalActiveIndices
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.deformableContactActiveDispatch
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.mpmNodeToActive
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.mpmActiveNodeCounts
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.rigidProxies
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.rigidStates
                             usage:MTLResourceUsageRead];
                if (hasExternalWorldWrenches) {
                    [encoder useResource:externalWrenches
                                 usage:MTLResourceUsageRead];
                }
                primalResourcesEncoder = encoder;
            }
            [encoder setBuffer:state.primalContactArguments
                         offset:0u atIndex:index];
        };
        id<MTLComputeCommandEncoder> armijoPrimalResourcesEncoder = nil;
        const auto bindArmijoPrimalContactArguments =
            [&](const NSUInteger index) {
            if (armijoPrimalResourcesEncoder != encoder) {
                [encoder useResource:state.contactPairs
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.femArmijoBoxContactSamples
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.contactNodeIncidence
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.contactNodeRanges
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.femArmijoContactActivePairs
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.femArmijoContactActiveSlotsByPair
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.femArmijoContactActiveCounts
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.deformableContacts
                             usage:MTLResourceUsageRead |
                                  MTLResourceUsageWrite];
                [encoder useResource:state.deformableContactNodeIncidence
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.deformableContactNodeRanges
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.mpmNodeToActive
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.mpmActiveNodeCounts
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.rigidProxies
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.femArmijoRigidStates
                             usage:MTLResourceUsageRead];
                [encoder useResource:state.deformableContactActiveCounts
                             usage:MTLResourceUsageRead];
                if (hasExternalWorldWrenches) {
                    [encoder useResource:externalWrenches
                                 usage:MTLResourceUsageRead];
                }
                armijoPrimalResourcesEncoder = encoder;
            }
            [encoder setBuffer:state.femArmijoPrimalContactArguments
                         offset:0u atIndex:index];
        };

        const auto dispatchThreads = [&](
            const char* name,
            const NSUInteger count,
            const auto& bind
        ) {
            if (count == 0u) {
                return;
            }
            ++diagnostics.threadDispatchCount;
            diagnostics.requestedThreadCount +=
                static_cast<std::uint64_t>(count);
            id<MTLComputePipelineState> pipeline = state.pipeline(name);
            [encoder setComputePipelineState:pipeline];
            bind();
            const NSUInteger width = std::min<NSUInteger>(
                256u,
                pipeline.maxTotalThreadsPerThreadgroup
            );
            [encoder dispatchThreads:MTLSizeMake(count, 1u, 1u)
                threadsPerThreadgroup:MTLSizeMake(width, 1u, 1u)];
        };
        const auto dispatchGroups32 = [&](
            const char* name,
            const NSUInteger groupCount,
            const auto& bind
        ) {
            if (groupCount == 0u) {
                return;
            }
            ++diagnostics.simdgroupDispatchCount;
            diagnostics.requestedThreadgroupCount +=
                static_cast<std::uint64_t>(groupCount);
            const char* denseTiming = std::getenv("NUMI_MATTER_GPU_TIMING_DENSE45");
            const bool profileDense = request.controlStep == 100u &&
                denseTiming && std::strcmp(denseTiming, "1") == 0 &&
                std::strcmp(name, "nm_vascular_dense_solve") == 0;
            if (profileDense) {
                [encoder endEncoding];
                encoder = detail::timedEncoder(commandBuffer, state.device,
                    "vascular_dense45", request.controlStep);
                primalResourcesEncoder = nil;
            }
            [encoder setComputePipelineState:state.pipeline(name)];
            bind();
            [encoder dispatchThreadgroups:MTLSizeMake(groupCount, 1u, 1u)
                threadsPerThreadgroup:MTLSizeMake(32u, 1u, 1u)];
            if (profileDense) {
                [encoder endEncoding];
                encoder = detail::timedEncoder(commandBuffer, state.device,
                    "matter_after_dense45", request.controlStep);
                primalResourcesEncoder = nil;
            }
        };
        const auto dispatchGroups256 = [&](const char* name,
                                            const NSUInteger groupCount,
                                            const auto& bind) {
            if (groupCount == 0u) return;
            id<MTLComputePipelineState> pipeline = state.pipeline(name);
            if (pipeline.maxTotalThreadsPerThreadgroup < 256u) {
                diagnostics.message = std::string(name) +
                    " requires a 256-thread Metal threadgroup";
                return;
            }
            ++diagnostics.simdgroupDispatchCount;
            diagnostics.requestedThreadgroupCount +=
                static_cast<std::uint64_t>(groupCount);
            [encoder setComputePipelineState:pipeline];
            bind();
            [encoder dispatchThreadgroups:MTLSizeMake(groupCount, 1u, 1u)
                threadsPerThreadgroup:MTLSizeMake(256u, 1u, 1u)];
        };
        const auto dispatchIndirect = [&](
            const char* name,
            id<MTLBuffer> indirect,
            const NSUInteger width,
            const auto& bind
        ) {
            id<MTLComputePipelineState> pipeline = state.pipeline(name);
            if (pipeline == nil || indirect == nil ||
                width == 0u ||
                width > pipeline.maxTotalThreadsPerThreadgroup) {
                return false;
            }
            ++diagnostics.indirectDispatchCount;
            [encoder setComputePipelineState:pipeline];
            bind();
            [encoder
                dispatchThreadgroupsWithIndirectBuffer:indirect
                indirectBufferOffset:0u
                threadsPerThreadgroup:MTLSizeMake(width, 1u, 1u)];
            return true;
        };
        const auto setDispatch = [&]() {
            [encoder setBytes:&frameDispatch
                       length:sizeof(frameDispatch)
                      atIndex:0u];
            [encoder setBytes:&state.fgmresLayout
                       length:sizeof(state.fgmresLayout) atIndex:30u];
        };
        const auto buildDeformableNodeIncidence = [&](
            id<MTLBuffer> contacts,
            id<MTLBuffer> activeIndices,
            id<MTLBuffer> activeCounts,
            id<MTLBuffer> nodeRanges,
            id<MTLBuffer> nodeIncidence,
            id<MTLBuffer> statuses,
            const NSUInteger totalNodes
        ) {
            if (!state.deformableContactNodeIncidenceSortEnabled) {
                dispatchThreads(
                    "nm_contact_count_deformable_node_incidence",
                    totalNodes,
                    [&] {
                        setDispatch();
                        [encoder setBuffer:contacts offset:0u atIndex:1u];
                        [encoder setBuffer:activeIndices offset:0u atIndex:2u];
                        [encoder setBuffer:activeCounts offset:0u atIndex:3u];
                        [encoder setBuffer:nodeRanges offset:0u atIndex:4u];
                    });
                dispatchGroups32(
                    "nm_contact_scan_deformable_node_incidence",
                    state.dispatch.environmentCount,
                    [&] {
                        setDispatch();
                        [encoder setBuffer:nodeRanges offset:0u atIndex:1u];
                        [encoder setBuffer:statuses offset:0u atIndex:2u];
                    });
                dispatchThreads(
                    "nm_contact_scatter_deformable_node_incidence",
                    totalNodes,
                    [&] {
                        setDispatch();
                        [encoder setBuffer:contacts offset:0u atIndex:1u];
                        [encoder setBuffer:activeIndices offset:0u atIndex:2u];
                        [encoder setBuffer:activeCounts offset:0u atIndex:3u];
                        [encoder setBuffer:nodeRanges offset:0u atIndex:4u];
                        [encoder setBuffer:nodeIncidence offset:0u atIndex:5u];
                    });
                return;
            }

            const std::uint32_t padded =
                state.deformableContactNodeCornerSortPaddedCapacity;
            const NSUInteger sortThreadCount = static_cast<NSUInteger>(
                std::uint64_t(state.dispatch.environmentCount) * padded);
            dispatchThreads(
                "nm_contact_emit_deformable_node_corners",
                sortThreadCount,
                [&] {
                    setDispatch();
                    [encoder setBuffer:contacts offset:0u atIndex:1u];
                    [encoder setBuffer:activeIndices offset:0u atIndex:2u];
                    [encoder setBuffer:activeCounts offset:0u atIndex:3u];
                    [encoder setBuffer:state.deformableContactNodeCornerSortKeys
                                 offset:0u atIndex:4u];
                    [encoder setBuffer:state.deformableContactNodeCornerSortPayloads
                                 offset:0u atIndex:5u];
                    [encoder setBytes:&padded length:sizeof(padded) atIndex:6u];
                });
            [encoder memoryBarrierWithScope:MTLBarrierScopeBuffers];
            for (std::uint32_t width = 2u;; width *= 2u) {
                for (std::uint32_t distance = width / 2u;
                     distance != 0u; distance /= 2u) {
                    dispatchThreads(
                        "nm_contact_bitonic_sort_deformable_node_corners",
                        sortThreadCount,
                        [&] {
                            setDispatch();
                            [encoder setBytes:&padded length:sizeof(padded) atIndex:1u];
                            [encoder setBytes:&width length:sizeof(width) atIndex:2u];
                            [encoder setBytes:&distance length:sizeof(distance) atIndex:3u];
                            [encoder setBuffer:state.deformableContactNodeCornerSortKeys
                                         offset:0u atIndex:4u];
                            [encoder setBuffer:state.deformableContactNodeCornerSortPayloads
                                         offset:0u atIndex:5u];
