                "nm_contact_count_deformable_node_incidence_sorted",
                totalNodes,
                [&] {
                    setDispatch();
                    [encoder setBytes:&padded length:sizeof(padded) atIndex:1u];
                    [encoder setBuffer:state.deformableContactNodeCornerSortKeys
                                 offset:0u atIndex:2u];
                    [encoder setBuffer:nodeRanges offset:0u atIndex:3u];
                });
            [encoder memoryBarrierWithScope:MTLBarrierScopeBuffers];
            dispatchGroups32(
                "nm_contact_scan_deformable_node_incidence",
                state.dispatch.environmentCount,
                [&] {
                    setDispatch();
                    [encoder setBuffer:nodeRanges offset:0u atIndex:1u];
                    [encoder setBuffer:statuses offset:0u atIndex:2u];
                });
            [encoder memoryBarrierWithScope:MTLBarrierScopeBuffers];
            dispatchThreads(
                "nm_contact_scatter_deformable_node_incidence_sorted",
                sortThreadCount,
                [&] {
                    setDispatch();
                    [encoder setBytes:&padded length:sizeof(padded) atIndex:1u];
                    [encoder setBuffer:state.deformableContactNodeCornerSortKeys
                                 offset:0u atIndex:2u];
                    [encoder setBuffer:state.deformableContactNodeCornerSortPayloads
                                 offset:0u atIndex:3u];
                    [encoder setBuffer:nodeIncidence offset:0u atIndex:4u];
                });
        };
        const std::uint32_t microtickCount =
            1u << state.dispatch.maximumRateExponent;
        const auto invokeAcceptedStepExtension = [&] (
            AcceptedStepExtensionPhase phase,
            const std::uint32_t microtick
        ) {
            if (!hasAcceptedStepExtension) return true;
            AcceptedStepExtensionView view{};
            view.commandBuffer = request.commandBuffer;
            view.matterStatuses = (__bridge void*)state.statuses;
            view.vascularAccepted = (__bridge void*)state.vascularAccepted;
            view.vascularCandidate = (__bridge void*)state.vascularCandidate;
            view.vascularCheckpoint = (__bridge void*)state.vascularCheckpoint;
            view.vascularUnknowns = (__bridge void*)state.vascularUnknowns;
            view.vascularCompartments = (__bridge void*)state.vascularCompartments;
            view.vascularElastance = (__bridge void*)state.vascularElastance;
            view.vascularConnections = (__bridge void*)state.vascularConnections;
            view.vascularTissues = (__bridge void*)state.vascularTissues;
            view.vascularExchanges = (__bridge void*)state.vascularExchanges;
            view.vascularCavities = (__bridge void*)state.vascularCavities;
            view.vascularCompartmentCavity =
                (__bridge void*)state.vascularCompartmentCavity;
            view.vascularClockAccepted =
                (__bridge void*)state.vascularClockAccepted;
            view.vascularClockCandidate =
                (__bridge void*)state.vascularClockCandidate;
            view.vascularClockCheckpoint =
                (__bridge void*)state.vascularClockCheckpoint;
            view.vascularLayout = state.vascularValue.layout;
            view.environmentCount = state.dispatch.environmentCount;
            view.vascularStateStride = state.vascularValue.layout.ranges.z;
            view.compartmentCount = state.vascularValue.layout.counts.x;
            view.connectionCount = state.vascularValue.layout.counts.y;
            view.tissueCount = state.vascularValue.layout.counts.w;
            view.exchangeCount = state.vascularValue.layout.ranges.x;
            view.cavityCount = state.vascularValue.layout.cavities.x;
            view.controlStep = request.controlStep;
            view.physicsSubstep = request.physicsSubstep;
            view.physicsSubsteps = request.physicsSubsteps;
            view.microtick = microtick;
            view.microtickCount = microtickCount;
            view.vascularClockQuantumExponent = std::bit_cast<std::int32_t>(
                state.vascularValue.layout.clock.x);
            view.matterPhase = request.phase;
            view.vascularTimestepTicks = vascularTimestepTicks;
            view.frameTimestepSeconds = frameTimestep;
            view.microstepTimestepSeconds = frameTimestep /
                static_cast<float>(microtickCount);

            [encoder endEncoding];
            encoder = nil;
            if (!request.encodeAcceptedStepExtension(
                    request.acceptedStepExtensionContext, phase, view)) {
                ownership->preDynamicsOpen = false;
                diagnostics.message =
                    "accepted-step extension failed to encode its device transaction";
                return false;
            }
            const char* stage = phase == AcceptedStepExtensionPhase::frameBegin ? "matter_after_frame_begin" :
                phase == AcceptedStepExtensionPhase::candidateReady ? "matter_after_candidate_ready" :
                phase == AcceptedStepExtensionPhase::microstepComplete ? "matter_after_microstep" :
                "matter_after_frame_complete";
            encoder = detail::timedEncoder(commandBuffer, state.device, stage, request.controlStep);
            if (encoder == nil) {
                ownership->preDynamicsOpen = false;
                diagnostics.message =
                    "failed to resume Matter after accepted-step extension";
                return false;
            }
            [encoder setLabel:request.phase == EncodePhase::preDynamics
                ? @"Numi Matter physiological continuation"
                : @"Numi Matter post-commit physiological continuation"];
            return true;
        };
        const NSUInteger environments = state.dispatch.environmentCount;
        const NSUInteger objects = state.dispatch.objectCount;
        const NSUInteger particleTotal =
            environments * state.dispatch.particleCount;
        const NSUInteger mpmActiveNodeTotal =
            environments * state.dispatch.mpmActiveNodeCapacity;
        const NSUInteger femNodeTotal =
            environments * state.dispatch.femNodeCount;
        const NSUInteger continuumNodeTotal = environments *
            (state.dispatch.gridNodeCount + state.dispatch.femNodeCount);
        const NSUInteger surfacePrimitiveTotal = environments *
            static_cast<NSUInteger>(
                continuumSurfacePrimitiveCount(state.dispatch));
        const NSUInteger tetrahedronTotal =
            environments * state.dispatch.tetrahedronCount;
        const NSUInteger cohesiveFaceTotal =
            environments * state.dispatch.cohesiveFaceCount;
        const NSUInteger femTransactionalTotal = environments * std::max(
            state.dispatch.femNodeCount,
            state.dispatch.tetrahedronCount
        );
        const NSUInteger pairTotal =
            environments * state.dispatch.contactPairCount;
        const NSUInteger femHumanAttachmentTotal =
            environments * state.dispatch.femHumanAttachmentCount;
        const NSUInteger deformableContactHistoryTotal =
            environments * state.dispatch.deformableContactCapacity;
        const NSUInteger humanSupportTotal = environments *
            state.humanSupportDispatch.contactCount;
        const NSUInteger vascularTotal = environments *
            state.vascularValue.layout.ranges.z;
        const NSUInteger proxyTotal =
            environments * state.dispatch.rigidProxyCount;
        const NSUInteger bodyWrenchTotal =
            environments * state.reactionBodyCount;
        const NSUInteger objectTotal = environments * objects;
        const NSUInteger mixedTransactionalTotal = std::max(
            femNodeTotal, objectTotal
        );
        const NSUInteger topologyTransactionalTotal = environments * std::max({
            static_cast<NSUInteger>(state.dispatch.femNodeCount),
            static_cast<NSUInteger>(state.dispatch.tetrahedronCount),
            static_cast<NSUInteger>(state.dispatch.cohesiveFaceCount),
            static_cast<NSUInteger>(state.dispatch.punctureChannelCount),
            static_cast<NSUInteger>(state.dispatch.objectCount),
            static_cast<NSUInteger>(state.dispatch.tetrahedronCount) * 4u
        });

        const auto encodeFEMHumanAttachmentKinematics = [&]() -> bool {
            if (state.dispatch.femHumanAttachmentCount == 0u) return true;
            [encoder endEncoding];
            encoder = nil;
            const std::uint32_t pointCount =
                state.dispatch.femHumanAttachmentCount;
            const CoupledCandidateQuery query{
                .input = (__bridge void*)
                    state.coupledGeneralizedCandidate,
                .candidateQ = (__bridge void*)state.coupledCandidateQ,
                .candidateBodies = (__bridge void*)
                    state.coupledCandidateBodies,
                .pointQueries = (__bridge void*)
                    state.femHumanAttachmentPointQueries,
                .pointJacobians = (__bridge void*)
                    state.femHumanAttachmentPointJacobians,
                .operation =
                    CoupledCandidateOperation::candidateKinematics,
                .generalizedVectorStride =
                    state.dispatch.rigidGeneralizedCapacity,
                .candidateQStride = state.coupledQStride,
                .candidateBodyStride = state.coupledBodyStride,
                .pointCount = pointCount,
                .pointStride = pointCount,
                .pointJacobianStride =
                    state.dispatch.femHumanAttachmentPointJacobianStride,
                .candidateRootTranslation = state.coupledCandidateCompensatedTranslation ? (__bridge void*)state.coupledCandidateRootTranslation : nullptr,
                .candidateBodyPositionLow = state.coupledCandidateCompensatedTranslation ? (__bridge void*)state.coupledCandidateBodyPositionLow : nullptr,
                .pointPositionLow = nullptr,
                .candidateRootTranslationGPUAddress = state.coupledCandidateCompensatedTranslation ? state.coupledCandidateRootTranslation.gpuAddress : 0u,
                .candidateBodyPositionLowGPUAddress = state.coupledCandidateCompensatedTranslation ? state.coupledCandidateBodyPositionLow.gpuAddress : 0u,
                .pointPositionLowGPUAddress = 0u,
                .candidateRootTranslationElementCount = state.coupledCandidateCompensatedTranslation ? state.dispatch.environmentCount : 0u,
                .candidateBodyPositionLowElementCount = state.coupledCandidateCompensatedTranslation ? std::uint64_t(state.dispatch.environmentCount) * state.coupledBodyStride : 0u,
                .pointPositionLowElementCount = 0u,
                .legacyHighOnly = !state.coupledCandidateCompensatedTranslation,
            };
            if (!request.encodeCoupledCandidate(
                    request.coupledCandidateContext, query)) {
                diagnostics.message =
                    "Human candidate service rejected exact FEM attachment kinematics";
                return false;
            }
            encoder = [commandBuffer computeCommandEncoder];
            if (encoder == nil) {
                diagnostics.message =
                    "failed to resume Matter after FEM attachment kinematics";
                return false;
            }
            [encoder setLabel:@"Numi Matter Human/FEM attachment continuation"];
            dispatchThreads(
                "nm_fem_human_attachment_drive_candidate",
                femHumanAttachmentTotal,
                [&] {
                    setDispatch();
                    [encoder setBytes:&request.rigid.currentBodyCount
                               length:sizeof(request.rigid.currentBodyCount)
                              atIndex:1u];
                    [encoder setBytes:&request.rigid.currentBodyStride
                               length:sizeof(request.rigid.currentBodyStride)
                              atIndex:2u];
                    [encoder setBytes:&coupledArticulatedNv
                               length:sizeof(coupledArticulatedNv)
                              atIndex:3u];
                    [encoder setBuffer:state.femHumanAttachments
                                 offset:0u atIndex:4u];
                    [encoder setBuffer:state.coupledCandidateBodies
                                 offset:0u atIndex:5u];
                    [encoder setBuffer:state.femHumanAttachmentPointJacobians
                                 offset:0u atIndex:6u];
                    [encoder setBuffer:state.coupledGeneralizedCandidate
                                 offset:0u atIndex:7u];
                    [encoder setBuffer:state.femAccepted
                                 offset:0u atIndex:8u];
                    [encoder setBuffer:state.femCandidate
                                 offset:0u atIndex:9u];
                    [encoder setBuffer:state.femNodeRanges
                                 offset:0u atIndex:10u];
                    [encoder setBuffer:state.statuses
                                 offset:0u atIndex:11u];
                    [encoder setBuffer:state.coupledCandidateBodyPositionLow offset:0u atIndex:12u];
                    [encoder setBytes:&coupledPositionPrecision length:sizeof(coupledPositionPrecision) atIndex:13u];
                }
            );
            return true;
        };
        const auto captureFEMHumanAttachmentResidual = [&]() {
            dispatchThreads(
                "nm_fem_human_attachment_capture_residual",
                femHumanAttachmentTotal,
                [&] {
                    setDispatch();
                    [encoder setBuffer:state.femHumanAttachments
                                 offset:0u atIndex:1u];
                    [encoder setBuffer:state.objects offset:0u atIndex:2u];
                    [encoder setBuffer:state.femNodeRanges
                                 offset:0u atIndex:3u];
                    [encoder setBuffer:state.schedulers offset:0u atIndex:4u];
                    [encoder setBuffer:state.femCandidate
                                 offset:0u atIndex:5u];
                    [encoder setBuffer:state.femResidual
                                 offset:0u atIndex:6u];
                    [encoder setBuffer:state.femPreconditioned
                                 offset:0u atIndex:7u];
                    [encoder setBuffer:state.femDirection
                                 offset:0u atIndex:8u];
                    [encoder
                        setBuffer:state.femHumanAttachmentResidualImpulses
                           offset:0u atIndex:9u];
                    [encoder setBuffer:state.femHumanAttachmentRawReactions
                                 offset:0u atIndex:10u];
                    [encoder setBuffer:state.statuses
                                 offset:0u atIndex:11u];
                }
            );
        };
        const auto scatterFEMHumanAttachmentResidual = [&]() {
