            dispatchThreads(
                "nm_invalidate_solver_certificate_after_late_failure",
                environments, [&] {
                setDispatch();
                [encoder setBuffer:state.statuses offset:0u atIndex:1u];
                [encoder setBuffer:state.solverCertificates offset:0u atIndex:2u];
