                    id<MTLBuffer> output, std::uint32_t useWorkingSet = 1u) {
                dispatchThreads(kernel, vascularTotal, [&] {
                    setDispatch();
                    [encoder setBytes:&state.vascularValue.layout
                        length:sizeof(state.vascularValue.layout) atIndex:1u];
                    [encoder setBytes:&micro length:sizeof(micro) atIndex:2u];
                    [encoder setBuffer:state.vascularUnknowns offset:0u atIndex:3u];
                    [encoder setBuffer:state.vascularCompartments offset:0u atIndex:4u];
                    [encoder setBuffer:state.vascularConnections offset:0u atIndex:5u];
                    [encoder setBuffer:state.vascularTissues offset:0u atIndex:6u];
                    [encoder setBuffer:state.vascularExchanges offset:0u atIndex:7u];
                    [encoder setBuffer:state.vascularConnectionIncidence offset:0u atIndex:8u];
                    [encoder setBuffer:state.vascularConnectionRanges offset:0u atIndex:9u];
                    [encoder setBuffer:state.vascularBloodExchangeIncidence offset:0u atIndex:10u];
                    [encoder setBuffer:state.vascularBloodExchangeRanges offset:0u atIndex:11u];
                    [encoder setBuffer:state.vascularTissueExchangeIncidence offset:0u atIndex:12u];
                    [encoder setBuffer:state.vascularTissueExchangeRanges offset:0u atIndex:13u];
                    [encoder setBuffer:state.vascularAccepted offset:0u atIndex:14u];
                    [encoder setBuffer:state.vascularCandidate offset:0u atIndex:15u];
                    [encoder setBuffer:direction offset:directionOffset atIndex:16u];
                    [encoder setBuffer:output offset:0u atIndex:17u];
                    [encoder setBuffer:state.fgmresStates offset:0u atIndex:18u];
                    [encoder setBuffer:state.statuses offset:0u atIndex:19u];
                    [encoder setBuffer:state.vascularElastance offset:0u atIndex:20u];
                    [encoder setBuffer:state.vascularWorkingSet offset:0u atIndex:21u];
                    [encoder setBytes:&useWorkingSet length:sizeof(useWorkingSet) atIndex:22u];
                    [encoder setBuffer:state.vascularCavities offset:0u atIndex:23u];
                    [encoder setBuffer:state.vascularCavityFaces offset:0u atIndex:24u];
                    [encoder setBuffer:state.vascularCompartmentCavity offset:0u atIndex:25u];
                    [encoder setBuffer:state.femCandidate offset:0u atIndex:26u];
                    [encoder setBuffer:state.femAccepted offset:0u atIndex:27u];
                });
            };
            // Reassemble hydraulic wall work with borrowed loads at the same
            // candidate used by the mechanical residual and final certificate.
            const auto encodeCavityForces = [&]() {
                if (!hasVascularMechanicalForces) return;
                dispatchThreads("nm_vascular_cavity_forces", femNodeTotal, [&] {
                    setDispatch();
                    [encoder setBytes:&state.vascularValue.layout length:sizeof(state.vascularValue.layout) atIndex:1u];
                    [encoder setBytes:&micro length:sizeof(micro) atIndex:2u];
                    [encoder setBuffer:state.vascularUnknowns offset:0u atIndex:3u];
                    [encoder setBuffer:state.vascularCompartments offset:0u atIndex:4u];
                    [encoder setBuffer:state.vascularCavities offset:0u atIndex:5u];
                    [encoder setBuffer:state.vascularCavityFaces offset:0u atIndex:6u];
                    [encoder setBuffer:state.vascularCavityNodeIncidence offset:0u atIndex:7u];
                    [encoder setBuffer:state.vascularCavityNodeRanges offset:0u atIndex:8u];
                    [encoder setBuffer:state.femAccepted offset:0u atIndex:9u];
                    [encoder setBuffer:state.femCandidate offset:0u atIndex:10u];
                    [encoder setBuffer:state.vascularCandidate offset:0u atIndex:11u];
                    [encoder setBuffer:femExternalForces offset:0u atIndex:12u];
                    [encoder setBytes:&hasFEMExternalForces length:sizeof(hasFEMExternalForces) atIndex:13u];
                    [encoder setBuffer:state.vascularCavityMergedExternal offset:0u atIndex:14u];
                    [encoder setBuffer:state.statuses offset:0u atIndex:15u];
                    [encoder setBuffer:state.vascularTissues offset:0u atIndex:16u];
                    [encoder setBuffer:state.vascularTissueBindings offset:0u atIndex:17u];
                    [encoder setBuffer:state.vascularElastance offset:0u atIndex:18u];
                    [encoder setBuffer:state.vascularConnections offset:0u atIndex:19u];
                    [encoder setBuffer:state.vascularAccepted offset:0u atIndex:20u];
                });
            };
            // Opt-in, bounded copies at a single requested root preserve the
            // failing Newton iterate before transactional rollback. The caller
            // retains submission authority; no new queue, commit, or wait.
            const auto encodeVascularTrace = [&](const char* stage) -> bool {
                const char* traceRoot = std::getenv("NM_VASCULAR_TRACE_ROOT");
                if (traceRoot == nullptr || vascularTotal == 0u || vascularTotal > 4096u ||
                    request.controlStep != std::strtoul(traceRoot, nullptr, 10)) return true;
                struct TraceArena { const char* name; id<MTLBuffer> source; NSUInteger offset; NSUInteger bytes; };
                const NSUInteger vectorOffset = state.fgmresLayout.vascularBase * sizeof(nm_float4);
                const NSUInteger vectorBytes = vascularTotal * sizeof(nm_float4);
                const std::array<TraceArena, 11u> arenas{{
                    {"accepted", state.vascularAccepted, 0u, vectorBytes},
                    {"candidate", state.vascularCandidate, 0u, vectorBytes},
                    {"residual", state.femResidual, vectorOffset, vectorBytes},
                    {"solution", state.femSolution, vectorOffset, vectorBytes},
                    {"alpha", state.environmentLineSearch, 0u, environments * sizeof(float)},
                    {"working_set", state.vascularWorkingSet, 0u, vascularTotal * sizeof(std::uint32_t)},
                    {"working_set_changed", state.vascularWorkingSetChanged, 0u, environments * sizeof(std::uint32_t)},
                    {"fgmres", state.fgmresStates, 0u, environments * sizeof(NMFGMRESStateGPU)},
                    {"elastance", state.vascularElastance, 0u, environments * state.vascularValue.layout.counts.x * sizeof(float)},
                    {"clock", state.vascularClockCandidate, 0u, environments * sizeof(NMVascularClockGPU)},
                    {"status", state.statuses, 0u, environments * sizeof(NMMatterStatusGPU)},
                }};
                NSUInteger bytes = 0u;
                for (const auto& arena : arenas) bytes += (arena.bytes + 15u) & ~15u;
                id<MTLBuffer> snapshot = [state.device newBufferWithLength:bytes options:MTLResourceStorageModeShared];
                [encoder endEncoding];
                encoder = nil;
                id<MTLBlitCommandEncoder> copy = [commandBuffer blitCommandEncoder];
                if (snapshot == nil || copy == nil) {
                    if (copy != nil) [copy endEncoding];
                    diagnostics.message = "failed to allocate vascular diagnostic snapshot";
                    return false;
                }
                NSUInteger offset = 0u;
                for (const auto& arena : arenas) {
                    [copy copyFromBuffer:arena.source sourceOffset:arena.offset toBuffer:snapshot destinationOffset:offset size:arena.bytes];
                    offset += (arena.bytes + 15u) & ~15u;
                }
                [copy endEncoding];
                const auto root = request.controlStep;
                const auto iteration = micro.solverIteration;
                const auto tick = microtick;
                [commandBuffer addCompletedHandler:^(id<MTLCommandBuffer> completed) {
                    if (completed.status != MTLCommandBufferStatusCompleted) return;
                    std::ostringstream line;
                    line << "vascular_iterate={\"root\":" << root << ",\"microtick\":" << tick
                         << ",\"iteration\":" << iteration << ",\"stage\":\"" << stage << "\",\"arenas\":{";
                    const auto* data = static_cast<const unsigned char*>(snapshot.contents);
                    NSUInteger at = 0u;
                    bool first = true;
                    constexpr char hex[] = "0123456789abcdef";
                    for (const auto& arena : arenas) {
                        if (!first) line << ',';
                        first = false;
                        line << '\"' << arena.name << "\":\"";
                        for (NSUInteger i = 0u; i < arena.bytes; ++i) line << hex[data[at + i] >> 4u] << hex[data[at + i] & 15u];
                        line << '\"';
                        at += (arena.bytes + 15u) & ~15u;
                    }
                    line << "}}\n";
                    const auto text = line.str();
                    std::fwrite(text.data(), 1u, text.size(), stderr);
                }];
                encoder = [commandBuffer computeCommandEncoder];
                if (encoder == nil) {
                    diagnostics.message = "failed to resume Matter after vascular diagnostic snapshot";
                    return false;
                }
                return true;
            };
            // Optional compact trace for one Newton microstep. FGMRES already
            // stores the exact assembled full-space residual norm at the start
            // of each Newton solve in nonlinear.y. This trace does not copy a
            // partial FEM residual or label an Arnoldi estimate as b-Ax.
            bool femNewtonTraceNoticeLogged = false;
            bool femNewtonTraceSelectorErrorLogged = false;
            bool femNewtonTraceCapturedAny = false;
            const auto femNewtonTraceScope = [&]() -> const char* {
                if (request.physicsSubsteps != 1u ||
                    request.physicsSubstep != 0u)
                    return "requires_one_physics_substep_at_index_zero";
                if (state.dispatch.maximumRateExponent != 0u)
                    return "requires_maximum_rate_exponent_zero";
                if (state.dispatch.environmentCount > 4u)
                    return "environment_cap_4";
                if (state.dispatch.femNodeCount == 0u ||
                    state.dispatch.femNodeCount > 4096u)
                    return "fem_node_cap_4096";
                if (state.dispatch.objectCount != 1u ||
                    state.dispatch.tetrahedronCount == 0u)
                    return "requires_one_explicit_fem_object";
                constexpr std::uint32_t unsupportedMatterFlags =
                    NM_MATTER_ADAPTIVE | NM_MATTER_IDENTIFICATION |
                    NM_MATTER_MIXED_FEM | NM_MATTER_MULTIPHYSICS |
                    NM_MATTER_MUTATION | NM_MATTER_LEARNED_MATERIAL;
                if ((state.dispatch.flags & unsupportedMatterFlags) != 0u ||
                    state.dispatch.particleCount != 0u ||
                    state.dispatch.mpmGridCount != 0u ||
                    state.dispatch.mpmBlockCount != 0u ||
                    state.dispatch.mpmActiveNodeCapacity != 0u)
                    return "requires_static_fem_without_mpm_or_mixed_fields";
                if (state.dispatch.fieldBoundaryCount != 0u ||
                    state.dispatch.rigidGeneralizedCapacity != 0u ||
                    state.dispatch.femHumanAttachmentCount != 0u ||
                    state.dispatch.learnedMaterialCount != 0u ||
                    state.dispatch.learnedWeightCount != 0u ||
                    state.dispatch.mutationCommandCount != 0u ||
                    state.fgmresLayout.supportContactCount != 0u ||
                    state.fgmresLayout.vascularUnknownCount != 0u ||
                    state.fgmresLayout.unknownCount !=
                        2u * environments * state.dispatch.femNodeCount)
                    return "requires_fem_nodes_as_only_generalized_unknowns";
                return nullptr;
            };
            const auto femResidualArmijoScope = [&]() -> const char* {
                if (!state.femResidualArmijoScratchEnabled)
                    return "armijo_scratch_was_not_reserved_at_runtime_creation";
                if (microtick != 0u)
                    return "requires_microtick_zero";
                if (const char* reason = femNewtonTraceScope())
                    return reason;
                constexpr std::uint32_t unsupportedMatterFlags =
                    NM_MATTER_CONTACT | NM_MATTER_ADAPTIVE |
                    NM_MATTER_IDENTIFICATION | NM_MATTER_MIXED_FEM |
                    NM_MATTER_MULTIPHYSICS | NM_MATTER_MUTATION |
                    NM_MATTER_LEARNED_MATERIAL;
                if ((state.dispatch.flags & unsupportedMatterFlags) != 0u ||
                    state.dispatch.rigidProxyCount != 0u ||
                    state.dispatch.contactPairCount != 0u ||
                    state.dispatch.cohesiveFaceCount != 0u ||
                    state.dispatch.punctureChannelCount != 0u ||
                    state.dispatch.rigidQCapacity != 0u ||
                    state.dispatch.fieldBoundaryCount != 0u)
                    return "requires_no_contact_mixed_cohesive_or_mutable_topology";
                if (state.objectLayout.size() != 1u ||
                    state.objectLayout[0].representation != NM_REPRESENTATION_FEM ||
                    (state.objectLayout[0].flags &
                        (NM_OBJECT_ADAPTIVE |
                         NM_OBJECT_IDENTIFIABLE | NM_OBJECT_MIXED_FEM |
                         NM_OBJECT_MULTIPHYSICS | NM_OBJECT_MUTABLE_TOPOLOGY)) != 0u ||
                    (state.objectLayout[0].flags &
                        (NM_OBJECT_DISABLE_SELF_CONTACT |
                         NM_OBJECT_DISABLE_DEFORMABLE_CONTACT)) !=
                        (NM_OBJECT_DISABLE_SELF_CONTACT |
                         NM_OBJECT_DISABLE_DEFORMABLE_CONTACT))
                    return "requires_one_static_explicit_fem_object";
                if (!state.vascularValue.unknowns.empty() ||
                    !state.vascularValue.cavities.empty() ||
                    !state.vascularValue.cavityFaces.empty() ||
                    state.enableVascularDense45)
                    return "vascular_coupling_is_outside_first_residual_armijo_slice";
                return nullptr;
            };
            const auto femCohesiveResidualArmijoScope = [&]() -> const char* {
                if (!state.femResidualArmijoScratchEnabled)
                    return "armijo_scratch_was_not_reserved_at_runtime_creation";
                if (state.femArmijoCohesiveFaces == nil ||
                    state.femArmijoCohesiveFaceForces == nil)
                    return "private_cohesive_trial_arena_missing_or_over_cap";
                if (microtick != 0u)
                    return "requires_microtick_zero";
                if (const char* reason = femNewtonTraceScope())
                    return reason;
                constexpr std::uint32_t unsupportedMatterFlags =
                    NM_MATTER_CONTACT | NM_MATTER_ADAPTIVE |
                    NM_MATTER_IDENTIFICATION | NM_MATTER_MIXED_FEM |
                    NM_MATTER_MULTIPHYSICS | NM_MATTER_MUTATION |
                    NM_MATTER_LEARNED_MATERIAL;
                if ((state.dispatch.flags & unsupportedMatterFlags) != 0u ||
                    state.dispatch.rigidProxyCount != 0u ||
                    state.dispatch.contactPairCount != 0u ||
                    state.dispatch.cohesiveFaceCount == 0u ||
                    state.dispatch.cohesiveFaceCount > 4096u ||
                    state.dispatch.punctureChannelCount != 0u ||
                    state.dispatch.rigidQCapacity != 0u ||
                    state.dispatch.fieldBoundaryCount != 0u)
                    return "requires_bounded_mixed_cohesive_without_contact_or_mutation";
                if (!state.femArmijoMixedCohesiveSupported)
                    return "requires_authored_paired_mixed_mode_faces_only";
                if (state.objectLayout.size() != 1u ||
                    state.objectLayout[0].representation != NM_REPRESENTATION_FEM ||
                    (state.objectLayout[0].flags &
                        (NM_OBJECT_ADAPTIVE |
                         NM_OBJECT_IDENTIFIABLE | NM_OBJECT_MIXED_FEM |
                         NM_OBJECT_MULTIPHYSICS | NM_OBJECT_MUTABLE_TOPOLOGY)) != 0u ||
                    (state.objectLayout[0].flags &
                        (NM_OBJECT_DISABLE_SELF_CONTACT |
                         NM_OBJECT_DISABLE_DEFORMABLE_CONTACT)) !=
                        (NM_OBJECT_DISABLE_SELF_CONTACT |
                         NM_OBJECT_DISABLE_DEFORMABLE_CONTACT))
                    return "requires_one_static_explicit_fem_object";
                if (!state.vascularValue.unknowns.empty() ||
                    !state.vascularValue.cavities.empty() ||
                    !state.vascularValue.cavityFaces.empty() ||
                    state.enableVascularDense45)
                    return "vascular_coupling_is_outside_cohesive_armijo_slice";
                return nullptr;
            };
            const auto femOperatorFDScope = [&]() -> const char* {
                if (!state.femOperatorFDScratchEnabled)
                    return "operator_fd_scratch_not_reserved_or_memory_cap_exceeded";
                if (const char* reason = femResidualArmijoScope())
                    return reason;
                if (state.dispatch.tetrahedronCount > 8192u)
                    return "tetrahedron_cap_8192";
                if (state.dispatch.materialStateStride == 0u ||
                    state.dispatch.materialStateStride > 32u)
                    return "material_state_stride_outside_1_to_32";
                // Residual rows eliminate non-positive masses, whereas the
                // production operator eliminates only constraint tags. This
                // immutable scope must keep the two row spaces identical.
                // Runtime restore already binds mass to this authored layout.
                if (state.femAuthoredMassLayout.size() != state.dispatch.femNodeCount ||
                    std::any_of(state.femAuthoredMassLayout.begin(),
                        state.femAuthoredMassLayout.end(), [](const auto& mass) {
                            return !std::isfinite(mass[0]) || !(mass[0] > 0.0f);
                        }))
                    return "requires_positive_finite_immutable_nodal_masses";
                if (state.femOperatorFDInputsUnchanged == nil ||
                    state.femOperatorFDHistorySnapshot == nil ||
                    state.femOperatorFDTetrahedronSnapshot == nil ||
                    state.femOperatorFDStatusSnapshot == nil ||
                    state.femOperatorFDMetrics == nil)
                    return "bounded_diagnostic_arena_incomplete";
                const char* capturePath =
                    std::getenv("NM_FEM_OPERATOR_FD_CAPTURE_PATH");
                if (capturePath != nullptr && capturePath[0] != '\0' &&
                    (!state.femOperatorFDRichCaptureEnabled ||
                     state.femOperatorFDNodeSnapshot == nil ||
                     state.femOperatorFDRichCapture == nil))
                    return "rich_capture_arena_not_reserved_or_memory_cap_exceeded";
                return nullptr;
            };
            const auto femCapsuleResidualArmijoScope = [&]() -> const char* {
                if (!state.femResidualArmijoScratchEnabled)
                    return "armijo_scratch_was_not_reserved_at_runtime_creation";
                if (microtick != 0u)
                    return "requires_microtick_zero";
                if (const char* reason = femNewtonTraceScope())
                    return reason;
                constexpr std::uint32_t unsupportedMatterFlags =
                    NM_MATTER_ADAPTIVE | NM_MATTER_IDENTIFICATION |
                    NM_MATTER_MIXED_FEM | NM_MATTER_MULTIPHYSICS |
                    NM_MATTER_MUTATION | NM_MATTER_LEARNED_MATERIAL;
                if ((state.dispatch.flags & unsupportedMatterFlags) != 0u ||
                    (state.dispatch.flags & NM_MATTER_CONTACT) == 0u ||
                    state.dispatch.contactPairCount == 0u ||
                    state.dispatch.contactPairCount > 16384u ||
                    state.dispatch.rigidProxyCount == 0u ||
                    state.dispatch.rigidProxyCount > 16u ||
                    state.dispatch.tetrahedronCount > 32768u ||
                    state.dispatch.cohesiveFaceCount != 0u ||
                    state.dispatch.punctureChannelCount != 0u ||
                    state.dispatch.rigidQCapacity != 0u ||
                    state.contactPairLayout.size() !=
                        state.dispatch.contactPairCount ||
                    state.rigidProxyLayout.size() !=
                        state.dispatch.rigidProxyCount ||
                    state.femArmijoContactSamples == nil)
                    return "requires_bounded_prescribed_capsule_contact";
                if (state.objectLayout.size() != 1u ||
                    state.objectLayout[0].representation != NM_REPRESENTATION_FEM ||
                    (state.objectLayout[0].flags &
                        (NM_OBJECT_ADAPTIVE | NM_OBJECT_IDENTIFIABLE |
                         NM_OBJECT_MIXED_FEM |
                         NM_OBJECT_MULTIPHYSICS | NM_OBJECT_MUTABLE_TOPOLOGY)) != 0u ||
                    (state.objectLayout[0].flags &
                        (NM_OBJECT_DISABLE_SELF_CONTACT |
                         NM_OBJECT_DISABLE_DEFORMABLE_CONTACT)) !=
                        (NM_OBJECT_DISABLE_SELF_CONTACT |
                         NM_OBJECT_DISABLE_DEFORMABLE_CONTACT))
                    return "requires_one_static_explicit_fem_object";
                if (!state.hasPrescribedTranslation ||
                    !state.requiresCurrentBodies ||
                    state.requiresCoupledCandidate)
                    return "requires_endpoint_authoritative_static_capsule_proxies";
                for (const NMRigidProxyGPU& proxy : state.rigidProxyLayout) {
                    if (proxy.shapeKind != NM_RIGID_CAPSULE ||
                        proxy.flags != NM_RIGID_PRESCRIBED_TRANSLATION ||
                        proxy.bodyIndex == NM_INVALID_INDEX ||
                        proxy.adaptiveObjectIndex != NM_INVALID_INDEX ||
                        proxy.generalizedFreeBodyIndex != NM_INVALID_INDEX)
                        return "requires_prescribed_capsules_without_rigid_unknowns";
                }
                for (const NMContactPairGPU& pair : state.contactPairLayout) {
                    if (pair.objectIndex != 0u ||
                        pair.continuumNode >= state.dispatch.femNodeCount ||
                        pair.rigidProxy >= state.dispatch.rigidProxyCount)
                        return "requires_contact_pairs_owned_by_fem_and_capsules";
                }
                if (!state.vascularValue.unknowns.empty() ||
                    !state.vascularValue.cavities.empty() ||
                    !state.vascularValue.cavityFaces.empty() ||
                    state.enableVascularDense45)
                    return "vascular_coupling_is_outside_capsule_armijo_slice";
                return nullptr;
            };
            const auto femCapsuleBoxResidualArmijoScope = [&](
                    const bool allowCohesive = false,
                    const bool allowDeformableSelfContact = false,
                    const bool allowFreeRigidBody = false) -> const char* {
                if (state.femArmijoSparseContactRequested &&
                    (!allowCohesive || !allowDeformableSelfContact))
                    return "sparse_private_contact_is_scoped_to_full_contact_armijo";
                if (!state.femResidualArmijoScratchEnabled)
                    return "armijo_scratch_was_not_reserved_at_runtime_creation";
                if (retainPreparedState || request.enablePreparedState ||
                    request.runAdaptiveTransfer || request.runIdentification ||
                    request.resetMaskStepStride != 0u ||
                    request.mutationCommandCount != 0u ||
                    request.learnedWeightCount != 0u ||
                    request.femExternalForces != nullptr ||
                    request.femExternalForceCount != 0u ||
                    request.rigidContactConstraints != nullptr ||
                    request.deferAcceptedControlCursorPublication ||
                    hasAcceptedStepExtension)
