                                        capturedAppendTraceFloat(line, record[1].w);
                                        line << ",\"material_parameter_count\":";
                                        capturedAppendTraceFloat(line, record[2].x);
                                        line << ",\"object_index\":";
                                        capturedAppendTraceFloat(line, record[2].y);
