                                        appendVec4(line, center[52u]);
                                        line << ",\"flags_terminal_status_parameter_count\":";
                                        appendVec4(line, center[53u]);
                                        line << ",\"hill_q_lambda_a_b\":";
                                        appendVec4(line, center[54u]);
