                            capturedAppendTraceFloat(line, row[2].x);
                            line << ",\"relative_error\":";
                            capturedAppendTraceFloat(line, row[2].y);
                            line << ",\"action_dot_fd\":";
                            capturedAppendTraceFloat(line, row[2].z);
                            line << ",\"action_fd_cosine\":";
                            capturedAppendTraceFloat(line, row[2].w);
