                    std::fwrite(text.data(), 1u, text.size(), stderr);
                }];
                encoder = [commandBuffer computeCommandEncoder];
                if (encoder == nil) {
                    diagnostics.message = "failed to resume Matter after FEM Newton trace";
                    return false;
                }
