            }
            dispatchGroups32("nm_mpm_compact_active_nodes", environments, [&] {
                setDispatch();
                [encoder setBytes:&micro length:sizeof(micro) atIndex:1u];
                [encoder setBuffer:state.gridNodes offset:0u atIndex:2u];
