            const auto encodeCoupledPrimalContact = [&] (
                const bool certify,
                id<MTLBuffer> histories,
                id<MTLBuffer> deformableContactHistories
            ) -> bool {
                if (state.requiresCoupledCandidate) {
                    [encoder endEncoding];
                    encoder = nil;
