            const auto encodeArmijoDeformableContact = [&] (
                    id<MTLBuffer> trialNodes,
                    id<MTLBuffer> trialStatuses,
                    id<MTLBuffer> history,
                    id<MTLBuffer> cohesiveFaces) -> bool {
                if (!state.femArmijoDeformableContactScratchEnabled)
