                const std::uint32_t leafCount = state.femSurfaceBVHLeafCount;
                dispatchThreads("nm_contact_build_surface_primitives",
                    surfacePrimitiveTotal, [&] {
                    setDispatch();
                    [encoder setBytes:&micro length:sizeof(micro) atIndex:1u];
