                    dispatchThreads("nm_contact_build_surface_bvh_level",
                        environments * width, [&] {
                        setDispatch();
                        [encoder setBytes:&leafCount length:sizeof(leafCount)
                                   atIndex:1u];
                        [encoder setBytes:&width length:sizeof(width) atIndex:2u];
