                    [encoder setBuffer:state.femArmijoSurfaceSortKeysB
                                 offset:0u atIndex:2u];
                    [encoder setBuffer:state.femArmijoSurfaceSortIndicesB
                                 offset:0u atIndex:3u];
                    [encoder setBuffer:state.femArmijoDeformableCandidateCounts
