                                     offset:0u atIndex:18u];
                        [encoder setBuffer:state.femRegionalGraphFactors
                                     offset:0u atIndex:19u];
                        [encoder setBuffer:state.statuses
                                     offset:0u atIndex:20u];
                        [encoder setBytes:&graphRows length:sizeof(graphRows)
                                  atIndex:21u];
                        [encoder setBytes:&graphPatches
                            length:sizeof(graphPatches) atIndex:22u];
                        [encoder setBytes:&graphMatrixFloats
                            length:sizeof(graphMatrixFloats) atIndex:23u];
                        [encoder setBuffer:state.fgmresStates
                                     offset:0u atIndex:24u];
                        [encoder setBytes:&reuseCompletedGraphTail
                                   length:sizeof(reuseCompletedGraphTail)
                                  atIndex:25u];
                        [encoder setBuffer:state.femRegionalGraphFactorValid
                                     offset:0u atIndex:26u];
                    });
                    [encoder memoryBarrierWithScope:MTLBarrierScopeBuffers];
                    // Legacy is the default. Explicit conditioning-only opt-in
                    // is captured in the source-bound run environment.
                    const std::uint32_t parallelGraphPivotSearch =
                        state.femRegionalGraphParallelSearch;
                    dispatchGroups256("nm_fgmres_graph_factor_patches",
                        environments * graphPatches, [&] {
                        setDispatch();
                        [encoder setBuffer:state.femRegionalGraphPatches
                                     offset:0u atIndex:1u];
                        [encoder setBuffer:state.femRegionalGraphFactors
                                     offset:0u atIndex:2u];
                        [encoder setBuffer:state.femRegionalGraphPivots
                                     offset:0u atIndex:3u];
                        [encoder setBuffer:state.femRegionalGraphFactorValid
                                     offset:0u atIndex:4u];
                        [encoder setBuffer:state.statuses
                                     offset:0u atIndex:5u];
                        [encoder setBytes:&graphPatches
                            length:sizeof(graphPatches) atIndex:6u];
                        [encoder setBytes:&graphMatrixFloats
                            length:sizeof(graphMatrixFloats) atIndex:7u];
                        [encoder setBytes:&graphPivots
                            length:sizeof(graphPivots) atIndex:8u];
                        [encoder setBuffer:
                            state.femRegionalGraphOriginalMatrices
                                     offset:0u atIndex:9u];
                        [encoder setBuffer:state.fgmresStates
                                     offset:0u atIndex:10u];
                        [encoder setBytes:&reuseCompletedGraphTail
                                   length:sizeof(reuseCompletedGraphTail)
                                  atIndex:11u];
                        [encoder setBuffer:state.femRegionalGraphFactorValid
                                     offset:0u atIndex:12u];
                        [encoder setBytes:&parallelGraphPivotSearch
                                   length:sizeof(parallelGraphPivotSearch)
                                  atIndex:13u];
                    });
                    [encoder memoryBarrierWithScope:MTLBarrierScopeBuffers];
                }
            }
                // Capture the exact preconditioner generation immediately
                // after RAP factorization. The ordinary RuntimeStateSnapshot
                // is retrospective and these scratch buffers are reused by
                // later Newton iterations, so it cannot establish which AP or
                // factor belonged to a rejected Newton candidate.
                const char* regionalCapturePathText = std::getenv(
                    "NM_FEM_OPERATOR_FD_CAPTURE_PATH");
                if (femOperatorFDTraceEnabled &&
                    !femRegionalRAPTraceCaptured &&
                    femOperatorFDTraceRoot == request.controlStep &&
                    femOperatorFDTraceIteration == nonlinearIteration &&
                    state.femOperatorFDRichCaptureEnabled &&
                    regionalCapturePathText != nullptr &&
                    regionalCapturePathText[0] != '\0') {
                    femRegionalRAPTraceCaptured = true;
                    // The RAP capture runs after the selector-scoped build
                    // block. Read the immutable mode count again in this
                    // scope rather than referring to its block-local value.
                    const std::uint32_t captureRegionalModes =
                        state.femRegionalModeCount;
                    const std::uint64_t captureCap =
                        32ull * 1024ull * 1024ull;
                    const std::uint64_t envCount = environments;
                    const std::uint64_t nodeCount =
                        state.dispatch.femNodeCount;
                    const std::uint64_t tetCount =
                        state.dispatch.tetrahedronCount;
                    const std::uint64_t modeCount = captureRegionalModes;
                    std::uint64_t payloadBytes = 0u;
                    bool layoutValid = state.femRegionalLinearizationNodes != nil &&
                        state.femRegionalLinearizationMaterialState != nil &&
                        state.femRegionalLinearizationSchedulerExponent != nil &&
                        state.femRegionalLinearizationLocalFHigh != nil &&
                        state.femRegionalLinearizationLocalFLow != nil &&
                        state.femRegionalBasis != nil &&
                        state.femRegionalEffectiveBasis != nil &&
                        state.femRegionalAP != nil &&
                        state.femRegionalCoarseMatrix != nil &&
                        state.femRegionalCoarsePivots != nil &&
                        state.femRegionalCoarseValid != nil;
                    std::vector<RegionalRAPCaptureArray> captureArrays;
                    id<MTLBuffer> captureSources[32] = {};
                    const auto appendCaptureArray = [&](
                        const char* name,
                        const char* dtype,
                        std::initializer_list<std::uint64_t> shape,
                        const std::uint64_t elementBytes,
                        id<MTLBuffer> source,
                        const std::uint64_t sourceOffset = 0u) {
                        if (!layoutValid || source == nil || elementBytes == 0u ||
                            captureArrays.size() >= 32u) {
                            layoutValid = false;
                            return;
                        }
                        std::uint64_t count = 1u;
                        for (const std::uint64_t extent : shape) {
                            if (extent == 0u ||
                                count > std::numeric_limits<std::uint64_t>::max() /
                                    extent) {
                                layoutValid = false;
                                return;
                            }
                            count *= extent;
                        }
                        if (count > std::numeric_limits<std::uint64_t>::max() /
                                elementBytes) {
                            layoutValid = false;
                            return;
                        }
                        const std::uint64_t byteCount = count * elementBytes;
                        if (sourceOffset > source.length ||
                            byteCount > source.length - sourceOffset ||
                            payloadBytes > std::numeric_limits<std::uint64_t>::max() -
                                byteCount) {
                            layoutValid = false;
                            return;
                        }
                        RegionalRAPCaptureArray array;
                        array.name = name;
                        array.dtype = dtype;
                        array.shape.assign(shape.begin(), shape.end());
                        array.offset = payloadBytes;
                        array.byteCount = byteCount;
                        array.elementBytes = elementBytes;
                        array.sourceSlot = static_cast<std::uint32_t>(
                            captureArrays.size());
                        array.sourceOffset = sourceOffset;
                        captureSources[array.sourceSlot] = source;
                        captureArrays.push_back(std::move(array));
                        payloadBytes += byteCount;
                    };
                    if (layoutValid) {
                        appendCaptureArray("P", "<f4x4",
                            {modeCount, nodeCount}, sizeof(nm_float4),
                            state.femRegionalBasis);
                        appendCaptureArray("effective_P", "<f4x4",
                            {envCount, modeCount, nodeCount},
                            sizeof(nm_float4), state.femRegionalEffectiveBasis);
                        appendCaptureArray("AP", "<f4x4",
                            {envCount, modeCount, nodeCount},
                            sizeof(nm_float4), state.femRegionalAP);
                        appendCaptureArray("pivoted_RAP", "<f4",
                            {envCount, modeCount, modeCount}, sizeof(float),
                            state.femRegionalCoarseMatrix);
                        appendCaptureArray("pivots", "<u4",
                            {envCount, modeCount}, sizeof(std::uint32_t),
                            state.femRegionalCoarsePivots);
                        appendCaptureArray("factor_valid", "<u4",
                            {envCount}, sizeof(std::uint32_t),
                            state.femRegionalCoarseValid);
                        if (state.femRegionalNodeBlockInverse != nil) {
                            appendCaptureArray("node_block_inverse", "<f4x4",
                                {envCount, nodeCount, 3u}, sizeof(nm_float4),
                                state.femRegionalNodeBlockInverse);
                        }
                        appendCaptureArray("candidate_nodes",
                            "struct:NMFEMNodeStateGPU", {envCount, nodeCount},
                            sizeof(NMFEMNodeStateGPU),
                            state.femRegionalLinearizationNodes);
                        appendCaptureArray("material_history", "<f4",
                            {envCount, tetCount,
                             state.dispatch.materialStateStride}, sizeof(float),
                            state.femRegionalLinearizationMaterialState);
                        appendCaptureArray("scheduler_exponents", "<u4",
                            {envCount, tetCount}, sizeof(std::uint32_t),
                            state.femRegionalLinearizationSchedulerExponent);
                        appendCaptureArray("deformation_high", "<f4x4",
                            {envCount, tetCount, 3u}, sizeof(nm_float4),
                            state.femRegionalLinearizationLocalFHigh);
                        appendCaptureArray("deformation_low", "<f4x4",
                            {envCount, tetCount, 3u}, sizeof(nm_float4),
                            state.femRegionalLinearizationLocalFLow);
                        if (state.femAlgorithmicTangentCache != nil &&
                            state.femAlgorithmicTangentCacheValid != nil) {
                            appendCaptureArray("algorithmic_tangent_cache",
                                "<f4", {envCount, tetCount, 81u},
                                sizeof(float),
                                state.femAlgorithmicTangentCache);
                            appendCaptureArray("algorithmic_tangent_cache_valid",
                                "<u4", {envCount, tetCount},
                                sizeof(std::uint32_t),
                                state.femAlgorithmicTangentCacheValid);
                        }
                        appendCaptureArray("production_status",
                            "struct:NMMatterStatusGPU", {envCount},
                            sizeof(NMMatterStatusGPU), state.statuses);
                        if (state.mixedSolverValue.executionBudgets.z == 5u) {
                            // The graph factors are environment-major and can
                            // be large. Capture the first environment only,
                            // explicitly identified in the manifest, so the
                            // existing aggregate readback cap remains in force.
                            constexpr std::uint64_t graphEnvironment = 0u;
                            const std::uint64_t graphMatrixOffset =
                                graphEnvironment *
                                state.femRegionalGraphMatrixFloatCount *
                                sizeof(float);
                            const std::uint64_t graphPivotOffset =
                                graphEnvironment *
                                state.femRegionalGraphPivotCount *
                                sizeof(std::uint32_t);
                            const std::uint64_t graphValidOffset =
                                graphEnvironment *
                                state.femRegionalGraphPatchCount *
                                sizeof(std::uint32_t);
                            layoutValid = state.femRegionalGraphPatches != nil &&
                                state.femRegionalGraphPatchNodes != nil &&
                                state.femRegionalGraphRows != nil &&
                                state.femRegionalGraphNodePatchOffsets != nil &&
                                state.femRegionalGraphNodePatchValues != nil &&
                                state.femRegionalGraphNodeCoverage != nil &&
                                state.femRegionalGraphFactors != nil &&
                                state.femRegionalGraphPivots != nil &&
                                state.femRegionalGraphFactorValid != nil;
                            if (layoutValid) {
                                appendCaptureArray("graph_patches", "<u4x4",
                                    {state.femRegionalGraphPatchCount},
                                    sizeof(std::array<std::uint32_t, 4>),
                                    state.femRegionalGraphPatches);
                                appendCaptureArray("graph_patch_nodes", "<u4",
                                    {state.femRegionalGraphPatchNodeCount},
                                    sizeof(std::uint32_t),
                                    state.femRegionalGraphPatchNodes);
                                appendCaptureArray("graph_rows", "<u4x4",
                                    {state.femRegionalGraphDofCount},
                                    sizeof(std::array<std::uint32_t, 4>),
                                    state.femRegionalGraphRows);
                                appendCaptureArray("graph_node_patch_offsets", "<u4",
                                    {nodeCount + 1u}, sizeof(std::uint32_t),
                                    state.femRegionalGraphNodePatchOffsets);
                                appendCaptureArray("graph_node_patch_values", "<u4",
                                    {state.femRegionalGraphPatchNodeCount},
                                    sizeof(std::uint32_t),
                                    state.femRegionalGraphNodePatchValues);
                                appendCaptureArray("graph_node_coverage", "<u4",
                                    {nodeCount}, sizeof(std::uint32_t),
                                    state.femRegionalGraphNodeCoverage);
                                appendCaptureArray("graph_patch_matrices_lu", "<f4",
                                    {state.femRegionalGraphMatrixFloatCount},
                                    sizeof(float), state.femRegionalGraphFactors,
                                    graphMatrixOffset);
                                appendCaptureArray("graph_pivots", "<u4",
                                    {state.femRegionalGraphPivotCount},
                                    sizeof(std::uint32_t),
                                    state.femRegionalGraphPivots,
                                    graphPivotOffset);
                                appendCaptureArray("graph_factor_valid", "<u4",
                                    {state.femRegionalGraphPatchCount},
                                    sizeof(std::uint32_t),
                                    state.femRegionalGraphFactorValid,
                                    graphValidOffset);
                            }
                        }
                    }

                    // The FD trace allocates its own shared readback later in
                    // this same command buffer. Bound both snapshots together
                    // so the selected diagnostics cannot exceed 32 MiB live
                    // readback storage, even when both captures are enabled.
                    std::uint64_t fdReadbackUpperBound = 0u;
                    if (state.femOperatorFDRichCaptureEnabled &&
                        !femRegionalRAPCaptureOnly) {
                        const std::uint64_t resultBytes = envCount *
                            10u * sizeof(nm_float4);
                        constexpr std::uint64_t integrityBytes =
                            sizeof(std::uint32_t);
                        const std::uint64_t richBytes =
                            state.femOperatorFDRichCapture == nil ? 0u :
                                state.femOperatorFDRichCapture.length;
                        const std::uint64_t richOffset =
                            ((resultBytes + integrityBytes +
                              sizeof(nm_float4) - 1u) /
                             sizeof(nm_float4)) * sizeof(nm_float4);
                        const std::uint64_t fdSnapshotBytes = richOffset +
                            richBytes;
                        if (fdSnapshotBytes > captureCap) {
                            layoutValid = false;
                        } else {
                            fdReadbackUpperBound = fdSnapshotBytes;
                        }
                    }
                    if (!layoutValid || payloadBytes == 0u ||
                        payloadBytes > captureCap ||
                        fdReadbackUpperBound > captureCap - payloadBytes) {
                        std::fprintf(stderr,
                            "fem_regional_rap_capture_skipped={\"schema\":1,\"root\":%u,\"iteration\":%u,\"reason\":\"invalid_layout_or_aggregate_32MiB_cap\",\"bytes\":%llu,\"other_readback_upper_bound\":%llu}\n",
                            femOperatorFDTraceRoot, femOperatorFDTraceIteration,
                            static_cast<unsigned long long>(payloadBytes),
                            static_cast<unsigned long long>(fdReadbackUpperBound));
                    } else {
                        id<MTLBuffer> snapshot = [state.device
                            newBufferWithLength:static_cast<NSUInteger>(payloadBytes)
                            options:MTLResourceStorageModeShared];
                        if (snapshot == nil ||
                            snapshot.length < payloadBytes ||
                            snapshot.length > captureCap) {
                            std::fprintf(stderr,
                                "fem_regional_rap_capture_skipped={\"schema\":1,\"root\":%u,\"iteration\":%u,\"reason\":\"bounded_snapshot_allocation_failed\",\"bytes\":%llu}\n",
                                femOperatorFDTraceRoot,
                                femOperatorFDTraceIteration,
                                static_cast<unsigned long long>(payloadBytes));
                        } else {
                            [encoder endEncoding];
                            encoder = nil;
                            id<MTLBlitCommandEncoder> copy =
                                [commandBuffer blitCommandEncoder];
                            if (copy == nil) {
                                std::fprintf(stderr,
                                    "fem_regional_rap_capture_skipped={\"schema\":1,\"root\":%u,\"iteration\":%u,\"reason\":\"blit_encoder_unavailable\"}\n",
                                    femOperatorFDTraceRoot,
                                    femOperatorFDTraceIteration);
                            } else {
                                for (const auto& array : captureArrays) {
                                    [copy copyFromBuffer:
                                        captureSources[array.sourceSlot]
                                        sourceOffset:static_cast<NSUInteger>(
                                            array.sourceOffset)
                                        toBuffer:snapshot
                                        destinationOffset:
                                            static_cast<NSUInteger>(array.offset)
                                        size:static_cast<NSUInteger>(array.byteCount)];
                                }
                                [copy endEncoding];
                                RegionalRAPCaptureMetadata metadata;
                                metadata.controlStep = request.controlStep;
                                metadata.solverIteration = nonlinearIteration;
                                metadata.physicsSubstep = request.physicsSubstep;
                                metadata.microtick = micro.microtick;
                                metadata.microtickCount = micro.microtickCount;
                                metadata.microGeneration = micro.reserved;
                                metadata.linearizationGeneration =
                                    (static_cast<std::uint64_t>(micro.reserved) << 32u) |
                                    static_cast<std::uint64_t>(nonlinearIteration);
                                metadata.environmentCount = state.dispatch.environmentCount;
                                metadata.nodeCount = state.dispatch.femNodeCount;
                                metadata.tetrahedronCount =
                                    static_cast<std::uint32_t>(
                                        state.dispatch.tetrahedronCount);
                                metadata.modeCount = captureRegionalModes;
                                metadata.preconditionerSelector =
                                    state.mixedSolverValue.executionBudgets.z;
                                if (metadata.preconditionerSelector == 5u) {
                                    metadata.graphEnvironment = 0u;
                                    metadata.graphPatchCount =
                                        state.femRegionalGraphPatchCount;
                                    metadata.graphPatchNodeCount =
                                        state.femRegionalGraphPatchNodeCount;
                                    metadata.graphDofCount =
                                        state.femRegionalGraphDofCount;
                                    metadata.graphMatrixFloatCount =
                                        state.femRegionalGraphMatrixFloatCount;
                                    metadata.graphPivotCount =
                                        state.femRegionalGraphPivotCount;
                                    metadata.graphLayoutChecksum =
                                        state.femRegionalGraphLayoutChecksum;
                                    metadata.graphSourceTopologySHA256 =
                                        state.femRegionalGraphSourceTopologySHA256;
                                    metadata.graphSourceFreeMaskSHA256 =
                                        state.femRegionalGraphSourceFreeMaskSHA256;
                                    metadata.graphPotentialMaskSHA256 =
                                        state.femRegionalGraphPotentialMaskSHA256;
                                }
                                metadata.materialStateStride =
                                    state.dispatch.materialStateStride;
                                metadata.tangentCacheUsed =
                                    state.mixedSolverValue.executionBudgets.w == 1u
                                        ? 1u : 0u;
                                metadata.worldFingerprint = state.worldFingerprint;
                                metadata.executionFingerprint =
                                    state.executionFingerprint;
                                metadata.deviceRegistryID =
                                    static_cast<std::uint64_t>(state.device.registryID);
                                metadata.timestepSeconds = micro.time.x;
                                metadata.deviceName = nsString(state.device.name);
                                const auto capturedArrays = captureArrays;
                                const auto capturedMetadata = metadata;
                                const std::string capturedBasePath =
                                    regionalCapturePathText;
                                const std::uint64_t capturedPayloadBytes =
                                    payloadBytes;
                                [commandBuffer addCompletedHandler:
                                    ^(id<MTLCommandBuffer> completed) {
                                    if (completed.status !=
                                            MTLCommandBufferStatusCompleted) {
                                        std::fprintf(stderr,
                                            "fem_regional_rap_capture_error={\"schema\":1,\"root\":%u,\"iteration\":%u,\"reason\":\"command_buffer_failed\",\"command_buffer_status\":%lu}\n",
                                            capturedMetadata.controlStep,
                                            capturedMetadata.solverIteration,
                                            static_cast<unsigned long>(
                                                completed.status));
                                        return;
                                    }
                                    try {
                                        writeRegionalRAPCapture(snapshot.contents,
                                            capturedPayloadBytes, capturedArrays,
                                            capturedMetadata, capturedBasePath);
                                    } catch (...) {
                                        std::fprintf(stderr,
                                            "fem_regional_rap_capture_error={\"schema\":1,\"root\":%u,\"iteration\":%u,\"reason\":\"capture_writer_exception\"}\n",
                                            capturedMetadata.controlStep,
                                            capturedMetadata.solverIteration);
                                    }
                                }];
                                encoder = [commandBuffer computeCommandEncoder];
                                if (encoder == nil) {
                                    diagnostics.message =
                                        "failed to resume Matter after selected RAP readback";
                                    return diagnostics;
                                }
                                [encoder setLabel:
                                    @"Numi Matter selected regional RAP capture continuation"];
                            }
                            if (encoder == nil) {
                                encoder = [commandBuffer computeCommandEncoder];
                                if (encoder == nil) {
                                    diagnostics.message =
                                        "failed to resume Matter after RAP capture skip";
                                    return diagnostics;
                                }
                                [encoder setLabel:
                                    @"Numi Matter regional RAP capture skip continuation"];
                            }
                        }
                    }
                }
            for (std::uint32_t restartCycle = 0u;
                 restartCycle < restartCycleCount;
                 ++restartCycle) {
            const std::uint32_t iterationOffset = restartCycle * restart;
            const std::uint32_t columnsThisCycle = std::min(
                restart, linearIterationBudget - iterationOffset);
            dispatchGroups32("nm_fgmres_begin", environments, [&] {
                setDispatch();
                [encoder setBuffer:state.mixedSolver offset:0u atIndex:1u];
                [encoder setBuffer:state.objects offset:0u atIndex:2u];
                [encoder setBuffer:state.femResidual offset:0u atIndex:3u];
                [encoder setBuffer:state.fgmresBasis offset:0u atIndex:4u];
                [encoder setBuffer:state.fgmresHessenberg offset:0u atIndex:5u];
                [encoder setBuffer:state.fgmresRotations offset:0u atIndex:6u];
                [encoder setBuffer:state.fgmresLeastSquares offset:0u atIndex:7u];
                [encoder setBuffer:state.fgmresStates offset:0u atIndex:8u];
                [encoder setBuffer:state.statuses offset:0u atIndex:9u];
                [encoder setBytes:&micro length:sizeof(micro) atIndex:10u];
                [encoder setBuffer:state.schedulers offset:0u atIndex:11u];
                [encoder setBuffer:state.adaptive offset:0u atIndex:12u];
                bindPrimalContactArguments(13u);
                [encoder setBytes:&restartCycle
                           length:sizeof(restartCycle) atIndex:14u];
                [encoder setBytes:&linearForcing
                           length:sizeof(linearForcing) atIndex:15u];
                [encoder setBytes:&nonlinearIteration
                           length:sizeof(nonlinearIteration) atIndex:16u];
                [encoder setBuffer:state.femCandidate
                             offset:0u atIndex:17u];
                [encoder setBuffer:state.coupledGeneralizedCandidate
                             offset:0u atIndex:18u];
                [encoder setBuffer:state.humanSupportHistoriesCandidate
                             offset:0u atIndex:19u];
                [encoder setBytes:&state.humanSupportDispatch
                           length:sizeof(state.humanSupportDispatch) atIndex:20u];
                [encoder setBuffer:state.humanSupportContacts
                             offset:0u atIndex:21u];
            });
            if (state.mixedSolverValue.executionBudgets.z == 0u) {
                dispatchThreads(
                    "nm_fgmres_build_preconditioner", femNodeTotal, [&] {
                        setDispatch();
                        [encoder setBuffer:state.mixedSolver offset:0u atIndex:1u];
                        [encoder setBuffer:state.objects offset:0u atIndex:2u];
                        [encoder setBuffer:state.femCandidate offset:0u atIndex:3u];
                        [encoder setBuffer:state.femTetrahedraCandidate
                                   offset:0u atIndex:4u];
                        [encoder setBuffer:state.femNodeIncidence
                                   offset:0u atIndex:5u];
                        [encoder setBuffer:state.femNodeRanges offset:0u atIndex:6u];
                        [encoder setBuffer:state.schedulers offset:0u atIndex:7u];
                        [encoder setBuffer:state.mixedMaterials offset:0u atIndex:8u];
                        [encoder setBuffer:state.femPreconditioned
                                   offset:0u atIndex:9u];
                        bindPrimalContactArguments(10u);
                    });
            }
            for (std::uint32_t column = 0u; column < columnsThisCycle; ++column) {
                const NSUInteger columnOffset = vectorBytes * column;
                dispatchThreads("nm_fgmres_precondition", femNodeTotal, [&] {
                    setDispatch();
                    [encoder setBuffer:state.femNodeRanges offset:0u atIndex:1u];
                    [encoder setBuffer:state.femPreconditioned offset:0u atIndex:2u];
                    [encoder setBuffer:state.fgmresBasis offset:columnOffset atIndex:3u];
                    [encoder setBuffer:state.fgmresPreconditionedBasis offset:columnOffset atIndex:4u];
                    [encoder setBuffer:state.fgmresStates offset:0u atIndex:5u];
                    [encoder setBuffer:state.mixedSolver offset:0u atIndex:6u];
                    [encoder setBuffer:state.objects offset:0u atIndex:7u];
                });
                dispatchThreads("nm_fgmres_precondition_patches", femNodeTotal, [&] {
                    setDispatch();
                    [encoder setBuffer:state.femTetrahedraCandidate
                                 offset:0u atIndex:1u];
                    [encoder setBuffer:state.femNodeIncidence
                                 offset:0u atIndex:2u];
                    [encoder setBuffer:state.femNodeRanges
                                 offset:0u atIndex:3u];
                    [encoder setBuffer:state.fgmresBasis
                                 offset:columnOffset atIndex:4u];
                    [encoder setBuffer:state.femPreconditioned
                                 offset:0u atIndex:5u];
                    [encoder setBuffer:state.fgmresPreconditionedBasis
                                 offset:columnOffset atIndex:6u];
                    [encoder setBuffer:state.fgmresStates
                                 offset:0u atIndex:7u];
                });
                dispatchGroups32("nm_fgmres_precondition_coarse", objectTotal, [&] {
                    setDispatch();
                    [encoder setBuffer:state.objects offset:0u atIndex:1u];
                    [encoder setBuffer:state.fgmresBasis
                                 offset:columnOffset atIndex:2u];
                    [encoder setBuffer:state.femPreconditioned
                                 offset:0u atIndex:3u];
                    [encoder setBuffer:state.fgmresPreconditionedBasis
                                 offset:columnOffset atIndex:4u];
                    [encoder setBuffer:state.fgmresStates
                                 offset:0u atIndex:5u];
                });
                dispatchThreads("nm_fgmres_field_smoother_initialize", femNodeTotal, [&] {
                    setDispatch();
                    [encoder setBuffer:state.femNodeRanges offset:0u atIndex:1u];
                    [encoder setBuffer:state.fgmresBasis offset:columnOffset atIndex:2u];
                    [encoder setBuffer:state.mixedFieldInverseDiagonal offset:0u atIndex:3u];
                    [encoder setBuffer:state.mixedFieldSolution offset:0u atIndex:4u];
                    [encoder setBuffer:state.mixedFieldResidual offset:0u atIndex:5u];
                    [encoder setBuffer:state.mixedFieldPreconditioned offset:0u atIndex:6u];
                    [encoder setBuffer:state.mixedFieldDirection offset:0u atIndex:7u];
                    [encoder setBuffer:state.fgmresStates offset:0u atIndex:8u];
                });
                // Apply a fixed matrix-free polynomial smoother to the four
                // packed transport blocks. The former nested field solve launched up
                // to seven kernels per inner iteration for every Arnoldi
                // column. This bounded right preconditioner keeps the outer
                // FGMRES authoritative while removing reductions, scalar
