                                [encoder setBytes:&coupledArticulatedNv
                                    length:sizeof(coupledArticulatedNv)
                                    atIndex:1u];
                                [encoder setBytes:
                                    &request.rigid.externalWrenchCount
                                    length:sizeof(request.rigid.externalWrenchCount)
                                    atIndex:2u];
                                [encoder setBytes:
                                    &request.rigid.externalWrenchStride
