RuntimeDiagnostics Runtime::setSutureProxyEdges(
    const std::span<const std::uint32_t> firstRodEdges,
    const std::uint32_t rodNodeCount
) {
    RuntimeDiagnostics diagnostics;
    if (state_ == nullptr) {
        diagnostics.message = "Matter runtime is not initialized";
        return diagnostics;
    }
    State& state = *state_;
    const auto ownership = state.commandOwnership;
    std::unique_lock lock(ownership->mutex);
    if (ownership->activeCommandBuffer != nullptr ||
        ownership->preDynamicsOpen || ownership->preparedStateOpen ||
        ownership->applyEncoded || ownership->restoreRequired) {
        diagnostics.message =
            "suture proxy bindings require a completed command boundary";
        return diagnostics;
    }
    if (state.sutureProxyIndices.empty() ||
        firstRodEdges.size() != state.sutureProxyIndices.size() ||
        rodNodeCount < 2u) {
        diagnostics.message =
            "suture proxy binding dimensions do not match the cooked window";
        return diagnostics;
    }

    std::vector<std::uint32_t> sortedEdges(
        firstRodEdges.begin(), firstRodEdges.end());
    std::ranges::sort(sortedEdges);
    for (std::size_t slot = 0u; slot < sortedEdges.size(); ++slot) {
        if (sortedEdges[slot] >= rodNodeCount - 1u ||
            (slot != 0u && sortedEdges[slot] == sortedEdges[slot - 1u])) {
            diagnostics.message =
                "suture proxy edges must form one unique in-range set";
            return diagnostics;
        }
    }

    std::vector<NMRigidProxyGPU> updated = state.rigidProxyLayout;
    std::vector<std::uint32_t> remapped(
        state.dispatch.rigidProxyCount, 0u);
    std::uint32_t changedCount = 0u;
    std::uint32_t requiredRodNodes = state.requiredRodNodeCount;
    for (std::size_t slot = 0u; slot < firstRodEdges.size(); ++slot) {
        const std::uint32_t proxyIndex = state.sutureProxyIndices[slot];
        const std::uint32_t edge = firstRodEdges[slot];
        requiredRodNodes = std::max(requiredRodNodes, edge + 2u);
        if (edge == state.sutureProxyEdges[slot]) continue;
        ++changedCount;
        remapped[proxyIndex] = 1u;
        updated[proxyIndex].bodyIndex = edge;
        updated[proxyIndex].sceneBodyIndex = edge + 1u;
    }
    if (changedCount > 1u) {
        diagnostics.message =
            "suture proxy transition must retain stable overlapping slots";
        return diagnostics;
    }
    if (changedCount == 0u) {
        diagnostics.encoded = true;
        diagnostics.residentBytes = state.residentBytes;
        diagnostics.device = nsString(state.device.name);
        diagnostics.message = "suture proxy bindings already match";
        return diagnostics;
    }

    @autoreleasepool {
        id<MTLBuffer> proxyStaging = [state.device
            newBufferWithBytes:updated.data()
                        length:updated.size() * sizeof(NMRigidProxyGPU)
                       options:MTLResourceStorageModeShared];
        id<MTLBuffer> remappedStaging = [state.device
            newBufferWithBytes:remapped.data()
                        length:remapped.size() * sizeof(std::uint32_t)
                       options:MTLResourceStorageModeShared];
        id<MTLCommandBuffer> commandBuffer = [state.queue commandBuffer];
        if (proxyStaging == nil || remappedStaging == nil ||
            commandBuffer == nil) {
            diagnostics.message =
                "failed to allocate suture proxy maintenance resources";
            return diagnostics;
        }
        id<MTLBlitCommandEncoder> blit = [commandBuffer blitCommandEncoder];
        if (blit == nil) {
            diagnostics.message =
                "failed to encode suture proxy binding upload";
            return diagnostics;
        }
        [blit copyFromBuffer:proxyStaging sourceOffset:0u
                   toBuffer:state.rigidProxies destinationOffset:0u
                       size:updated.size() * sizeof(NMRigidProxyGPU)];
        [blit endEncoding];

        id<MTLComputeCommandEncoder> encoder =
            [commandBuffer computeCommandEncoder];
        id<MTLComputePipelineState> pipeline = state.pipeline(
            "nm_contact_clear_remapped_suture_histories");
        if (encoder == nil || pipeline == nil) {
            diagnostics.message =
                "failed to encode suture proxy history reset";
            return diagnostics;
        }
        [encoder setComputePipelineState:pipeline];
        [encoder setBuffer:state.dispatchBuffer offset:0u atIndex:0u];
        [encoder setBuffer:state.contactPairs offset:0u atIndex:1u];
        [encoder setBuffer:remappedStaging offset:0u atIndex:2u];
        [encoder setBuffer:state.contactHistoriesAccepted offset:0u atIndex:3u];
        [encoder setBuffer:state.contactHistoriesCandidate offset:0u atIndex:4u];
        [encoder setBuffer:state.contactHistoriesCheckpoint offset:0u atIndex:5u];
        const NSUInteger total =
            static_cast<NSUInteger>(state.dispatch.environmentCount) *
            state.dispatch.contactPairCount;
        const NSUInteger width = std::min<NSUInteger>(
            256u, pipeline.maxTotalThreadsPerThreadgroup);
        if (total != 0u) {
            [encoder dispatchThreads:MTLSizeMake(total, 1u, 1u)
                threadsPerThreadgroup:MTLSizeMake(width, 1u, 1u)];
        }
        [encoder endEncoding];
        [commandBuffer commit];
        [commandBuffer waitUntilCompleted];
        if (commandBuffer.status != MTLCommandBufferStatusCompleted) {
            diagnostics.message =
                "suture proxy maintenance command failed: " +
                errorString(commandBuffer.error);
            return diagnostics;
        }
    }

    state.rigidProxyLayout = std::move(updated);
    state.sutureProxyEdges.assign(
        firstRodEdges.begin(), firstRodEdges.end());
    state.requiredRodNodeCount = requiredRodNodes;
    ++state.sutureProxyBindingRevision;
    diagnostics.encoded = true;
    diagnostics.residentBytes = state.residentBytes;
    diagnostics.device = nsString(state.device.name);
    diagnostics.threadDispatchCount = 1u;
    diagnostics.requestedThreadCount =
        static_cast<std::uint64_t>(state.dispatch.environmentCount) *
        state.dispatch.contactPairCount;
    diagnostics.message = "suture proxy bindings advanced with stable ownership";
    return diagnostics;
}

bool Runtime::setCoupledTimestepMultiplier(
    const std::uint32_t multiplier
) noexcept {
    if (state_ == nullptr || multiplier == 0u ||
        (multiplier & (multiplier - 1u)) != 0u ||
        multiplier > (1u << NM_MAX_RATE_EXPONENT) ||
        !state_->requiresRodNodes ||
        state_->dispatch.maximumRateExponent != 0u) {
        return false;
    }
    try {
        const auto ownership = state_->commandOwnership;
        const std::lock_guard lock(ownership->mutex);
        if (ownership->activeCommandBuffer != nullptr ||
            ownership->preDynamicsOpen || ownership->preparedStateOpen ||
            ownership->applyEncoded || ownership->restoreRequired) {
            return false;
        }
        const float activeTimestep =
            state_->dispatch.gravityAndTimestep.w *
            static_cast<float>(multiplier);
        if (!std::isfinite(activeTimestep) || !(activeTimestep > 0.0f)) {
            return false;
        }
        state_->coupledTimestepMultiplier.store(
            multiplier,
            std::memory_order_release
        );
        state_->coupledTimestepDivisor.store(
            1u,
            std::memory_order_release
        );
        return true;
    } catch (...) {
        return false;
    }
}

std::uint32_t Runtime::coupledTimestepMultiplier() const noexcept {
    return state_
        ? state_->coupledTimestepMultiplier.load(std::memory_order_acquire)
        : 0u;
}

bool Runtime::setCoupledTimestepDivisor(
    const std::uint32_t divisor
) noexcept {
    if (state_ == nullptr || divisor == 0u ||
        (divisor & (divisor - 1u)) != 0u ||
        divisor > (1u << NM_MAX_RATE_EXPONENT) ||
        !state_->requiresRodNodes ||
        state_->dispatch.maximumRateExponent != 0u) {
        return false;
    }
    try {
        const auto ownership = state_->commandOwnership;
        const std::lock_guard lock(ownership->mutex);
        if (ownership->activeCommandBuffer != nullptr ||
            ownership->preDynamicsOpen || ownership->preparedStateOpen ||
            ownership->applyEncoded || ownership->restoreRequired) {
            return false;
        }
        const float activeTimestep =
            state_->dispatch.gravityAndTimestep.w /
            static_cast<float>(divisor);
        if (!std::isfinite(activeTimestep) || !(activeTimestep > 0.0f)) {
            return false;
        }
        state_->coupledTimestepMultiplier.store(
            1u,
            std::memory_order_release
        );
        state_->coupledTimestepDivisor.store(
            divisor,
            std::memory_order_release
        );
        return true;
    } catch (...) {
        return false;
    }
}

std::uint32_t Runtime::coupledTimestepDivisor() const noexcept {
    return state_
        ? state_->coupledTimestepDivisor.load(std::memory_order_acquire)
        : 0u;
}

float Runtime::timestepSeconds() const noexcept {
    return state_
        ? state_->dispatch.gravityAndTimestep.w *
            static_cast<float>(state_->coupledTimestepMultiplier.load(
                std::memory_order_acquire
            )) /
            static_cast<float>(state_->coupledTimestepDivisor.load(
                std::memory_order_acquire
            ))
        : 0.0f;
}

bool Runtime::setFGMRESIterationBudget(
    const std::uint32_t iterations
) noexcept {
    if (state_ == nullptr || iterations == 0u) {
        return false;
    }
    try {
        const std::uint32_t restart = std::min(
            state_->mixedSolverValue.nonlinearIterations.y,
            static_cast<std::uint32_t>(NM_MIXED_FGMRES_RESTART)
        );
        if (restart == 0u || iterations < restart ||
            iterations > NM_MIXED_FGMRES_MAX_ITERATIONS ||
            iterations >
                std::numeric_limits<std::uint32_t>::max() - restart + 1u) {
            return false;
        }
        const auto ownership = state_->commandOwnership;
        const std::lock_guard lock(ownership->mutex);
        if (ownership->activeCommandBuffer != nullptr ||
            ownership->preDynamicsOpen || ownership->preparedStateOpen ||
            ownership->applyEncoded || ownership->restoreRequired) {
            return false;
        }
        const std::uint32_t cooked = std::max(
            restart,
            state_->mixedSolverValue.nonlinearIterations.z
        );
        state_->fgmresIterationBudgetOverride.store(
            iterations == cooked ? 0u : iterations,
            std::memory_order_release
        );
        return true;
    } catch (...) {
        return false;
    }
}

std::uint32_t Runtime::fgmresIterationBudget() const noexcept {
    if (state_ == nullptr) {
        return 0u;
    }
    const std::uint32_t restart = std::min(
        state_->mixedSolverValue.nonlinearIterations.y,
        static_cast<std::uint32_t>(NM_MIXED_FGMRES_RESTART)
    );
    const std::uint32_t budgetOverride =
        state_->fgmresIterationBudgetOverride.load(
            std::memory_order_acquire
        );
    return std::max(
        restart,
        budgetOverride == 0u
            ? state_->mixedSolverValue.nonlinearIterations.z
            : budgetOverride
    );
}

bool Runtime::setNewtonIterationBudget(
    const std::uint32_t iterations
) noexcept {
    if (state_ == nullptr || iterations == 0u) {
        return false;
    }
    try {
        const auto ownership = state_->commandOwnership;
        const std::lock_guard lock(ownership->mutex);
        if (ownership->activeCommandBuffer != nullptr ||
            ownership->preDynamicsOpen || ownership->preparedStateOpen ||
            ownership->applyEncoded || ownership->restoreRequired) {
            return false;
        }
        const std::uint32_t cooked =
            state_->mixedSolverValue.nonlinearIterations.x;
        state_->newtonIterationBudgetOverride.store(
            iterations == cooked ? 0u : iterations,
            std::memory_order_release
        );
        return true;
    } catch (...) {
        return false;
    }
}

std::uint32_t Runtime::newtonIterationBudget() const noexcept {
    if (state_ == nullptr) {
        return 0u;
    }
    const std::uint32_t budgetOverride =
        state_->newtonIterationBudgetOverride.load(
            std::memory_order_acquire
        );
    return budgetOverride == 0u
        ? state_->mixedSolverValue.nonlinearIterations.x
        : budgetOverride;
}

RuntimeDiagnostics Runtime::restore(const RuntimeStateSnapshot& snapshot) {
    RuntimeDiagnostics diagnostics;
    if (state_ == nullptr) {
        diagnostics.message = "Matter runtime is not initialized";
        return diagnostics;
    }
    State& state = *state_;
    const auto ownership = state.commandOwnership;
    std::unique_lock lock(ownership->mutex);
    if (ownership->activeCommandBuffer != nullptr ||
        ownership->preDynamicsOpen || ownership->preparedStateOpen ||
        ownership->applyEncoded || ownership->restoreRequired) {
        diagnostics.message =
            "Matter snapshot restore requires a completed command boundary";
        return diagnostics;
    }
    {
        const std::lock_guard growthLock(state.growthOwnership->mutex);
        if (state.growthOwnership->pending.required) {
            diagnostics.message =
                "Matter snapshot restore cannot bypass pending topology growth";
            return diagnostics;
        }
    }
    if (!snapshot.available ||
        snapshot.sourcePhysicsFingerprint != state.sourcePhysicsFingerprint ||
        snapshot.deviceProgramFingerprint != state.executionFingerprint ||
        snapshot.materialStateStride != state.dispatch.materialStateStride) {
        diagnostics.message =
            "Matter snapshot does not match the initialized device program";
        return diagnostics;
    }
    // Incidence is derived state rather than independent snapshot authority.
    // A topology mutation can advance the accepted generation without changing
    // the compiled arena sizes, so reconstruct that derived state below from
    // the exact accepted node/tetrahedron arrays instead of pairing restored
    // topology with the initialized world's stale incidence.
    std::uint32_t cookedAllocationGeneration = 0u;
    for (const NMContinuumObjectGPU& object : state.objectLayout) {
        if (object.representation != NM_REPRESENTATION_FEM) {
            continue;
        }
        cookedAllocationGeneration = std::max(
            cookedAllocationGeneration,
            object.topologyGeneration
        );
    }
    const bool rebuildTopologyIncidence =
        snapshot.allocationGeneration != cookedAllocationGeneration;
    const auto powerOfTwo = [](const std::uint32_t value) {
        return value != 0u && (value & (value - 1u)) == 0u;
    };
    if (!powerOfTwo(snapshot.coupledTimestepMultiplier) ||
        !powerOfTwo(snapshot.coupledTimestepDivisor) ||
        (snapshot.coupledTimestepMultiplier != 1u &&
         snapshot.coupledTimestepDivisor != 1u) ||
        snapshot.coupledTimestepMultiplier >
            (1u << NM_MAX_RATE_EXPONENT) ||
        snapshot.coupledTimestepDivisor >
            (1u << NM_MAX_RATE_EXPONENT) ||
        (!state.requiresRodNodes &&
         (snapshot.coupledTimestepMultiplier != 1u ||
          snapshot.coupledTimestepDivisor != 1u))) {
        diagnostics.message =
            "Matter snapshot has an invalid coupled timestep cadence";
        return diagnostics;
    }
    const std::uint32_t fgmresRestart = std::min(
        state.mixedSolverValue.nonlinearIterations.y,
        static_cast<std::uint32_t>(NM_MIXED_FGMRES_RESTART)
    );
    const std::uint32_t fgmresBudget =
        snapshot.fgmresIterationBudgetOverride == 0u
            ? state.mixedSolverValue.nonlinearIterations.z
            : snapshot.fgmresIterationBudgetOverride;
    if (fgmresRestart == 0u || fgmresBudget < fgmresRestart ||
        fgmresBudget > NM_MIXED_FGMRES_MAX_ITERATIONS ||
        fgmresBudget >
            std::numeric_limits<std::uint32_t>::max() - fgmresRestart + 1u) {
        diagnostics.message =
            "Matter snapshot has an invalid FGMRES iteration budget";
        return diagnostics;
    }
    const std::uint32_t newtonBudget =
        snapshot.newtonIterationBudgetOverride == 0u
            ? state.mixedSolverValue.nonlinearIterations.x
            : snapshot.newtonIterationBudgetOverride;
    if (newtonBudget == 0u) {
        diagnostics.message =
            "Matter snapshot has an invalid Newton iteration budget";
        return diagnostics;
    }

    bool dimensionsValid = true;
    const auto exactArena = [&](const auto& values,
                                id<MTLBuffer> target,
                                const char* label) {
        using Value = typename std::decay_t<decltype(values)>::value_type;
        const std::size_t bytes = values.size() * sizeof(Value);
        if (target == nil || bytes != target.length) {
            dimensionsValid = false;
            if (diagnostics.message.empty()) {
                diagnostics.message = std::string{"Matter snapshot "} +
                    label + " arena size changed";
            }
        }
    };
    const auto boundedArena = [&](const auto& values,
                                  id<MTLBuffer> target,
                                  const char* label) {
        using Value = typename std::decay_t<decltype(values)>::value_type;
        const std::size_t bytes = values.size() * sizeof(Value);
        if (target == nil || bytes > target.length) {
            dimensionsValid = false;
            if (diagnostics.message.empty()) {
                diagnostics.message = std::string{"Matter snapshot "} +
                    label + " logical size exceeds its arena";
            }
        }
    };
    exactArena(snapshot.particles, state.particleAccepted, "particle");
    exactArena(snapshot.femNodes, state.femAccepted, "FEM-node");
    exactArena(
        snapshot.particleMaterialState,
        state.particleMaterialStateAccepted,
        "particle-material-state"
    );
    exactArena(
        snapshot.femMaterialState,
        state.femMaterialStateAccepted,
        "FEM-material-state"
    );
    exactArena(snapshot.femFields, state.femFieldsAccepted, "FEM-field");
    const std::size_t vascularCount =
        static_cast<std::size_t>(state.dispatch.environmentCount) *
            state.vascularValue.layout.ranges.z;
    if (snapshot.vascularState.size() != vascularCount) {
        diagnostics.message = "Matter snapshot vascular logical size changed";
        return diagnostics;
    }
    const std::size_t vascularClockCount = vascularCount == 0u ? 0u :
        state.dispatch.environmentCount;
    if (snapshot.vascularClock.size() != vascularClockCount) {
        diagnostics.message = "Matter snapshot vascular clock logical size changed";
        return diagnostics;
    }
    for (std::size_t index = 0u; index < vascularCount; ++index) {
        const auto value = snapshot.vascularState[index];
        const auto row = index % state.vascularValue.layout.ranges.z;
        const auto offsets = state.vascularValue.layout.offsets;
        const float physical = value.x *
            state.vascularValue.unknowns[row].initialAndScaling.y;
        if (!std::isfinite(value.x) || !std::isfinite(physical) ||
            value.y != 0.0f || value.z != 0.0f || value.w != 0.0f ||
            (row < offsets.y && state.vascularValue.compartments[row].identity.z == 0u &&
                !(physical > 0.0f)) ||
            (row >= offsets.y && row < offsets.z &&
                state.vascularValue.connections[row - offsets.y].identity.w >= 1u &&
                state.vascularValue.connections[row - offsets.y].identity.w <= 3u && physical < 0.0f) ||
            (row >= offsets.z && row < state.vascularValue.layout.cavities.z && physical < 0.0f)) {
            diagnostics.message = "Matter snapshot vascular state is inadmissible";
            return diagnostics;
        }
        if (row >= state.vascularValue.layout.cavities.z) {
            const auto& cavity = state.vascularValue.cavities[
                row - state.vascularValue.layout.cavities.z];
            if (!std::isfinite(physical -
                    state.vascularValue.compartments[cavity.identity.y].compliance.w)) {
                diagnostics.message = "Matter snapshot transmural cavity pressure overflows";
                return diagnostics;
            }
        }
        if (row < offsets.y && state.vascularValue.compartments[row].identity.w == 3u) {
            const auto node = state.vascularValue.compartments[row];
            const float displacement = physical - node.compliance.x;
            const float angle = (0.5f * node.waveform.x) * (displacement / node.pressureParameters.x);
            const float tangent = std::tan(angle);
            const float pressure = node.compliance.w + node.compliance.y +
                (2.0f * node.pressureParameters.x / node.waveform.x / node.compliance.z) * tangent;
            const float derivative = (1.0f + tangent * tangent) / node.compliance.z;
            if (!(std::abs(displacement) < node.pressureParameters.x) || !(std::cos(angle) > 0.0f) ||
                !std::isfinite(pressure) || !std::isfinite(derivative) || !(derivative > 0.0f)) {
                diagnostics.message = "Matter snapshot vascular state is outside its pressure-law domain";
                return diagnostics;
            }
        }
    }
    exactArena(
        snapshot.solverCertificates,
        state.solverCertificates,
        "solver-certificate"
    );
    exactArena(snapshot.learnedWeights, state.learnedWeightsAccepted,
        "learned-weight");
    exactArena(snapshot.femTopologyNodes,
        state.femTopologyNodesAccepted, "topology-node");
    exactArena(snapshot.femTopologyTetrahedra,
        state.femTetrahedraAccepted, "topology-tetrahedron");
    exactArena(snapshot.cohesiveFaces,
        state.cohesiveFacesAccepted, "cohesive-face");
    exactArena(snapshot.punctureChannels,
        state.punctureChannelsAccepted, "puncture-channel");
    exactArena(snapshot.topologyStates,
        state.topologyStatesAccepted, "topology-state");
    exactArena(snapshot.adaptive, state.adaptive, "adaptive");
    exactArena(snapshot.schedulers, state.schedulers, "scheduler");
    exactArena(snapshot.reactions, state.frameReactions, "reaction");
    exactArena(snapshot.identification,
        state.identificationDistributions, "identification");
    exactArena(snapshot.environmentParameters,
        state.environmentParameters, "environment-parameter");
    boundedArena(snapshot.statuses, state.statuses, "status");
    boundedArena(snapshot.mpmActiveNodeIndices,
        state.mpmActiveNodeIndices, "MPM-active-index");
    boundedArena(snapshot.mpmNodeToActive,
        state.mpmNodeToActive, "MPM-node-map");
    boundedArena(snapshot.mpmActiveNodeCounts,
        state.mpmActiveNodeCounts, "MPM-active-count");
    boundedArena(snapshot.rigidGeneralizedCandidate,
        state.coupledGeneralizedCandidate, "rigid-generalized-candidate");
    boundedArena(snapshot.contactHistories,
        state.contactHistoriesAccepted, "contact-history");
    const std::size_t logicalHumanSupportCount =
        static_cast<std::size_t>(state.dispatch.environmentCount) *
        state.humanSupportDispatch.contactCount;
    if (snapshot.humanSupportHistories.size() != logicalHumanSupportCount) {
        diagnostics.message =
            "Matter snapshot Human-support-history logical size changed";
        return diagnostics;
    }
    if (state.humanSupportContactLayout.size() !=
            state.humanSupportDispatch.contactCount ||
        !validHumanSupportHistories(snapshot.humanSupportHistories,
            state.humanSupportContactLayout,
            state.humanSupportDispatch.groundNormal)) {
        diagnostics.message =
            "Matter snapshot Human-support-history is inadmissible";
        return diagnostics;
    }
    boundedArena(snapshot.humanSupportHistories,
        state.humanSupportHistoriesAccepted, "Human-support-history");
    boundedArena(snapshot.humanSupportConsequences,
        state.humanSupportConsequencesAccepted,
        "Human-support-consequence");
    boundedArena(snapshot.deformableContactHistories,
        state.deformableContactHistoriesAccepted,
        "deformable-contact-history");
    boundedArena(snapshot.rigidStates, state.rigidStates, "rigid-state");
    if (state.captureDiagnostics) {
        boundedArena(
            snapshot.contactSamples,
            state.contactSamples,
            "contact-sample"
        );
    } else if (!snapshot.contactSamples.empty()) {
        dimensionsValid = false;
        diagnostics.message =
            "Matter snapshot carries diagnostics for a non-diagnostic runtime";
    }
    if (!dimensionsValid) {
        return diagnostics;
    }

    // The displacement-mode tag is immutable layout metadata carried beside
    // the dynamic u state. Absolute positions are its FP32 materialization for
    // contact/output, while constitutive FEM kinematics consume u directly.
    for (std::size_t environment = 0u; environment < state.dispatch.environmentCount; ++environment) {
        const std::size_t nodeBase = environment * state.dispatch.femNodeCount;
        for (const auto& object : state.objectLayout) {
            if (object.representation != NM_REPRESENTATION_FEM) continue;
            const bool displacementMode =
                (object.flags & NM_OBJECT_FEM_REFERENCE_DISPLACEMENT_GRADIENT) != 0u;
            for (std::size_t local = 0u; local < object.stateCount; ++local) {
                const auto& node = snapshot.femNodes[nodeBase + object.stateOffset + local];
                const auto& u = node.referenceDisplacementAndMode;
                const bool finite = std::isfinite(u.x) && std::isfinite(u.y) &&
                    std::isfinite(u.z) && std::isfinite(u.w);
                const bool canonical = displacementMode
                    ? u.w == 1.0f &&
                        node.positionAndMass.x == node.restAndFixed.x + u.x &&
                        node.positionAndMass.y == node.restAndFixed.y + u.y &&
                        node.positionAndMass.z == node.restAndFixed.z + u.z
                    : u.x == 0.0f && u.y == 0.0f && u.z == 0.0f && u.w == 0.0f;
                if (!finite || !canonical) {
                    diagnostics.message =
                        "Matter snapshot has a noncanonical FEM reference displacement state";
                    return diagnostics;
                }
            }
        }
    }

    // This admission applies to ordinary snapshots as well as generation
    // changes. Incidence reconstruction is not permission to change frames.
    if (!state.femImmutableElementLayout.empty()) {
        const std::size_t perEnvironment = state.dispatch.tetrahedronCount;
        if (state.femImmutableElementLayout.size() != perEnvironment ||
            state.femImmutableNodeLayout.size() != state.dispatch.femNodeCount ||
            state.femImmutableCohesiveLayout.size() != state.dispatch.cohesiveFaceCount ||
            state.femImmutablePunctureLayout.size() != state.dispatch.punctureChannelCount ||
            state.femImmutableTopologyStateLayout.size() != state.dispatch.objectCount ||
            snapshot.allocationGeneration != cookedAllocationGeneration) {
            diagnostics.message = "Matter immutable FEM material-field layout changed";
            return diagnostics;
        }
        for (std::size_t environment = 0u; environment < state.dispatch.environmentCount; ++environment) {
            for (std::size_t object = 0u; object < state.objectLayout.size(); ++object) {
                if (snapshot.adaptive[environment * state.objectLayout.size() + object].activeRepresentation !=
                        state.objectLayout[object].representation) {
                    diagnostics.message = "Matter snapshot changed an immutable FEM material-field representation";
                    return diagnostics;
                }
            }
            // Dormant event capacity is allowed, but restore is not a mutation
            // transaction. Puncture geometry participates in contact admission;
            // topology roles also own the reported allocation generation.
            bool cohesiveLayoutChanged = false;
            for (std::size_t faceIndex = 0u;
                 faceIndex < state.dispatch.cohesiveFaceCount; ++faceIndex) {
                const NMCohesiveFaceGPU& value = snapshot.cohesiveFaces[
                    environment * state.dispatch.cohesiveFaceCount + faceIndex];
                const NMCohesiveFaceGPU& layout =
                    state.femImmutableCohesiveLayout[faceIndex];
                if ((layout.adjacency.w & NM_TOPOLOGY_PAIRED_COHESIVE) == 0u) {
                    cohesiveLayoutChanged = cohesiveLayoutChanged ||
                        std::memcmp(&value, &layout, sizeof(value)) != 0;
                    continue;
                }
                const bool mixedMode =
                    (layout.adjacency.w & NM_TOPOLOGY_COHESIVE_MIXED_MODE) != 0u;
                const bool valueDormant =
                    (value.adjacency.w & NM_TOPOLOGY_COHESIVE_DORMANT) != 0u;
                const bool authoredDormantMixedMortar = mixedMode &&
                    (layout.adjacency.w & NM_TOPOLOGY_PAIRED_COHESIVE) != 0u &&
                    (layout.adjacency.w & NM_TOPOLOGY_COHESIVE_MORTAR) != 0u &&
                    (layout.adjacency.w & NM_TOPOLOGY_COHESIVE_DORMANT) != 0u;
                const bool activatedMortarReference =
                    authoredDormantMixedMortar && !valueDormant;
                const bool geometryChanged =
                    std::memcmp(&value.geometry, &layout.geometry,
                        sizeof(value.geometry)) != 0;
                const bool activatedMortarFrameInvalid =
                    activatedMortarReference &&
                    !validLatchedMixedMortarFrame(value);
                const bool dormantLatchChanged = valueDormant &&
                    (std::memcmp(&value.activationSideAPosition,
                            &layout.activationSideAPosition,
                            sizeof(value.activationSideAPosition)) != 0 ||
                     std::memcmp(&value.activationTangent1,
                            &layout.activationTangent1,
                            sizeof(value.activationTangent1)) != 0);
                bool mixedHistoryInvalid = false;
                if (mixedMode) {
                    const auto workAt = [](const nm_float4& work,
                                           const std::size_t point) {
                        return point == 0u ? work.x :
                            point == 1u ? work.y : work.z;
                    };
                    float maximumDamage = 0.0f;
                    float summedWork = 0.0f;
                    for (std::size_t point = 0u; point < 3u; ++point) {
                        const nm_float4 history = value.mixedPointHistory[point];
                        const float work = workAt(value.mixedPointWork, point);
                        const bool historyFinite = std::isfinite(history.x) &&
                            std::isfinite(history.y) && std::isfinite(history.z) &&
                            std::isfinite(history.w) && std::isfinite(work);
                        mixedHistoryInvalid = mixedHistoryInvalid || !historyFinite ||
                            history.x < 0.0f || history.y < 0.0f ||
                            history.z < 0.0f || history.w < 0.0f ||
                            history.w > 1.0f || work < 0.0f ||
                            (history.y == 0.0f && (history.x != 0.0f ||
                                history.z != 0.0f || history.w != 0.0f ||
                                work != 0.0f)) ||
                            (history.y > 0.0f && history.x < history.y);
                        maximumDamage = std::max(maximumDamage, history.w);
                        summedWork += work;
                        const nm_float4 local = value.activationLocalGap[point];
                        mixedHistoryInvalid = mixedHistoryInvalid ||
                            !std::isfinite(local.x) || !std::isfinite(local.y) ||
                            !std::isfinite(local.z) || !std::isfinite(local.w) ||
                            local.w != 0.0f;
                    }
                    const float expectedTotalWork =
                        value.geometry.w * summedWork / 3.0f;
                    const float workScale = std::max(
                        {std::abs(value.state.w), std::abs(expectedTotalWork), 1.0e-20f});
                    mixedHistoryInvalid = mixedHistoryInvalid ||
                        value.mixedPointWork.w != 0.0f ||
                        std::abs(value.state.x - maximumDamage) >
                            64.0f * std::numeric_limits<float>::epsilon() ||
                        std::abs(value.state.w - expectedTotalWork) >
                            128.0f * std::numeric_limits<float>::epsilon() * workScale;
                    if (valueDormant) {
                        for (std::size_t point = 0u; point < 3u; ++point) {
                            const nm_float4 local = value.activationLocalGap[point];
                            mixedHistoryInvalid = mixedHistoryInvalid ||
                                value.mixedPointHistory[point].x != 0.0f ||
                                value.mixedPointHistory[point].y != 0.0f ||
                                value.mixedPointHistory[point].z != 0.0f ||
                                value.mixedPointHistory[point].w != 0.0f ||
                                workAt(value.mixedPointWork, point) != 0.0f ||
                                local.x != 0.0f || local.y != 0.0f || local.z != 0.0f;
                        }
                    }
                    mixedHistoryInvalid = mixedHistoryInvalid || dormantLatchChanged;
                }
                bool mixedIdentityChanged = false;
                if (mixedMode) {
                    const nm_u32 immutableFlags =
                        layout.adjacency.w & ~NM_TOPOLOGY_COHESIVE_DORMANT;
                    mixedIdentityChanged =
                        value.adjacency.x != layout.adjacency.x ||
                        value.adjacency.y != layout.adjacency.y ||
                        value.adjacency.z != layout.adjacency.z ||
                        (value.adjacency.w & ~NM_TOPOLOGY_COHESIVE_DORMANT) !=
                            immutableFlags ||
                        std::memcmp(&value.lawIdentity, &layout.lawIdentity,
                            sizeof(value.lawIdentity)) != 0 ||
                        std::memcmp(&value.activationControl,
                            &layout.activationControl,
                            sizeof(value.activationControl)) != 0;
                } else {
                    mixedIdentityChanged =
                        std::memcmp(&value.lawIdentity, &layout.lawIdentity,
                            sizeof(value.lawIdentity)) != 0 ||
                        std::memcmp(&value.activationControl,
                            &layout.activationControl,
                            sizeof(value.activationControl)) != 0 ||
                        std::memcmp(&value.activationLocalGap,
                            &layout.activationLocalGap,
                            sizeof(value.activationLocalGap)) != 0 ||
                        std::memcmp(&value.mixedPointHistory,
                            &layout.mixedPointHistory,
                            sizeof(value.mixedPointHistory)) != 0 ||
                        std::memcmp(&value.mixedPointWork,
                            &layout.mixedPointWork,
                            sizeof(value.mixedPointWork)) != 0;
                }
                cohesiveLayoutChanged = cohesiveLayoutChanged ||
                    std::memcmp(&value.nodesAndFirst, &layout.nodesAndFirst,
                        sizeof(value.nodesAndFirst)) != 0 ||
                    (!mixedMode && std::memcmp(&value.adjacency,
                        &layout.adjacency, sizeof(value.adjacency)) != 0) ||
                    mixedIdentityChanged ||
                    (geometryChanged && !activatedMortarReference) ||
                    activatedMortarFrameInvalid ||
                    std::memcmp(&value.separatedNodes, &layout.separatedNodes,
                        sizeof(value.separatedNodes)) != 0 ||
                    std::memcmp(&value.mortarSideAVertexWeights,
                        &layout.mortarSideAVertexWeights,
                        sizeof(value.mortarSideAVertexWeights)) != 0 ||
                    std::memcmp(&value.mortarSideBVertexWeights,
                        &layout.mortarSideBVertexWeights,
                        sizeof(value.mortarSideBVertexWeights)) != 0 ||
                    !std::isfinite(value.state.x) || value.state.x < layout.state.x ||
                    value.state.x > (mixedMode ? 1.0f : std::nextafter(1.0f, 0.0f)) ||
                    !std::isfinite(value.state.y) || value.state.y < layout.state.y ||
                    !std::isfinite(value.state.z) || value.state.z < 0.0f ||
                    !std::isfinite(value.state.w) || value.state.w < 0.0f ||
                    mixedHistoryInvalid;
            }
            if (cohesiveLayoutChanged ||
                (state.dispatch.punctureChannelCount != 0u &&
                    std::memcmp(snapshot.punctureChannels.data() + environment * state.dispatch.punctureChannelCount,
                        state.femImmutablePunctureLayout.data(), state.dispatch.punctureChannelCount * sizeof(NMPunctureChannelGPU)) != 0) ||
                std::memcmp(snapshot.topologyStates.data() + environment * state.dispatch.objectCount,
                    state.femImmutableTopologyStateLayout.data(), state.dispatch.objectCount * sizeof(NMFEMTopologyStateGPU)) != 0) {
                diagnostics.message = "Matter snapshot changed immutable FEM topology events or accounting";
                return diagnostics;
            }
            // Stable node lineage affects self-contact eligibility even when
            // connectivity and mechanical nodes are unchanged. Immutable
            // material fields therefore bind the complete topology record.
            if (std::memcmp(snapshot.femTopologyNodes.data() + environment * state.dispatch.femNodeCount,
                    state.femImmutableNodeLayout.data(), state.dispatch.femNodeCount * sizeof(NMFEMTopologyNodeGPU)) != 0) {
                diagnostics.message = "Matter snapshot changed an immutable FEM material-field topology node";
                return diagnostics;
            }
            if (std::memcmp(snapshot.femTopologyTetrahedra.data() + environment * perEnvironment,
                    state.femImmutableElementLayout.data(), perEnvironment * sizeof(NMTetrahedronGPU)) != 0) {
                diagnostics.message = "Matter snapshot changed an immutable FEM material-field element";
                return diagnostics;
            }
        }
    } else {
        for (const auto& tetrahedron : snapshot.femTopologyTetrahedra) {
            const auto& q = tetrahedron.materialFrameRotation;
            if (q.x != 0.0f || q.y != 0.0f || q.z != 0.0f || q.w != 0.0f) {
                diagnostics.message = "Matter snapshot invented an FEM material frame";
                return diagnostics;
            }
        }
    }

    if (state.femAuthoredMassLayout.size() != state.dispatch.femNodeCount ||
        state.femAuthoredRestLayout.size() != state.dispatch.femNodeCount ||
        state.femMutableMassRestLayout.size() != state.dispatch.femNodeCount) {
        diagnostics.message = "Matter immutable authored FEM mass/rest layout changed";
        return diagnostics;
    }
    for (std::size_t environment = 0u;
         environment < state.dispatch.environmentCount; ++environment) {
        for (std::size_t nodeIndex = 0u;
             nodeIndex < state.dispatch.femNodeCount; ++nodeIndex) {
            // Native split/collapse updates mass and reference coordinates,
            // including reserved slots; retain its topology-aware admission.
            if (state.femMutableMassRestLayout[nodeIndex] != 0u) continue;
            const auto& node = snapshot.femNodes[
                environment * state.dispatch.femNodeCount + nodeIndex];
            const std::array<float, 2> observed{
                node.positionAndMass.w, node.velocityAndInverseMass.w};
            const auto& authoredRest = state.femAuthoredRestLayout[nodeIndex];
            const float authoredMass =
                state.femAuthoredMassLayout[nodeIndex][0];
            const bool unchangedAuthoredState =
                std::memcmp(observed.data(),
                    state.femAuthoredMassLayout[nodeIndex].data(),
                    sizeof(observed)) == 0 &&
                std::memcmp(&node.restAndFixed, &authoredRest,
                    sizeof(node.restAndFixed)) == 0;
            const bool releasedAuthoredStatic =
                authoredRest.w == 1.0f && node.restAndFixed.w == 0.0f &&
                node.positionAndMass.w == authoredMass && authoredMass > 0.0f &&
                node.velocityAndInverseMass.w == 1.0f / authoredMass &&
                std::memcmp(&node.restAndFixed, &authoredRest,
                    3u * sizeof(float)) == 0;
            const bool temporaryGripActive =
                (authoredRest.w == 0.0f || authoredRest.w == 1.0f) &&
                node.restAndFixed.w == 3.0f &&
                node.positionAndMass.w == authoredMass && authoredMass > 0.0f &&
                node.velocityAndInverseMass.w == 0.0f &&
                std::memcmp(&node.restAndFixed, &authoredRest,
                    3u * sizeof(float)) == 0;
            const bool releasedTemporaryGrip =
                (authoredRest.w == 0.0f || authoredRest.w == 1.0f) &&
                node.restAndFixed.w == 0.0f &&
                node.positionAndMass.w == authoredMass && authoredMass > 0.0f &&
                node.velocityAndInverseMass.w == 1.0f / authoredMass &&
                std::memcmp(&node.restAndFixed, &authoredRest,
                    3u * sizeof(float)) == 0;
            if (!unchangedAuthoredState && !releasedAuthoredStatic &&
                !temporaryGripActive && !releasedTemporaryGrip) {
                diagnostics.message =
                    "Matter snapshot contains an invalid FEM kinematic grip or changed authored mass/rest constraint";
                return diagnostics;
            }
        }
    }

    for (std::size_t environment=0u;environment<state.dispatch.environmentCount;++environment)
        for (const auto& [index, referenceCenter] : state.femReferenceCenterLayout) {
            if (std::memcmp(&snapshot.adaptive[environment*state.dispatch.objectCount+index].referenceCenter,
                    &referenceCenter, sizeof(referenceCenter)) != 0) {
                diagnostics.message = "Matter snapshot changed immutable FEM reference-center metadata";
                return diagnostics;
            }
        }

    // Restore validates the same FP32 geometry model as source admission,
    // but preserves accepted Metal boundary states whose host arithmetic can
    // differ by contraction/reduction rounding. No fixed epsilon widens J.
    for (std::size_t environment = 0u; environment < state.dispatch.environmentCount; ++environment)
        for (const auto& [index, limits] : state.femReferenceDeterminantLimits) {
            const auto& t = state.femImmutableElementLayout[index];
            const auto interval = detail::femReferenceDeterminantInterval(
                t, snapshot.femNodes.data(), environment * state.dispatch.femNodeCount);
            if (!interval.possiblyAdmissible(limits)) {
                diagnostics.message = "Matter snapshot current FEM geometry has no admissible FP32 determinant in its fixed reference material domain";
                return diagnostics;
            }
        }

    // Regional material parameters are fixed authored data, not identified
    // state. Preserve unrelated posterior values, but never allow their
    // immutable parameter identities to be retargeted into a fixed region.
    for (std::size_t environment = 0u; environment < state.dispatch.environmentCount; ++environment)
        for (const auto& [parameter, expected] : state.femRegionalFixedParameterLayout) {
            const auto& value = snapshot.environmentParameters[environment * state.dispatch.parameterCount + parameter];
            if (std::memcmp(&value, &expected, sizeof(value)) != 0) {
                diagnostics.message = "Matter snapshot changed a fixed authored FEM material parameter";
                return diagnostics;
            }
        }
    // The authored CFL floor is fixed; active/requested exponents and their
    // event metadata remain legitimate scheduler state and are not pinned.
    for (std::size_t environment = 0u; environment < state.dispatch.environmentCount; ++environment)
        for (const auto& [scheduler, expected] : state.femRegionalBaseExponentLayout) {
            if (snapshot.schedulers[environment * state.dispatch.objectCount + scheduler].baseExponent != expected) {
                diagnostics.message = "Matter snapshot changed a fixed authored FEM scheduler floor";
                return diagnostics;
            }
        }
    if (snapshot.identification.size() < state.femRegionalIdentificationIdentityLayout.size()) {
        diagnostics.message = "Matter regional identification layout changed";
        return diagnostics;
    }
    for (std::size_t index = 0u; index < state.femRegionalIdentificationIdentityLayout.size(); ++index) {
        if (std::memcmp(&snapshot.identification[index].identity,
                &state.femRegionalIdentificationIdentityLayout[index], sizeof(nm_uint4)) != 0) {
            diagnostics.message = "Matter snapshot retargeted an identification distribution in a regional world";
            return diagnostics;
        }
    }

    // A snapshot restores one coupled physical state. Pressure is signed,
    // but wall geometry, hydraulic volume and scheduler cadence cannot diverge.
    for (std::uint32_t environment = 0u; environment < state.dispatch.environmentCount; ++environment) {
        for (const auto& cavity : state.vascularValue.cavities) {
            const auto& scheduler = snapshot.schedulers[
                environment * state.dispatch.objectCount + cavity.identity.z];
            const auto& adaptive = snapshot.adaptive[
                environment * state.dispatch.objectCount + cavity.identity.z];
            const auto exponent = state.dispatch.maximumRateExponent;
            if (scheduler.baseExponent != exponent || scheduler.activeExponent != exponent ||
                scheduler.requestedExponent != exponent || !std::isfinite(scheduler.numerical.w) ||
                !(scheduler.numerical.w > 0.0f) ||
                adaptive.activeRepresentation != NM_REPRESENTATION_FEM) {
                diagnostics.message = "Matter snapshot cavity wall changed hydraulic microtick ownership";
                return diagnostics;
            }
            const auto nodeBase = static_cast<std::size_t>(environment) * state.dispatch.femNodeCount;
            const auto& origin = snapshot.femNodes[nodeBase +
                state.vascularValue.cavityFaces[cavity.faces.x].nodes.x].positionAndMass;
            const auto point = [&](std::uint32_t node) {
                const auto& p = snapshot.femNodes[nodeBase + node].positionAndMass;
                return std::array<double, 3>{double(p.x) - origin.x, double(p.y) - origin.y, double(p.z) - origin.z};
            };
            double geometry = 0.0;
            for (std::uint32_t index = 0u; index < cavity.faces.y; ++index) {
                const auto& face = state.vascularValue.cavityFaces[cavity.faces.x + index];
                const auto a = point(face.nodes.x), b = point(face.nodes.y), c = point(face.nodes.z);
                geometry += (a[0] * (b[1] * c[2] - b[2] * c[1]) +
                    a[1] * (b[2] * c[0] - b[0] * c[2]) +
                    a[2] * (b[0] * c[1] - b[1] * c[0])) / 6.0;
            }
            const auto volumeRow = cavity.identity.y;
            const auto stateBase = static_cast<std::size_t>(environment) * state.vascularValue.layout.ranges.z;
            const float volume = snapshot.vascularState[stateBase + volumeRow].x *
                state.vascularValue.unknowns[volumeRow].initialAndScaling.y;
            const auto scaling = state.vascularValue.unknowns[cavity.identity.w].initialAndScaling;
            const double tolerance = double(scaling.z) * scaling.w +
                64.0 * std::numeric_limits<float>::epsilon() * std::max(std::abs(geometry), double(volume));
            if (!(geometry > 0.0) || !std::isfinite(geometry) || std::abs(geometry - volume) > tolerance) {
                diagnostics.message = "Matter snapshot cavity geometry and hydraulic volume disagree";
                return diagnostics;
            }
        }
    }

    std::vector<std::uint32_t> restoredFEMIncidence;
    std::vector<NMIncidenceRangeGPU> restoredFEMRanges;
    if (rebuildTopologyIncidence) {
        try {
            const std::size_t environments = state.dispatch.environmentCount;
            const std::size_t nodesPerEnvironment =
                state.dispatch.femNodeCount;
            const std::size_t tetrahedraPerEnvironment =
                state.dispatch.tetrahedronCount;
            const std::size_t nodeCount =
                environments * nodesPerEnvironment;
            const std::size_t tetrahedronCount =
                environments * tetrahedraPerEnvironment;
            const std::size_t incidenceCapacity =
                state.femNodeIncidence.length / sizeof(std::uint32_t);
            const std::size_t incidencePerEnvironment = environments == 0u
                ? 0u : incidenceCapacity / environments;
            const bool arenaShapeValid =
                environments != 0u &&
                state.femNodeIncidence.length % sizeof(std::uint32_t) == 0u &&
                incidenceCapacity % environments == 0u &&
                incidenceCapacity <=
                    std::numeric_limits<std::uint32_t>::max() &&
                state.femNodeIncidenceCheckpoint.length ==
                    state.femNodeIncidence.length &&
                state.femNodeRanges.length %
                        sizeof(NMIncidenceRangeGPU) ==
                    0u &&
                state.femNodeRanges.length /
                        sizeof(NMIncidenceRangeGPU) ==
                    nodeCount &&
                state.femNodeRangesCheckpoint.length ==
                    state.femNodeRanges.length &&
                snapshot.femTopologyNodes.size() == nodeCount &&
                snapshot.femTopologyTetrahedra.size() == tetrahedronCount;
            if (!arenaShapeValid) {
                diagnostics.message =
                    "Matter snapshot topology incidence arena shape changed: "
                    "incidence_bytes=" +
                    std::to_string(state.femNodeIncidence.length) +
                    " incidence_checkpoint_bytes=" +
                    std::to_string(
                        state.femNodeIncidenceCheckpoint.length
                    ) +
                    " incidence_capacity=" +
                    std::to_string(incidenceCapacity) +
                    " incidence_per_environment=" +
                    std::to_string(incidencePerEnvironment) +
                    " tetrahedron_slot_incidence=" +
                    std::to_string(tetrahedraPerEnvironment * 4u) +
                    " range_bytes=" +
                    std::to_string(state.femNodeRanges.length) +
                    " range_checkpoint_bytes=" +
                    std::to_string(state.femNodeRangesCheckpoint.length) +
                    " expected_nodes=" + std::to_string(nodeCount) +
                    " snapshot_nodes=" +
                    std::to_string(snapshot.femTopologyNodes.size()) +
                    " expected_tetrahedra=" +
                    std::to_string(tetrahedronCount) +
                    " snapshot_tetrahedra=" +
                    std::to_string(
                        snapshot.femTopologyTetrahedra.size()
                    );
                return diagnostics;
            }

            restoredFEMIncidence.assign(incidenceCapacity, 0u);
            restoredFEMRanges.assign(nodeCount, NMIncidenceRangeGPU{});
            std::vector<std::uint32_t> counts(nodeCount, 0u);
            std::vector<std::uint32_t> cursors(nodeCount, 0u);
            bool topologyValid = true;
            const auto visitActiveTetrahedronNodes = [&] (
                const std::size_t environment,
                const std::uint32_t localTetrahedron,
                const auto& visitor
            ) {
                const NMTetrahedronGPU& tetrahedron =
                    snapshot.femTopologyTetrahedra[
                        environment * tetrahedraPerEnvironment +
                        localTetrahedron
                    ];
                if ((tetrahedron.identity.w & NM_OBJECT_ACTIVE) == 0u) {
                    return;
                }
                const std::array<std::uint32_t, 4u> nodes{
                    tetrahedron.nodes.x,
                    tetrahedron.nodes.y,
                    tetrahedron.nodes.z,
                    tetrahedron.nodes.w,
                };
                for (std::uint32_t slot = 0u; slot < 4u; ++slot) {
                    const std::uint32_t node = nodes[slot];
                    bool duplicate = false;
                    for (std::uint32_t earlier = 0u;
                         earlier < slot; ++earlier) {
                        duplicate = duplicate || nodes[earlier] == node;
                    }
                    if (duplicate) {
                        continue;
                    }
                    if (node >= nodesPerEnvironment) {
                        topologyValid = false;
                        continue;
                    }
                    const std::size_t globalNode =
                        environment * nodesPerEnvironment + node;
                    const NMFEMTopologyNodeGPU& topologyNode =
                        snapshot.femTopologyNodes[globalNode];
                    if ((topologyNode.identity.w & NM_TOPOLOGY_ACTIVE) == 0u ||
                        topologyNode.identity.y != tetrahedron.identity.y) {
                        topologyValid = false;
                        continue;
                    }
                    visitor(
                        globalNode,
                        localTetrahedron
                    );
                }
            };
            for (std::size_t environment = 0u;
                 environment < environments; ++environment) {
                for (std::uint32_t tetrahedron = 0u;
                     tetrahedron < tetrahedraPerEnvironment;
                     ++tetrahedron) {
                    visitActiveTetrahedronNodes(
                        environment,
                        tetrahedron,
                        [&] (const std::size_t node, const std::uint32_t) {
                            if (counts[node] ==
                                std::numeric_limits<std::uint32_t>::max()) {
                                topologyValid = false;
                                return;
                            }
                            ++counts[node];
                        }
                    );
                }
            }
            for (std::size_t environment = 0u;
                 environment < environments; ++environment) {
                const std::size_t nodeBase =
                    environment * nodesPerEnvironment;
                const std::size_t incidenceBase =
                    environment * incidencePerEnvironment;
                std::size_t running = 0u;
                for (std::size_t localNode = 0u;
                     localNode < nodesPerEnvironment; ++localNode) {
                    const std::size_t node = nodeBase + localNode;
                    if (incidenceBase + running + counts[node] >
                        restoredFEMIncidence.size()) {
                        topologyValid = false;
                        break;
                    }
                    NMIncidenceRangeGPU& range = restoredFEMRanges[node];
                    range.first = static_cast<std::uint32_t>(
                        incidenceBase + running
                    );
                    range.count = counts[node];
                    range.objectIndex = counts[node] == 0u
                        ? NM_INVALID_INDEX
                        : snapshot.femTopologyNodes[node].identity.y;
                    range.reserved = 0u;
                    running += counts[node];
                }
                topologyValid = topologyValid &&
                    running <= incidencePerEnvironment;
            }
            if (topologyValid) {
                for (std::size_t environment = 0u;
                     environment < environments; ++environment) {
                    for (std::uint32_t tetrahedron = 0u;
                         tetrahedron < tetrahedraPerEnvironment;
                         ++tetrahedron) {
                        visitActiveTetrahedronNodes(
                            environment,
                            tetrahedron,
                            [&] (
                                const std::size_t node,
                                const std::uint32_t localTetrahedron
                            ) {
                                const NMIncidenceRangeGPU& range =
                                    restoredFEMRanges[node];
                                if (cursors[node] >= range.count ||
                                    static_cast<std::size_t>(range.first) +
                                            cursors[node] >=
                                        restoredFEMIncidence.size()) {
                                    topologyValid = false;
                                    return;
                                }
                                restoredFEMIncidence[
                                    range.first + cursors[node]++
                                ] = localTetrahedron;
                            }
                        );
                    }
                }
            }
            topologyValid = topologyValid && std::ranges::equal(
                counts,
                cursors
            );
            if (!topologyValid) {
                diagnostics.message =
                    "Matter snapshot topology incidence is invalid or exceeds "
                    "the exact device arena";
                return diagnostics;
            }
        } catch (const std::bad_alloc&) {
            diagnostics.message =
                "failed to allocate Matter topology incidence restore staging";
            return diagnostics;
        }
    }

    std::vector<NMRigidProxyGPU> restoredProxyLayout =
        state.rigidProxyLayout;
    if (snapshot.sutureProxyEdges.size() !=
        state.sutureProxyIndices.size()) {
        diagnostics.message =
            "Matter snapshot suture-proxy set width changed";
        return diagnostics;
    }
    std::uint32_t restoredRequiredRodNodeCount =
        state.requiredRodNodeCount;
    if (!snapshot.sutureProxyEdges.empty()) {
        std::vector<std::uint32_t> sorted = snapshot.sutureProxyEdges;
        std::ranges::sort(sorted);
        for (std::size_t slot = 0u; slot < sorted.size(); ++slot) {
            if (sorted[slot] >=
                    std::numeric_limits<std::uint32_t>::max() - 1u ||
                (slot != 0u && sorted[slot] == sorted[slot - 1u])) {
                diagnostics.message =
                    "Matter snapshot suture-proxy set is invalid";
                return diagnostics;
            }
            restoredRequiredRodNodeCount = std::max(
                restoredRequiredRodNodeCount,
                sorted[slot] + 2u
            );
            const std::uint32_t proxy = state.sutureProxyIndices[slot];
            restoredProxyLayout[proxy].bodyIndex =
                snapshot.sutureProxyEdges[slot];
            restoredProxyLayout[proxy].sceneBodyIndex =
                snapshot.sutureProxyEdges[slot] + 1u;
        }
    }

    @autoreleasepool {
        bool stagingValid = true;
        const auto stage = [&](const auto& values,
                               const char* label) -> id<MTLBuffer> {
            using Value = typename std::decay_t<decltype(values)>::value_type;
            const NSUInteger bytes = static_cast<NSUInteger>(
                values.size() * sizeof(Value)
            );
            if (bytes == 0u) {
                return nil;
            }
            id<MTLBuffer> result = [state.device
                newBufferWithBytes:values.data()
                            length:bytes
                           options:MTLResourceStorageModeShared];
            if (result == nil) {
                stagingValid = false;
                if (diagnostics.message.empty()) {
                    diagnostics.message = std::string{
                        "failed to allocate Matter snapshot "
                    } + label + " staging";
                }
            }
            return result;
        };
        id<MTLBuffer> particles = stage(snapshot.particles, "particle");
        id<MTLBuffer> femNodes = stage(snapshot.femNodes, "FEM-node");
        id<MTLBuffer> particleMaterialState = stage(
            snapshot.particleMaterialState,
            "particle-material-state"
        );
        id<MTLBuffer> femMaterialState = stage(
            snapshot.femMaterialState,
            "FEM-material-state"
        );
        id<MTLBuffer> femFields = stage(snapshot.femFields, "FEM-field");
        id<MTLBuffer> vascularState = stage(snapshot.vascularState, "vascular-state");
        id<MTLBuffer> vascularClock = stage(snapshot.vascularClock, "vascular-clock");
        id<MTLBuffer> solverCertificates = stage(
            snapshot.solverCertificates,
            "solver-certificate"
        );
        id<MTLBuffer> statuses = stage(snapshot.statuses, "status");
        id<MTLBuffer> activeNodeIndices = stage(
            snapshot.mpmActiveNodeIndices,
            "MPM-active-index"
        );
        id<MTLBuffer> nodeToActive = stage(
            snapshot.mpmNodeToActive,
            "MPM-node-map"
        );
        id<MTLBuffer> activeNodeCounts = stage(
            snapshot.mpmActiveNodeCounts,
            "MPM-active-count"
        );
        id<MTLBuffer> rigidGeneralized = stage(
            snapshot.rigidGeneralizedCandidate,
            "rigid-generalized-candidate"
        );
        id<MTLBuffer> learnedWeights = stage(
            snapshot.learnedWeights,
            "learned-weight"
        );
        const std::array learnedRevision{snapshot.learnedWeightRevision};
        id<MTLBuffer> learnedRevisionBuffer = stage(
            learnedRevision,
            "learned-revision"
        );
        id<MTLBuffer> topologyNodes = stage(
            snapshot.femTopologyNodes,
            "topology-node"
        );
        id<MTLBuffer> topologyTetrahedra = stage(
            snapshot.femTopologyTetrahedra,
            "topology-tetrahedron"
        );
        id<MTLBuffer> cohesiveFaces = stage(
            snapshot.cohesiveFaces,
            "cohesive-face"
        );
        id<MTLBuffer> punctureChannels = stage(
            snapshot.punctureChannels,
            "puncture-channel"
        );
        id<MTLBuffer> topologyStates = stage(
            snapshot.topologyStates,
            "topology-state"
        );
        id<MTLBuffer> femNodeIncidence = rebuildTopologyIncidence
            ? stage(restoredFEMIncidence, "FEM-node-incidence") : nil;
        id<MTLBuffer> femNodeRanges = rebuildTopologyIncidence
            ? stage(restoredFEMRanges, "FEM-node-range") : nil;
        id<MTLBuffer> contactHistories = stage(
            snapshot.contactHistories,
            "contact-history"
        );
        id<MTLBuffer> humanSupportHistories = stage(
            snapshot.humanSupportHistories,
            "Human-support-history"
        );
        id<MTLBuffer> humanSupportConsequences = stage(
            snapshot.humanSupportConsequences,
            "Human-support-consequence"
        );
        id<MTLBuffer> deformableContactHistories = stage(
            snapshot.deformableContactHistories,
            "deformable-contact-history"
        );
        id<MTLBuffer> adaptive = stage(snapshot.adaptive, "adaptive");
        id<MTLBuffer> schedulers = stage(snapshot.schedulers, "scheduler");
        id<MTLBuffer> reactions = stage(snapshot.reactions, "reaction");
        id<MTLBuffer> rigidStates = stage(
            snapshot.rigidStates,
            "rigid-state"
        );
        id<MTLBuffer> contactSamples = state.captureDiagnostics
            ? stage(snapshot.contactSamples, "contact-sample")
            : nil;
        id<MTLBuffer> identification = stage(
            snapshot.identification,
            "identification"
        );
        id<MTLBuffer> environmentParameters = stage(
            snapshot.environmentParameters,
            "environment-parameter"
        );
        id<MTLBuffer> rigidProxies = stage(
            restoredProxyLayout,
            "rigid-proxy"
        );
        const std::array<nm_uint4, 1u> acceptedCursorValue{{
            nm_uint4{snapshot.controlStep, snapshot.physicsSubstep, 0u,
                     0x4e4d4343u}}};
        id<MTLBuffer> acceptedCursor = stage(
            acceptedCursorValue, "accepted-control-cursor");
        if (!stagingValid) {
            return diagnostics;
        }

        id<MTLCommandBuffer> commandBuffer = [state.queue commandBuffer];
        id<MTLBlitCommandEncoder> blit = [commandBuffer blitCommandEncoder];
        if (commandBuffer == nil || blit == nil) {
            diagnostics.message =
                "failed to encode Matter snapshot restore";
            return diagnostics;
        }
        [blit setLabel:@"Numi Matter snapshot restore"];
        const auto copy = [&](id<MTLBuffer> source,
                              id<MTLBuffer> destination) {
            if (destination.length != 0u) {
                [blit fillBuffer:destination
                           range:NSMakeRange(0u, destination.length)
                           value:0u];
            }
            if (source != nil && source.length != 0u) {
                [blit copyFromBuffer:source sourceOffset:0u
                            toBuffer:destination destinationOffset:0u
                                size:source.length];
            }
        };
        const auto mirror = [&](id<MTLBuffer> source,
                                id<MTLBuffer> accepted,
                                id<MTLBuffer> candidate,
                                id<MTLBuffer> checkpoint) {
            copy(source, accepted);
            copy(source, candidate);
            copy(source, checkpoint);
        };
        mirror(particles, state.particleAccepted,
            state.particleCandidate, state.particleCheckpoint);
        mirror(particleMaterialState,
            state.particleMaterialStateAccepted,
            state.particleMaterialStateCandidate,
            state.particleMaterialStateCheckpoint);
        mirror(femNodes, state.femAccepted,
            state.femCandidate, state.femCheckpoint);
        mirror(femMaterialState,
            state.femMaterialStateAccepted,
            state.femMaterialStateCandidate,
            state.femMaterialStateCheckpoint);
        mirror(femFields, state.femFieldsAccepted,
            state.femFieldsCandidate, state.femFieldsCheckpoint);
        mirror(vascularState, state.vascularAccepted,
            state.vascularCandidate, state.vascularCheckpoint);
        mirror(vascularClock, state.vascularClockAccepted,
            state.vascularClockCandidate, state.vascularClockCheckpoint);
        copy(femFields, state.femFieldsWork);
        mirror(learnedWeights, state.learnedWeightsAccepted,
            state.learnedWeightsCandidate, state.learnedWeightsCheckpoint);
        mirror(learnedRevisionBuffer, state.learnedRevisionAccepted,
            state.learnedRevisionCandidate, state.learnedRevisionCheckpoint);
        mirror(topologyNodes, state.femTopologyNodesAccepted,
            state.femTopologyNodesCandidate,
            state.femTopologyNodesCheckpoint);
        mirror(topologyTetrahedra, state.femTetrahedraAccepted,
            state.femTetrahedraCandidate,
            state.femTetrahedraCheckpoint);
        mirror(cohesiveFaces, state.cohesiveFacesAccepted,
            state.cohesiveFacesCandidate, state.cohesiveFacesCheckpoint);
        mirror(punctureChannels, state.punctureChannelsAccepted,
            state.punctureChannelsCandidate,
            state.punctureChannelsCheckpoint);
        mirror(topologyStates, state.topologyStatesAccepted,
            state.topologyStatesCandidate, state.topologyStatesCheckpoint);
        if (rebuildTopologyIncidence) {
            copy(femNodeIncidence, state.femNodeIncidence);
            copy(femNodeIncidence, state.femNodeIncidenceCheckpoint);
            copy(femNodeRanges, state.femNodeRanges);
            copy(femNodeRanges, state.femNodeRangesCheckpoint);
            if (state.topologyIncidenceCursors.length != 0u) {
                [blit fillBuffer:state.topologyIncidenceCursors
                           range:NSMakeRange(
                               0u,
                               state.topologyIncidenceCursors.length
                           )
                           value:0u];
            }
        }
        mirror(contactHistories, state.contactHistoriesAccepted,
            state.contactHistoriesCandidate,
            state.contactHistoriesCheckpoint);
        mirror(humanSupportHistories,
            state.humanSupportHistoriesAccepted,
            state.humanSupportHistoriesCandidate,
            state.humanSupportHistoriesCheckpoint);
        mirror(humanSupportConsequences,
            state.humanSupportConsequencesAccepted,
            state.humanSupportConsequencesCandidate,
            state.humanSupportConsequencesCheckpoint);
        mirror(deformableContactHistories,
            state.deformableContactHistoriesAccepted,
            state.deformableContactHistoriesCandidate,
            state.deformableContactHistoriesCheckpoint);
        copy(solverCertificates, state.solverCertificates);
        copy(statuses, state.statuses);
        copy(activeNodeIndices, state.mpmActiveNodeIndices);
        copy(nodeToActive, state.mpmNodeToActive);
        copy(activeNodeCounts, state.mpmActiveNodeCounts);
        copy(rigidGeneralized, state.coupledGeneralizedCandidate);
        copy(adaptive, state.adaptive);
        copy(schedulers, state.schedulers);
        copy(schedulers, state.schedulerPrevious);
        copy(schedulers, state.schedulerCheckpoint);
        copy(reactions, state.frameReactions);
        copy(rigidStates, state.rigidStates);
        if (state.captureDiagnostics) {
            copy(contactSamples, state.contactSamples);
        }
        copy(identification, state.identificationDistributions);
        copy(environmentParameters, state.environmentParameters);
        copy(rigidProxies, state.rigidProxies);
        copy(acceptedCursor, state.acceptedControlCursor);
        [blit endEncoding];
        [commandBuffer commit];
        [commandBuffer waitUntilCompleted];
        if (commandBuffer.status != MTLCommandBufferStatusCompleted) {
            diagnostics.message =
                "Matter snapshot restore command failed: " +
                errorString(commandBuffer.error);
            return diagnostics;
        }
    }

    state.rigidProxyLayout = std::move(restoredProxyLayout);
    state.sutureProxyEdges = snapshot.sutureProxyEdges;
    state.sutureProxyBindingRevision = snapshot.sutureProxyBindingRevision;
    state.requiredRodNodeCount = restoredRequiredRodNodeCount;
    state.coupledTimestepMultiplier.store(
        snapshot.coupledTimestepMultiplier,
        std::memory_order_release
    );
    state.coupledTimestepDivisor.store(
        snapshot.coupledTimestepDivisor,
        std::memory_order_release
    );
    state.fgmresIterationBudgetOverride.store(
        snapshot.fgmresIterationBudgetOverride,
        std::memory_order_release
    );
    state.newtonIterationBudgetOverride.store(
        snapshot.newtonIterationBudgetOverride,
        std::memory_order_release
    );
    ownership->controlStep = snapshot.controlStep;
    ownership->physicsSubstep = snapshot.physicsSubstep;
    ownership->identificationGeneration =
        snapshot.identificationGeneration;
    ownership->identificationCheckpoint =
        snapshot.identificationCheckpoint;
    ownership->identificationAdvanced = snapshot.identificationAdvanced;
    diagnostics.encoded = true;
    diagnostics.residentBytes = state.residentBytes;
    diagnostics.device = nsString(state.device.name);
    diagnostics.message =
        "Numi Matter completion-boundary snapshot restored";
    return diagnostics;
}

RuntimeStateSnapshot Runtime::snapshot() const {
    RuntimeStateSnapshot snapshot;
    if (state_ == nullptr) {
        snapshot.message = "Matter runtime is not initialized";
        return snapshot;
    }
    snapshot.sourcePhysicsFingerprint = state_->sourcePhysicsFingerprint;
    snapshot.deviceProgramFingerprint = state_->executionFingerprint;
    const auto ownership = state_->commandOwnership;
    {
        const std::lock_guard lock(ownership->mutex);
        if (ownership->activeCommandBuffer != nullptr ||
            ownership->preparedStateOpen || ownership->applyEncoded ||
            ownership->restoreRequired) {
            snapshot.message =
                "Matter state cannot be read while a borrowed transaction is active";
            return snapshot;
        }
        snapshot.sutureProxyEdges = state_->sutureProxyEdges;
        snapshot.sutureProxyBindingRevision =
            state_->sutureProxyBindingRevision;
        snapshot.coupledTimestepMultiplier =
            state_->coupledTimestepMultiplier.load(
                std::memory_order_acquire
            );
        snapshot.coupledTimestepDivisor =
            state_->coupledTimestepDivisor.load(
                std::memory_order_acquire
            );
        snapshot.fgmresIterationBudgetOverride =
            state_->fgmresIterationBudgetOverride.load(
                std::memory_order_acquire
            );
        snapshot.newtonIterationBudgetOverride =
            state_->newtonIterationBudgetOverride.load(
                std::memory_order_acquire
            );
        const auto* acceptedCursor = static_cast<const nm_uint4*>(
            state_->acceptedControlCursor.contents);
        if (acceptedCursor == nullptr) {
            snapshot.message =
                "Matter accepted-control-cursor readback is unavailable";
            return snapshot;
        }
        snapshot.controlStep = acceptedCursor->x;
        snapshot.physicsSubstep = acceptedCursor->y;
        snapshot.identificationGeneration =
            ownership->identificationGeneration;
        snapshot.identificationCheckpoint =
            ownership->identificationCheckpoint;
        snapshot.identificationAdvanced = ownership->identificationAdvanced;
    }
    @autoreleasepool {
        const auto copy = [&](id<MTLBuffer> source) -> id<MTLBuffer> {
            return [state_->device newBufferWithLength:source.length
                                               options:MTLResourceStorageModeShared];
        };
        id<MTLBuffer> contactFailures = copy(state_->deformableContactFailures);
        id<MTLBuffer> particles = copy(state_->particleAccepted);
        id<MTLBuffer> femNodes = copy(state_->femAccepted);
        id<MTLBuffer> particleMaterialState =
            copy(state_->particleMaterialStateAccepted);
        id<MTLBuffer> femMaterialState =
            copy(state_->femMaterialStateAccepted);
        id<MTLBuffer> femFields = copy(state_->femFieldsAccepted);
        id<MTLBuffer> vascularState = copy(state_->vascularAccepted);
        id<MTLBuffer> vascularClock = copy(state_->vascularClockAccepted);
        id<MTLBuffer> solverCertificates = copy(state_->solverCertificates);
        id<MTLBuffer> statuses = copy(state_->statuses);
        id<MTLBuffer> mpmActiveNodeIndices =
            copy(state_->mpmActiveNodeIndices);
        id<MTLBuffer> mpmNodeToActive = copy(state_->mpmNodeToActive);
        id<MTLBuffer> mpmActiveNodeCounts =
            copy(state_->mpmActiveNodeCounts);
        id<MTLBuffer> rigidGeneralizedCandidate =
            copy(state_->coupledGeneralizedCandidate);
        id<MTLBuffer> learnedWeights = copy(state_->learnedWeightsAccepted);
        id<MTLBuffer> learnedRevision = copy(state_->learnedRevisionAccepted);
        id<MTLBuffer> topologyNodes = copy(state_->femTopologyNodesAccepted);
        id<MTLBuffer> topologyTetrahedra = copy(state_->femTetrahedraAccepted);
        id<MTLBuffer> cohesiveFaces = copy(state_->cohesiveFacesAccepted);
        id<MTLBuffer> punctureChannels = copy(state_->punctureChannelsAccepted);
        id<MTLBuffer> topologyStates = copy(state_->topologyStatesAccepted);
        id<MTLBuffer> contactHistories =
            copy(state_->contactHistoriesAccepted);
        id<MTLBuffer> humanSupportHistories =
            copy(state_->humanSupportHistoriesAccepted);
        id<MTLBuffer> humanSupportConsequences =
            copy(state_->humanSupportConsequencesAccepted);
        id<MTLBuffer> deformableContactHistories =
            copy(state_->deformableContactHistoriesAccepted);
        id<MTLBuffer> adaptive = copy(state_->adaptive);
        id<MTLBuffer> schedulers = copy(state_->schedulers);
        id<MTLBuffer> reactions = copy(state_->frameReactions);
        id<MTLBuffer> rigidStates = copy(state_->rigidStates);
        id<MTLBuffer> contactSamples = state_->captureDiagnostics
            ? copy(state_->contactSamples)
            : nil;
        id<MTLBuffer> identification =
            copy(state_->identificationDistributions);
        id<MTLBuffer> environmentParameters =
            copy(state_->environmentParameters);
        id<MTLBuffer> regionalBasisP = nil;
        id<MTLBuffer> regionalEffectiveBasisP = nil;
        id<MTLBuffer> regionalLinearizationNodes = nil;
        id<MTLBuffer> regionalLinearizationMaterialState = nil;
        id<MTLBuffer> regionalLinearizationSchedulerExponent = nil;
        id<MTLBuffer> regionalLinearizationLocalFHigh = nil;
        id<MTLBuffer> regionalLinearizationLocalFLow = nil;
        id<MTLBuffer> regionalOperatorAP = nil;
        id<MTLBuffer> regionalPivotedRAP = nil;
        id<MTLBuffer> regionalPivots = nil;
        id<MTLBuffer> regionalFactorValid = nil;
        id<MTLBuffer> regionalNodeBlockInverse = nil;
        std::string regionalDiagnosticsMessage;
        const std::uint32_t regionalModeCount =
            state_->femRegionalModeCount;
        if (!state_->captureDiagnostics) {
            regionalDiagnosticsMessage =
                "regional Galerkin readback requires captureDiagnostics";
        } else if (regionalModeCount == 0u) {
            regionalDiagnosticsMessage =
                "regional Galerkin selector is not active";
        } else {
            const std::uint64_t environments =
                state_->dispatch.environmentCount;
            const std::uint64_t nodes = state_->dispatch.femNodeCount;
            const std::uint64_t modes = regionalModeCount;
            const std::uint64_t bytes =
                nodes * modes * sizeof(nm_float4) +
                environments * nodes * modes * sizeof(nm_float4) +
                environments * nodes * modes * sizeof(nm_float4) +
                ((state_->mixedSolverValue.executionBudgets.z == 3u ||
                  state_->mixedSolverValue.executionBudgets.z == 4u)
                    ? 3u * environments * nodes * sizeof(nm_float4)
                    : 0u) +
                environments * nodes * sizeof(NMFEMNodeStateGPU) +
                environments * state_->dispatch.tetrahedronCount *
                    state_->dispatch.materialStateStride * sizeof(float) +
                environments * state_->dispatch.tetrahedronCount *
                    (sizeof(std::uint32_t) + 6u * sizeof(nm_float4)) +
                environments * modes * modes * sizeof(float) +
                environments * modes * sizeof(std::uint32_t) +
                environments * sizeof(std::uint32_t);
            constexpr std::uint64_t maximumReadbackBytes =
                64ull * 1024ull * 1024ull;
            if (bytes > maximumReadbackBytes) {
                regionalDiagnosticsMessage =
                    "regional Galerkin diagnostic vectors exceed the 64 MiB snapshot readback bound";
            } else {
                regionalBasisP = copy(state_->femRegionalBasis);
                regionalEffectiveBasisP =
                    copy(state_->femRegionalEffectiveBasis);
                regionalLinearizationNodes =
                    copy(state_->femRegionalLinearizationNodes);
                regionalLinearizationMaterialState =
                    copy(state_->femRegionalLinearizationMaterialState);
                regionalLinearizationSchedulerExponent =
                    copy(state_->femRegionalLinearizationSchedulerExponent);
                regionalLinearizationLocalFHigh =
                    copy(state_->femRegionalLinearizationLocalFHigh);
                regionalLinearizationLocalFLow =
                    copy(state_->femRegionalLinearizationLocalFLow);
                regionalOperatorAP = copy(state_->femRegionalAP);
                regionalPivotedRAP = copy(state_->femRegionalCoarseMatrix);
                regionalPivots = copy(state_->femRegionalCoarsePivots);
                regionalFactorValid = copy(state_->femRegionalCoarseValid);
                if (state_->mixedSolverValue.executionBudgets.z == 3u ||
                    state_->mixedSolverValue.executionBudgets.z == 4u)
                    regionalNodeBlockInverse =
                        copy(state_->femRegionalNodeBlockInverse);
                regionalDiagnosticsMessage = "captured";
            }
        }
        if (contactFailures == nil || particles == nil || femNodes == nil ||
            particleMaterialState == nil || femMaterialState == nil ||
            femFields == nil || vascularState == nil || vascularClock == nil || solverCertificates == nil ||
            statuses == nil ||
            mpmActiveNodeIndices == nil || mpmNodeToActive == nil ||
            mpmActiveNodeCounts == nil ||
            rigidGeneralizedCandidate == nil ||
            learnedWeights == nil || learnedRevision == nil ||
            topologyNodes == nil || topologyTetrahedra == nil ||
            cohesiveFaces == nil || punctureChannels == nil ||
            topologyStates == nil || contactHistories == nil ||
            humanSupportHistories == nil ||
            humanSupportConsequences == nil ||
            deformableContactHistories == nil ||
            adaptive == nil || schedulers == nil || reactions == nil ||
            rigidStates == nil ||
            (state_->captureDiagnostics && contactSamples == nil) ||
            (regionalDiagnosticsMessage == "captured" &&
             (regionalBasisP == nil || regionalEffectiveBasisP == nil ||
              regionalLinearizationNodes == nil ||
              regionalLinearizationMaterialState == nil ||
              regionalLinearizationSchedulerExponent == nil ||
              regionalLinearizationLocalFHigh == nil ||
              regionalLinearizationLocalFLow == nil ||
              regionalOperatorAP == nil ||
              regionalPivotedRAP == nil || regionalPivots == nil ||
              regionalFactorValid == nil)) ||
            identification == nil || environmentParameters == nil) {
            snapshot.message = "failed to allocate Matter diagnostic readback";
            return snapshot;
        }
        id<MTLCommandBuffer> commandBuffer = [state_->queue commandBuffer];
        id<MTLBlitCommandEncoder> blit = [commandBuffer blitCommandEncoder];
        if (commandBuffer == nil || blit == nil) {
            snapshot.message = "failed to create Matter diagnostic readback command";
            return snapshot;
        }
        const auto encodeCopy = [&](id<MTLBuffer> source, id<MTLBuffer> target) {
            if (source.length != 0u) {
                [blit copyFromBuffer:source sourceOffset:0u
                              toBuffer:target destinationOffset:0u
                                  size:source.length];
            }
        };
        encodeCopy(state_->deformableContactFailures, contactFailures);
        encodeCopy(state_->particleAccepted, particles);
        encodeCopy(state_->femAccepted, femNodes);
        encodeCopy(
            state_->particleMaterialStateAccepted,
            particleMaterialState
        );
        encodeCopy(state_->femMaterialStateAccepted, femMaterialState);
        encodeCopy(state_->femFieldsAccepted, femFields);
        encodeCopy(state_->vascularAccepted, vascularState);
        encodeCopy(state_->vascularClockAccepted, vascularClock);
        encodeCopy(state_->solverCertificates, solverCertificates);
        encodeCopy(state_->statuses, statuses);
        encodeCopy(state_->mpmActiveNodeIndices, mpmActiveNodeIndices);
        encodeCopy(state_->mpmNodeToActive, mpmNodeToActive);
        encodeCopy(state_->mpmActiveNodeCounts, mpmActiveNodeCounts);
        encodeCopy(
            state_->coupledGeneralizedCandidate,
            rigidGeneralizedCandidate);
        encodeCopy(state_->learnedWeightsAccepted, learnedWeights);
        encodeCopy(state_->learnedRevisionAccepted, learnedRevision);
        encodeCopy(state_->femTopologyNodesAccepted, topologyNodes);
        encodeCopy(state_->femTetrahedraAccepted, topologyTetrahedra);
        encodeCopy(state_->cohesiveFacesAccepted, cohesiveFaces);
        encodeCopy(state_->punctureChannelsAccepted, punctureChannels);
        encodeCopy(state_->topologyStatesAccepted, topologyStates);
        encodeCopy(state_->contactHistoriesAccepted, contactHistories);
        encodeCopy(
            state_->humanSupportHistoriesAccepted,
            humanSupportHistories);
        encodeCopy(
            state_->humanSupportConsequencesAccepted,
            humanSupportConsequences);
        encodeCopy(
            state_->deformableContactHistoriesAccepted,
            deformableContactHistories);
        encodeCopy(state_->adaptive, adaptive);
        encodeCopy(state_->schedulers, schedulers);
        encodeCopy(state_->frameReactions, reactions);
        encodeCopy(state_->rigidStates, rigidStates);
        if (state_->captureDiagnostics) {
            encodeCopy(state_->contactSamples, contactSamples);
        }
        if (regionalDiagnosticsMessage == "captured") {
            encodeCopy(state_->femRegionalBasis, regionalBasisP);
            encodeCopy(state_->femRegionalEffectiveBasis,
                       regionalEffectiveBasisP);
            encodeCopy(state_->femRegionalLinearizationNodes,
                       regionalLinearizationNodes);
            encodeCopy(state_->femRegionalLinearizationMaterialState,
                       regionalLinearizationMaterialState);
            encodeCopy(state_->femRegionalLinearizationSchedulerExponent,
                       regionalLinearizationSchedulerExponent);
            encodeCopy(state_->femRegionalLinearizationLocalFHigh,
                       regionalLinearizationLocalFHigh);
            encodeCopy(state_->femRegionalLinearizationLocalFLow,
                       regionalLinearizationLocalFLow);
            encodeCopy(state_->femRegionalAP, regionalOperatorAP);
            encodeCopy(state_->femRegionalCoarseMatrix, regionalPivotedRAP);
            encodeCopy(state_->femRegionalCoarsePivots, regionalPivots);
            encodeCopy(state_->femRegionalCoarseValid, regionalFactorValid);
            if (state_->mixedSolverValue.executionBudgets.z == 3u ||
                state_->mixedSolverValue.executionBudgets.z == 4u)
                encodeCopy(state_->femRegionalNodeBlockInverse,
                           regionalNodeBlockInverse);
        }
        encodeCopy(state_->identificationDistributions, identification);
        encodeCopy(state_->environmentParameters, environmentParameters);
        [blit endEncoding];
        [commandBuffer commit];
        [commandBuffer waitUntilCompleted];
        if (commandBuffer.status != MTLCommandBufferStatusCompleted) {
            snapshot.message = "Matter diagnostic readback command failed: " +
                errorString(commandBuffer.error);
            return snapshot;
        }
        const auto read = [](id<MTLBuffer> buffer, auto& values) {
            using Value = typename std::decay_t<decltype(values)>::value_type;
            values.resize(buffer.length / sizeof(Value));
            if (!values.empty()) {
                std::memcpy(
                    values.data(),
                    buffer.contents,
                    values.size() * sizeof(Value)
                );
            }
        };
        const auto readCount = [](id<MTLBuffer> buffer, auto& values,
                                  const std::size_t count) {
            using Value = typename std::decay_t<decltype(values)>::value_type;
            values.resize(count);
            if (count != 0u) {
                const std::size_t bytes = count * sizeof(Value);
                if (bytes > buffer.length) {
                    values.clear();
                    return;
                }
                std::memcpy(values.data(), buffer.contents, bytes);
            }
        };
        read(particles, snapshot.particles);
        read(femNodes, snapshot.femNodes);
        snapshot.materialStateStride = state_->dispatch.materialStateStride;
        read(particleMaterialState, snapshot.particleMaterialState);
        read(femMaterialState, snapshot.femMaterialState);
        read(femFields, snapshot.femFields);
        readCount(vascularState, snapshot.vascularState,
            static_cast<std::size_t>(state_->dispatch.environmentCount) *
                state_->vascularValue.layout.ranges.z);
        readCount(vascularClock, snapshot.vascularClock,
            state_->vascularValue.layout.ranges.z == 0u ? 0u : state_->dispatch.environmentCount);
        read(solverCertificates, snapshot.solverCertificates);
        readCount(
            statuses,
            snapshot.statuses,
            state_->dispatch.environmentCount
        );
        readCount(
            mpmActiveNodeIndices, snapshot.mpmActiveNodeIndices,
            static_cast<std::size_t>(state_->dispatch.environmentCount) *
                state_->dispatch.mpmActiveNodeCapacity);
        readCount(
            mpmNodeToActive, snapshot.mpmNodeToActive,
            static_cast<std::size_t>(state_->dispatch.environmentCount) *
                state_->dispatch.gridNodeCount);
        readCount(
            mpmActiveNodeCounts, snapshot.mpmActiveNodeCounts,
            state_->dispatch.environmentCount);
        readCount(
            rigidGeneralizedCandidate,
            snapshot.rigidGeneralizedCandidate,
            static_cast<std::size_t>(state_->dispatch.environmentCount) *
                state_->dispatch.rigidGeneralizedCapacity);
        read(learnedWeights, snapshot.learnedWeights);
        snapshot.learnedWeightRevision =
            *static_cast<const std::uint32_t*>(learnedRevision.contents);
        read(topologyNodes, snapshot.femTopologyNodes);
        read(topologyTetrahedra, snapshot.femTopologyTetrahedra);
        read(cohesiveFaces, snapshot.cohesiveFaces);
        read(punctureChannels, snapshot.punctureChannels);
        read(topologyStates, snapshot.topologyStates);
        for (const NMFEMTopologyStateGPU& topology : snapshot.topologyStates)
            snapshot.allocationGeneration = std::max(
                snapshot.allocationGeneration, topology.roles.w);
        const std::size_t logicalContactCount =
            static_cast<std::size_t>(state_->dispatch.environmentCount) *
            state_->dispatch.contactPairCount;
        readCount(contactHistories, snapshot.contactHistories,
                  logicalContactCount);
        const std::size_t logicalHumanSupportCount =
            static_cast<std::size_t>(state_->dispatch.environmentCount) *
            state_->humanSupportDispatch.contactCount;
        readCount(
            humanSupportHistories,
            snapshot.humanSupportHistories,
            logicalHumanSupportCount);
        readCount(
            humanSupportConsequences,
            snapshot.humanSupportConsequences,
            logicalHumanSupportCount);
        const std::size_t logicalDeformableContactCount =
            static_cast<std::size_t>(state_->dispatch.environmentCount) *
            state_->dispatch.deformableContactCapacity;
        readCount(
            deformableContactHistories,
            snapshot.deformableContactHistories,
            logicalDeformableContactCount);
        read(adaptive, snapshot.adaptive);
        read(schedulers, snapshot.schedulers);
        read(reactions, snapshot.reactions);
        readCount(
            rigidStates,
            snapshot.rigidStates,
            static_cast<std::size_t>(state_->dispatch.environmentCount) *
                state_->dispatch.rigidProxyCount
        );
        if (state_->captureDiagnostics) {
            read(contactFailures, snapshot.deformableContactFailures);
            readCount(contactSamples, snapshot.contactSamples,
                      logicalContactCount);
        }
        snapshot.femRegionalGalerkinModeCount = regionalModeCount;
        snapshot.femRegionalGalerkinDiagnosticsMessage =
            regionalDiagnosticsMessage;
        if (regionalDiagnosticsMessage == "captured") {
            const std::size_t nodes = state_->dispatch.femNodeCount;
            const std::size_t environments =
                state_->dispatch.environmentCount;
            const std::size_t modes = regionalModeCount;
            readCount(regionalBasisP,
                snapshot.femRegionalGalerkinBasisP, nodes * modes);
            readCount(regionalEffectiveBasisP,
                snapshot.femRegionalGalerkinEffectiveBasisP,
                environments * nodes * modes);
            readCount(regionalLinearizationNodes,
                snapshot.femRegionalGalerkinLinearizationNodes,
                environments * nodes);
            readCount(regionalLinearizationMaterialState,
                snapshot.femRegionalGalerkinLinearizationMaterialState,
                environments * state_->dispatch.tetrahedronCount *
                    state_->dispatch.materialStateStride);
            readCount(regionalLinearizationSchedulerExponent,
                snapshot.femRegionalGalerkinLinearizationSchedulerExponent,
                environments * state_->dispatch.tetrahedronCount);
            readCount(regionalLinearizationLocalFHigh,
                snapshot.femRegionalGalerkinLinearizationLocalFHigh,
                environments * state_->dispatch.tetrahedronCount * 3u);
            readCount(regionalLinearizationLocalFLow,
                snapshot.femRegionalGalerkinLinearizationLocalFLow,
                environments * state_->dispatch.tetrahedronCount * 3u);
            readCount(regionalOperatorAP,
                snapshot.femRegionalGalerkinOperatorAP,
                environments * nodes * modes);
            readCount(regionalPivotedRAP,
                snapshot.femRegionalGalerkinPivotedRAP,
                environments * modes * modes);
            readCount(regionalPivots,
                snapshot.femRegionalGalerkinPivots,
                environments * modes);
            readCount(regionalFactorValid,
                snapshot.femRegionalGalerkinFactorValid, environments);
            if (state_->mixedSolverValue.executionBudgets.z == 3u ||
                state_->mixedSolverValue.executionBudgets.z == 4u)
                readCount(regionalNodeBlockInverse,
                    snapshot.femRegionalGalerkinNodeBlockInverse,
                    environments * nodes * 3u);
            snapshot.femRegionalGalerkinDiagnosticsAvailable =
                snapshot.femRegionalGalerkinBasisP.size() == nodes * modes &&
                snapshot.femRegionalGalerkinEffectiveBasisP.size() ==
                    environments * nodes * modes &&
                snapshot.femRegionalGalerkinLinearizationNodes.size() ==
                    environments * nodes &&
                snapshot.femRegionalGalerkinLinearizationMaterialState.size() ==
                    environments * state_->dispatch.tetrahedronCount *
                        state_->dispatch.materialStateStride &&
                snapshot.femRegionalGalerkinLinearizationSchedulerExponent.size() ==
                    environments * state_->dispatch.tetrahedronCount &&
                snapshot.femRegionalGalerkinLinearizationLocalFHigh.size() ==
                    environments * state_->dispatch.tetrahedronCount * 3u &&
                snapshot.femRegionalGalerkinLinearizationLocalFLow.size() ==
                    environments * state_->dispatch.tetrahedronCount * 3u &&
                snapshot.femRegionalGalerkinOperatorAP.size() ==
                    environments * nodes * modes &&
                snapshot.femRegionalGalerkinPivotedRAP.size() ==
                    environments * modes * modes &&
                snapshot.femRegionalGalerkinPivots.size() ==
                    environments * modes &&
                snapshot.femRegionalGalerkinFactorValid.size() ==
                    environments &&
                (state_->mixedSolverValue.executionBudgets.z != 3u ||
                 snapshot.femRegionalGalerkinNodeBlockInverse.size() ==
                    environments * nodes * 3u);
            if (!snapshot.femRegionalGalerkinDiagnosticsAvailable) {
                snapshot.femRegionalGalerkinDiagnosticsMessage =
                    "regional Galerkin diagnostic readback size mismatch";
            }
        }
        read(identification, snapshot.identification);
        read(environmentParameters, snapshot.environmentParameters);
        snapshot.available = true;
    }
    return snapshot;
}

void* Runtime::eventBuffer() const noexcept {
    return state_ ? (__bridge void*)state_->events : nullptr;
}

void* Runtime::statusBuffer() const noexcept {
    return state_ ? (__bridge void*)state_->statuses : nullptr;
}

void* Runtime::femConstraintReactionBuffer() const noexcept {
    return state_ ? (__bridge void*)state_->femConstraintReactions : nullptr;
}

void* Runtime::femConstraintContactForceBuffer() const noexcept {
    return state_ ? (__bridge void*)state_->femConstraintContactForces : nullptr;
}

void* Runtime::femMechanicalResidualBuffer() const noexcept {
    return state_ ? (__bridge void*)state_->femResidual : nullptr;
}

void* Runtime::femAcceptedNodeBuffer() const noexcept {
    return state_ ? (__bridge void*)state_->femAccepted : nullptr;
}

void* Runtime::parameterBuffer() const noexcept {
    return state_ ? (__bridge void*)state_->environmentParameters : nullptr;
}

void* Runtime::identificationLossBuffer() const noexcept {
    return state_ ? (__bridge void*)state_->identificationLosses : nullptr;
}

} // namespace numi::matter
